QUESTIONS.push(

  // ================= Algorithm Analysis (50) =================
  { id: "aa-01", topic: "algo-analysis", q: "Algorithm analysis primarily measures how an algorithm's resource use grows as a function of:", options: ["The programming language", "The input size n", "The CPU clock speed", "The number of comments"], answer: 1, exp: "Analysis is about the growth rate of running time / space with respect to input size, independent of hardware and language." },
  { id: "aa-02", topic: "algo-analysis", q: "The RAM (Random Access Machine) model assumes each basic operation costs:", options: ["Variable time", "Constant (unit) time", "O(log n) time", "Time proportional to operand size"], answer: 1, exp: "The RAM model charges 1 for each simple operation (arithmetic, comparison, array access), enabling machine-independent analysis." },
  { id: "aa-03", topic: "algo-analysis", q: "Which is generally the MOST important factor in algorithm performance for large inputs?", options: ["Constant factors", "The order of growth (asymptotic complexity)", "Lines of code", "Variable names"], answer: 1, exp: "For large n, a lower-order-of-growth algorithm eventually wins regardless of constant factors." },
  { id: "aa-04", topic: "algo-analysis", q: "Counting the number of times the innermost statement executes is a way to find:", options: ["Space complexity", "The running-time function T(n)", "The best programming language", "Cache misses"], answer: 1, exp: "Summing the executions of the dominant operation yields T(n), which is then expressed asymptotically." },
  { id: "aa-05", topic: "algo-analysis", q: "For nested loops 'for i in 1..n { for j in 1..n {...} }', the body executes:", options: ["n times", "2n times", "n^2 times", "n log n times"], answer: 2, exp: "Each of n outer iterations runs n inner iterations." },
  { id: "aa-06", topic: "algo-analysis", q: "A loop 'for (i = 1; i <= n; i *= 2)' runs how many times?", options: ["n", "n/2", "log2 n", "sqrt n"], answer: 2, exp: "i doubles each step, reaching n after about log2(n) iterations." },
  { id: "aa-07", topic: "algo-analysis", q: "The running time of 'for (i=0;i<n;i++) for (j=0;j<i;j++) op;' is:", options: ["O(n)", "O(n log n)", "O(n^2)", "O(2^n)"], answer: 2, exp: "Total = 0 + 1 + 2 + ... + (n-1) = n(n-1)/2 = O(n^2)." },
  { id: "aa-08", topic: "algo-analysis", q: "Empirical (experimental) analysis of an algorithm involves:", options: ["Proving a recurrence", "Measuring actual run time on real inputs", "Counting operations by hand", "Reading the pseudocode"], answer: 1, exp: "Experimental analysis times implementations; it is machine-dependent and limited to the inputs tested." },
  { id: "aa-09", topic: "algo-analysis", q: "Which sum is Theta(n^2)?", options: ["1 + 2 + ... + n", "1 + 1/2 + 1/3 + ... + 1/n", "2^0 + 2^1 + ... + 2^n", "n + n + ... (log n terms)"], answer: 0, exp: "The arithmetic series 1+2+...+n = n(n+1)/2 = Theta(n^2)." },
  { id: "aa-10", topic: "algo-analysis", q: "The harmonic series H(n) = 1 + 1/2 + ... + 1/n is:", options: ["Theta(1)", "Theta(log n)", "Theta(n)", "Theta(n log n)"], answer: 1, exp: "H(n) is approximately ln(n) + 0.577, so Theta(log n)." },
  { id: "aa-11", topic: "algo-analysis", q: "Amortized analysis gives:", options: ["The cost of the single worst operation", "The average cost per operation over a worst-case sequence of operations", "The best-case cost", "A probabilistic average"], answer: 1, exp: "Amortized analysis bounds the total cost of a sequence and divides by the count — no probability involved." },
  { id: "aa-12", topic: "algo-analysis", q: "The aggregate, accounting, and potential methods are three techniques of:", options: ["Asymptotic notation", "Amortized analysis", "Recurrence solving", "Loop invariants"], answer: 1, exp: "All three are ways to compute amortized cost; the potential method uses a potential function Phi." },
  { id: "aa-13", topic: "algo-analysis", q: "A dynamic array's push is amortized O(1) because:", options: ["It never resizes", "The occasional O(n) resize is spread over many O(1) pushes via doubling", "Resizing is free", "It uses a linked list"], answer: 1, exp: "n pushes cost n + n/2 + n/4 + ... < 2n total, so O(1) amortized." },
  { id: "aa-14", topic: "algo-analysis", q: "A loop invariant is used to prove an algorithm's:", options: ["Running time", "Correctness", "Space usage", "Cache behavior"], answer: 1, exp: "You show the invariant holds at initialization, is maintained each iteration, and at termination implies the desired result." },
  { id: "aa-15", topic: "algo-analysis", q: "T(n) = T(n-1) + n, T(0) = 0 solves to:", options: ["Theta(n)", "Theta(n log n)", "Theta(n^2)", "Theta(2^n)"], answer: 2, exp: "Unrolling gives n + (n-1) + ... + 1 = n(n+1)/2 = Theta(n^2). This is selection/insertion sort's worst case." },
  { id: "aa-16", topic: "algo-analysis", q: "The 'dominant term' rule says for T(n) = 3n^2 + 100n + 5000, the growth is:", options: ["O(1)", "O(n)", "O(n^2)", "O(n^3)"], answer: 2, exp: "The highest-order term n^2 dominates for large n; constants and lower terms are dropped." },
  { id: "aa-17", topic: "algo-analysis", q: "Which two algorithms have the same asymptotic time but very different constants?", options: ["Merge sort and bubble sort", "Merge sort and quicksort (both O(n log n) average)", "Linear search and binary search", "DFS and Dijkstra"], answer: 1, exp: "Both are n log n on average, but quicksort's smaller constant and cache friendliness usually make it faster in practice." },
  { id: "aa-18", topic: "algo-analysis", q: "Analysis that assumes inputs are drawn from a probability distribution is called:", options: ["Worst-case analysis", "Average-case (expected) analysis", "Amortized analysis", "Asymptotic analysis"], answer: 1, exp: "Average-case analysis computes E[T(n)] over a distribution of inputs." },
  { id: "aa-19", topic: "algo-analysis", q: "Randomized quicksort's O(n log n) expected time comes from:", options: ["The input being random", "Random pivot choice making bad splits unlikely regardless of input", "Using extra memory", "Sorting twice"], answer: 1, exp: "Randomization moves the 'randomness' from the input to the algorithm, so no fixed input is consistently bad." },
  { id: "aa-20", topic: "algo-analysis", q: "The number of comparisons to find the max of n elements is:", options: ["1", "log n", "n - 1", "n^2"], answer: 2, exp: "You must compare the current max with each of the other n-1 elements at least once." },
  { id: "aa-21", topic: "algo-analysis", q: "Finding both the min and max of n elements can be done in about:", options: ["2n comparisons", "3n/2 comparisons", "n log n comparisons", "n^2 comparisons"], answer: 1, exp: "Process elements in pairs: 1 comparison to order the pair, then 1 each against current min and max => 3 per 2 elements." },
  { id: "aa-22", topic: "algo-analysis", q: "The lower bound for comparison-based sorting is:", options: ["Omega(n)", "Omega(n log n)", "Omega(n^2)", "Omega(log n)"], answer: 1, exp: "A decision tree with n! leaves has height >= log2(n!) = Omega(n log n)." },
  { id: "aa-23", topic: "algo-analysis", q: "Which describes 'tight bound'?", options: ["Big-O only", "Big-Omega only", "Theta — both an upper and matching lower bound", "little-o"], answer: 2, exp: "T(n) = Theta(f(n)) means f is both an asymptotic upper and lower bound." },
  { id: "aa-24", topic: "algo-analysis", q: "The running time of computing the n-th Fibonacci number with bottom-up DP is:", options: ["O(2^n)", "O(n)", "O(log n)", "O(n^2)"], answer: 1, exp: "One pass filling an array (or two variables) of size n, O(1) work each." },
  { id: "aa-25", topic: "algo-analysis", q: "Computing x^n by repeated squaring takes how many multiplications?", options: ["n", "n - 1", "Theta(log n)", "Theta(n log n)"], answer: 2, exp: "x^n = (x^(n/2))^2 halves the exponent each step." },
  { id: "aa-26", topic: "algo-analysis", q: "The time for matrix multiplication of two n x n matrices by the schoolbook method is:", options: ["O(n^2)", "O(n^3)", "O(n^2 log n)", "O(n!)"], answer: 1, exp: "n^2 output entries, each a dot product of length n. (Strassen's is ~O(n^2.81).)" },
  { id: "aa-27", topic: "algo-analysis", q: "The best-case running time of insertion sort (already sorted input) is:", options: ["O(1)", "O(n)", "O(n log n)", "O(n^2)"], answer: 1, exp: "Each element is compared once with its predecessor and not moved — a single linear pass." },
  { id: "aa-28", topic: "algo-analysis", q: "A polynomial-time algorithm has running time:", options: ["O(2^n)", "O(n^k) for some constant k", "O(n!)", "O(k^n)"], answer: 1, exp: "Polynomial time = bounded by a polynomial in the input size; considered 'efficient' / class P." },
  { id: "aa-29", topic: "algo-analysis", q: "Which growth rate is the fastest-growing?", options: ["n^100", "2^n", "n log n", "n!"], answer: 3, exp: "n! grows faster than 2^n, which grows faster than any polynomial." },
  { id: "aa-30", topic: "algo-analysis", q: "Which growth rate is the slowest-growing (for large n)?", options: ["log log n", "log n", "sqrt n", "n"], answer: 0, exp: "log log n < log n < sqrt n < n." },
  { id: "aa-31", topic: "algo-analysis", q: "The 'size' of the input for a graph algorithm is usually measured as:", options: ["Just |V|", "Just |E|", "|V| + |E|", "|V| * |E|"], answer: 2, exp: "Both the vertex count and edge count contribute to the input size and appear in the complexity." },
  { id: "aa-32", topic: "algo-analysis", q: "For a number n given in binary, the input size is:", options: ["n", "n^2", "Theta(log n) bits", "sqrt n"], answer: 2, exp: "An integer n needs about log2(n) bits; an algorithm 'linear in n' is actually exponential in the input size." },
  { id: "aa-33", topic: "algo-analysis", q: "Trial-division primality testing of n runs in O(sqrt n) arithmetic operations, which in terms of input size (b bits) is:", options: ["Polynomial", "Exponential (2^(b/2))", "Logarithmic", "Constant"], answer: 1, exp: "sqrt(n) = 2^(b/2) is exponential in the number of bits b — a classic 'pseudo-polynomial' pitfall." },
  { id: "aa-34", topic: "algo-analysis", q: "An algorithm whose running time depends on the numeric VALUE of an input (not just its size in bits) is called:", options: ["Polynomial", "Pseudo-polynomial", "Sub-linear", "Logarithmic"], answer: 1, exp: "E.g. the O(nW) knapsack DP: polynomial in n and W's value but exponential in W's bit length." },
  { id: "aa-35", topic: "algo-analysis", q: "The master theorem is used to solve recurrences of the form:", options: ["T(n) = T(n-1) + f(n)", "T(n) = a T(n/b) + f(n)", "T(n) = T(n/2) + T(n/3) + n", "Any recurrence"], answer: 1, exp: "It handles divide-and-conquer recurrences with a subproblems of size n/b." },
  { id: "aa-36", topic: "algo-analysis", q: "In T(n) = a T(n/b) + f(n), the 'critical exponent' is:", options: ["a / b", "log_b(a)", "b^a", "a + b"], answer: 1, exp: "Compare f(n) with n^(log_b a) to choose the master-theorem case." },
  { id: "aa-37", topic: "algo-analysis", q: "T(n) = 2T(n/2) + O(1) solves to:", options: ["O(log n)", "O(n)", "O(n log n)", "O(n^2)"], answer: 1, exp: "Master theorem case 1: f(n)=O(1) is polynomially smaller than n^(log2 2)=n, so T(n)=Theta(n). (E.g. tree traversal / heapify recursion structure.)" },
  { id: "aa-38", topic: "algo-analysis", q: "The recursion-tree method estimates a recurrence's cost by:", options: ["Guessing and checking", "Summing the work at each level of the recursion tree", "Using calculus", "Ignoring lower levels"], answer: 1, exp: "Add the cost per level and multiply by the number of levels (or sum a geometric series)." },
  { id: "aa-39", topic: "algo-analysis", q: "The substitution method for recurrences:", options: ["Substitutes n = 2^k", "Guesses a bound and proves it by induction", "Draws a tree", "Applies the master theorem"], answer: 1, exp: "You guess T(n) = O(g(n)) and verify the inductive step and base case." },
  { id: "aa-40", topic: "algo-analysis", q: "Which best describes 'sub-linear' time?", options: ["O(n)", "o(n) — the algorithm does not even read all of its input", "O(n log n)", "O(1) only"], answer: 1, exp: "Sub-linear algorithms (e.g. binary search, or sampling-based approximations) inspect only part of the input." },
  { id: "aa-41", topic: "algo-analysis", q: "The time complexity of building a binary heap from n elements is analyzed as O(n) using:", options: ["A single loop count", "The sum over levels of (nodes at level) * (height below), a converging series", "The master theorem", "Amortization"], answer: 1, exp: "sum_{h} (n / 2^(h+1)) * h converges to 2n, hence O(n)." },
  { id: "aa-42", topic: "algo-analysis", q: "Which statement about constant factors is TRUE?", options: ["They never matter", "They are ignored asymptotically but can dominate for realistic input sizes", "They change the order of growth", "They are always 1"], answer: 1, exp: "For small/medium n a 'worse' O(n^2) algorithm with tiny constants can beat an O(n log n) one." },
  { id: "aa-43", topic: "algo-analysis", q: "The number of leaf nodes in the recursion tree of merge sort on n elements is:", options: ["log n", "n", "n/2", "2^n"], answer: 1, exp: "The tree bottoms out at n subproblems of size 1." },
  { id: "aa-44", topic: "algo-analysis", q: "'Work' and 'span' are metrics used to analyze:", options: ["Sequential algorithms", "Parallel algorithms", "Cache performance", "I/O complexity"], answer: 1, exp: "Work = total operations; span (depth) = longest dependency chain; parallelism = work / span." },
  { id: "aa-45", topic: "algo-analysis", q: "The external-memory (I/O) model counts:", options: ["CPU instructions", "Block transfers between disk and main memory", "Comparisons only", "Recursive calls"], answer: 1, exp: "For big data, disk I/O dominates; algorithms are analyzed by number of B-sized block transfers." },
  { id: "aa-46", topic: "algo-analysis", q: "Which is a correct ranking from slowest to fastest growth?", options: ["log n, n, n log n, n^2, 2^n", "n, log n, n^2, 2^n, n log n", "2^n, n^2, n log n, n, log n", "n log n, n, log n, n^2, 2^n"], answer: 0, exp: "Standard hierarchy: 1 < log n < n < n log n < n^2 < n^3 < 2^n < n!." },
  { id: "aa-47", topic: "algo-analysis", q: "If T(n) = 4T(n/2) + n, then T(n) is:", options: ["O(n)", "O(n log n)", "O(n^2)", "O(n^2 log n)"], answer: 2, exp: "n^(log2 4) = n^2 dominates f(n)=n, so master theorem case 1: Theta(n^2)." },
  { id: "aa-48", topic: "algo-analysis", q: "The purpose of analyzing an algorithm before coding it is to:", options: ["Impress reviewers", "Predict scalability and compare design choices without implementing all of them", "Satisfy a compiler", "Reduce the number of variables"], answer: 1, exp: "Asymptotic analysis lets you reject non-scalable designs early." },
  { id: "aa-49", topic: "algo-analysis", q: "Two algorithms are asymptotically equivalent if:", options: ["They have the same code length", "Each is Big-O of the other (i.e. both Theta of the same function)", "They run on the same machine", "They use the same language"], answer: 1, exp: "Mutual O-bounds mean the same order of growth, Theta." },
  { id: "aa-50", topic: "algo-analysis", q: "The running time T(n) = n + n/2 + n/4 + ... + 1 sums to:", options: ["Theta(log n)", "Theta(n)", "Theta(n log n)", "Theta(n^2)"], answer: 1, exp: "A geometric series with ratio 1/2 sums to < 2n, so Theta(n) — the analysis behind linear-time heapify and the KMP failure function." },

  // ================= Asymptotic Notation (50) =================
  { id: "an-01", topic: "algo-asymptotic", q: "f(n) = O(g(n)) means:", options: ["f grows exactly like g", "f grows no faster than g (asymptotic upper bound)", "f grows at least as fast as g", "f = g for all n"], answer: 1, exp: "There exist c > 0 and n0 such that f(n) <= c*g(n) for all n >= n0." },
  { id: "an-02", topic: "algo-asymptotic", q: "f(n) = Omega(g(n)) means:", options: ["Upper bound", "Lower bound: f grows at least as fast as g", "Tight bound", "f is unbounded"], answer: 1, exp: "There exist c > 0 and n0 with f(n) >= c*g(n) for n >= n0." },
  { id: "an-03", topic: "algo-asymptotic", q: "f(n) = Theta(g(n)) iff:", options: ["f = O(g) only", "f = Omega(g) only", "f = O(g) AND f = Omega(g)", "f = o(g)"], answer: 2, exp: "Theta is a tight bound: g is both an asymptotic upper and lower bound for f." },
  { id: "an-04", topic: "algo-asymptotic", q: "3n^2 + 5n + 2 is:", options: ["O(n)", "Theta(n^2)", "Theta(n^3)", "O(log n)"], answer: 1, exp: "Drop lower terms and constants: the growth is exactly n^2." },
  { id: "an-05", topic: "algo-asymptotic", q: "Is n^2 = O(n^3)?", options: ["Yes", "No", "Only for small n", "Undefined"], answer: 0, exp: "n^2 grows no faster than n^3, so it is a valid (loose) upper bound." },
  { id: "an-06", topic: "algo-asymptotic", q: "Is n^3 = O(n^2)?", options: ["Yes", "No", "Yes, with a large constant", "Only asymptotically"], answer: 1, exp: "No constant c makes n^3 <= c*n^2 for all large n." },
  { id: "an-07", topic: "algo-asymptotic", q: "little-o, f(n) = o(g(n)), means:", options: ["f <= c*g for some c", "f/g -> 0 as n -> infinity (strictly smaller growth)", "f = Theta(g)", "f >= g"], answer: 1, exp: "little-o is a strict upper bound: g dominates f in the limit." },
  { id: "an-08", topic: "algo-asymptotic", q: "Which is TRUE? log(n!) = ?", options: ["Theta(n)", "Theta(n log n)", "Theta(n^2)", "Theta(log n)"], answer: 1, exp: "By Stirling's approximation, log(n!) = Theta(n log n)." },
  { id: "an-09", topic: "algo-asymptotic", q: "2^(n+1) is:", options: ["Theta(2^n)", "Theta(n * 2^n)", "Theta(4^n)", "o(2^n)"], answer: 0, exp: "2^(n+1) = 2 * 2^n, and constant multiples do not change Theta." },
  { id: "an-10", topic: "algo-asymptotic", q: "2^(2n) compared to 2^n:", options: ["Theta(2^n)", "= (2^n)^2, i.e. Theta(4^n) — NOT Theta(2^n)", "o(2^n)", "Theta(n 2^n)"], answer: 1, exp: "2^(2n) = 4^n grows much faster; exponents are not constant factors." },
  { id: "an-11", topic: "algo-asymptotic", q: "log base a n vs log base b n (a, b > 1):", options: ["Different orders of growth", "Differ only by a constant factor, so same Theta", "One is O of the other but not vice versa", "Incomparable"], answer: 1, exp: "log_a n = log_b n / log_b a, a constant factor — this is why the base is dropped in O-notation." },
  { id: "an-12", topic: "algo-asymptotic", q: "n log n vs n^1.01:", options: ["n log n grows faster", "n^1.01 grows faster (any positive power of n beats a polylog factor)", "Same growth", "Incomparable"], answer: 1, exp: "For any epsilon > 0, n^epsilon dominates (log n)^k; so n^1.01 = n * n^0.01 beats n log n." },
  { id: "an-13", topic: "algo-asymptotic", q: "Which is the correct asymptotic ordering (slow to fast)?", options: ["1, log n, n, n log n, n^2, 2^n, n!", "1, n, log n, n^2, 2^n, n log n, n!", "log n, 1, n, 2^n, n!, n^2", "n!, 2^n, n^2, n log n, n, log n, 1"], answer: 0, exp: "This is the standard growth hierarchy." },
  { id: "an-14", topic: "algo-asymptotic", q: "If f(n) = O(g(n)) and g(n) = O(h(n)), then:", options: ["f(n) = O(h(n)) (transitivity)", "h(n) = O(f(n))", "f(n) = Theta(h(n))", "Nothing can be concluded"], answer: 0, exp: "Big-O is transitive." },
  { id: "an-15", topic: "algo-asymptotic", q: "The sum O(n) + O(n^2) is:", options: ["O(n)", "O(n^2)", "O(n^3)", "O(n log n)"], answer: 1, exp: "The dominant term wins: O(n^2)." },
  { id: "an-16", topic: "algo-asymptotic", q: "O(n) * O(log n) is:", options: ["O(n)", "O(log n)", "O(n log n)", "O(n^2)"], answer: 2, exp: "Multiplying bounds (e.g. n iterations each doing a binary search) gives O(n log n)." },
  { id: "an-17", topic: "algo-asymptotic", q: "Which statement about O(1) is TRUE?", options: ["It means exactly one operation", "It means the cost is bounded by a constant independent of n", "It means the fastest possible", "It means no operations"], answer: 1, exp: "Constant time — the bound does not grow with input size, though the constant may be large." },
  { id: "an-18", topic: "algo-asymptotic", q: "'The worst case of quicksort is O(n log n)' is:", options: ["Correct", "Technically true but misleading — the tight worst-case bound is Theta(n^2)", "False, worst case is O(n)", "Always the right way to state it"], answer: 1, exp: "O(n log n) is not wrong as an upper bound only if it held — it does not; worst case is Theta(n^2). People often misuse O for 'tight'." },
  { id: "an-19", topic: "algo-asymptotic", q: "f(n) = 100 is:", options: ["O(1)", "O(n)", "O(100n)", "Theta(n)"], answer: 0, exp: "A constant function is O(1) (and also O(n), but O(1) is the tight bound)." },
  { id: "an-20", topic: "algo-asymptotic", q: "sqrt(n) = n^0.5 is:", options: ["O(log n)", "O(n) but not O(log n); it is o(n)", "Theta(n)", "Omega(n)"], answer: 1, exp: "sqrt n grows faster than log n, slower than n (little-o of n)." },
  { id: "an-21", topic: "algo-asymptotic", q: "Which pair are NOT asymptotically equal?", options: ["n and n + 1000", "2n and n", "n^2 and n^2 + n", "n and n log n"], answer: 3, exp: "n log n grows strictly faster than n; the others differ only by constants or lower-order terms." },
  { id: "an-22", topic: "algo-asymptotic", q: "If T(n) = Theta(n^2), which is FALSE?", options: ["T(n) = O(n^2)", "T(n) = Omega(n^2)", "T(n) = O(n^3)", "T(n) = O(n)"], answer: 3, exp: "T(n) grows like n^2, so it cannot be bounded above by n." },
  { id: "an-23", topic: "algo-asymptotic", q: "n^(1/log n) is:", options: ["Theta(n)", "Theta(1) (it equals a constant, ~2.718)", "Theta(log n)", "Unbounded"], answer: 1, exp: "n^(1/log n) = 2^(log n / log n) = 2 (base 2), a constant." },
  { id: "an-24", topic: "algo-asymptotic", q: "The notation f(n) = omega(g(n)) (little-omega) means:", options: ["f = O(g)", "f / g -> infinity (strictly larger growth)", "f = Theta(g)", "f <= g"], answer: 1, exp: "little-omega is the strict lower bound, the dual of little-o." },
  { id: "an-25", topic: "algo-asymptotic", q: "Which of these is the tightest correct bound for the number of subsets of an n-set?", options: ["O(n^2)", "O(n!)", "Theta(2^n)", "Theta(n log n)"], answer: 2, exp: "There are exactly 2^n subsets." },
  { id: "an-26", topic: "algo-asymptotic", q: "log(n^2) is:", options: ["Theta((log n)^2)", "Theta(log n)", "Theta(n)", "Theta(2 log n) which is not simplifiable"], answer: 1, exp: "log(n^2) = 2 log n = Theta(log n)." },
  { id: "an-27", topic: "algo-asymptotic", q: "(log n)^2 vs log(log n):", options: ["Equal", "(log n)^2 grows faster", "log(log n) grows faster", "Incomparable"], answer: 1, exp: "log log n is much smaller than log n, let alone its square." },
  { id: "an-28", topic: "algo-asymptotic", q: "Is 2^n = O(2^(n/2))?", options: ["Yes", "No — 2^n / 2^(n/2) = 2^(n/2) -> infinity", "Yes with constant 2", "Only for even n"], answer: 1, exp: "2^n is exponentially larger than 2^(n/2)." },
  { id: "an-29", topic: "algo-asymptotic", q: "The bound O(n^2) for an algorithm means its running time is:", options: ["Exactly proportional to n^2", "At most proportional to n^2 for large inputs", "At least n^2", "Independent of n"], answer: 1, exp: "Big-O is an upper bound; the algorithm could be faster on some inputs." },
  { id: "an-30", topic: "algo-asymptotic", q: "For polynomials, deg(p) = k implies p(n) = ?", options: ["O(n^(k-1))", "Theta(n^k)", "Theta(k^n)", "O(k n)"], answer: 1, exp: "A degree-k polynomial with positive leading coefficient is Theta(n^k)." },
  { id: "an-31", topic: "algo-asymptotic", q: "n! is:", options: ["O(n^n)", "Omega(n^n)", "Theta(n^n)", "o(2^n)"], answer: 0, exp: "n! < n^n (each of n factors is <= n), and n! grows faster than any c^n, so n! = O(n^n) but not Theta." },
  { id: "an-32", topic: "algo-asymptotic", q: "Which is the correct definition of 'f(n) is polynomially bounded'?", options: ["f(n) = O(2^n)", "f(n) = n^O(1), i.e. f(n) = O(n^k) for some constant k", "f(n) = Theta(n)", "f(n) = Omega(n!)"], answer: 1, exp: "Polynomially bounded means dominated by some fixed power of n." },
  { id: "an-33", topic: "algo-asymptotic", q: "If an algorithm is O(n) and also Omega(n), then it is:", options: ["O(n^2)", "Theta(n)", "o(n)", "Undetermined"], answer: 1, exp: "Matching upper and lower bounds give Theta(n)." },
  { id: "an-34", topic: "algo-asymptotic", q: "The reflexive property holds for:", options: ["little-o (f = o(f))", "Big-O (f = O(f)) and Theta, but NOT little-o", "Only Omega", "None"], answer: 1, exp: "f = O(f) and f = Theta(f) trivially; f = o(f) is false since f/f = 1, not 0." },
  { id: "an-35", topic: "algo-asymptotic", q: "The symmetry property 'f = Theta(g) iff g = Theta(f)' holds for:", options: ["Theta only", "Big-O only", "little-o only", "All of them"], answer: 0, exp: "Only Theta is symmetric; O and Omega are 'transpose-symmetric' (f=O(g) iff g=Omega(f))." },
  { id: "an-36", topic: "algo-asymptotic", q: "Which running time is preferred for an algorithm on huge inputs?", options: ["O(n^2)", "O(n log n)", "O(n^3)", "O(2^n)"], answer: 1, exp: "Lower order of growth scales better; O(n log n) beats the others for large n." },
  { id: "an-37", topic: "algo-asymptotic", q: "The expression max(f(n), g(n)) is:", options: ["Theta(f(n) + g(n))", "Theta(f(n) * g(n))", "o(f + g)", "Theta(min(f,g))"], answer: 0, exp: "max(f,g) <= f+g <= 2 max(f,g), so they are the same Theta." },
  { id: "an-38", topic: "algo-asymptotic", q: "An O(n log log n) algorithm compared to O(n log n):", options: ["Is slower", "Is asymptotically faster", "Same speed", "Only faster for small n"], answer: 1, exp: "log log n grows much slower than log n." },
  { id: "an-39", topic: "algo-asymptotic", q: "Which is the smallest (best) upper bound for insertion sort's running time over all inputs?", options: ["O(n)", "O(n log n)", "O(n^2)", "O(2^n)"], answer: 2, exp: "Its worst case is Theta(n^2), so the tightest universal upper bound is O(n^2)." },
  { id: "an-40", topic: "algo-asymptotic", q: "If f(n) = O(g(n)), then a*f(n) = ? for constant a > 0:", options: ["O(a * g(n)) which is O(g(n))", "O(g(n)^a)", "a * O(g(n)^2)", "Not bounded"], answer: 0, exp: "Constant multiples are absorbed: a*f(n) = O(g(n))." },
  { id: "an-41", topic: "algo-asymptotic", q: "Which is true about e^n and 2^n?", options: ["Same Theta", "e^n = O(2^n)", "2^n = O(e^n) but not vice versa (since e < ... wait) — actually e^n grows faster than 2^n", "Incomparable"], answer: 2, exp: "Since e (2.718) > 2, e^n / 2^n = (e/2)^n -> infinity; e^n is NOT O(2^n)." },
  { id: "an-42", topic: "algo-asymptotic", q: "The running time 'O(V + E)' for graph traversal is an example of a bound that:", options: ["Uses one variable", "Uses two input-size parameters", "Is exponential", "Is amortized"], answer: 1, exp: "Graph complexity is naturally expressed in both |V| and |E|." },
  { id: "an-43", topic: "algo-asymptotic", q: "T(n) = 2^(log2 n) equals:", options: ["n", "log n", "n^2", "2n"], answer: 0, exp: "2 raised to log2(n) is n exactly." },
  { id: "an-44", topic: "algo-asymptotic", q: "n^(log2 3) (from Karatsuba multiplication) is approximately:", options: ["n^1.585", "n^2", "n^0.5", "n^3"], answer: 0, exp: "log2(3) ~ 1.585, so Karatsuba is ~O(n^1.585), better than the O(n^2) schoolbook method." },
  { id: "an-45", topic: "algo-asymptotic", q: "Which is FALSE?", options: ["n = O(n^2)", "n^2 = Omega(n)", "n = Theta(n^2)", "n^2 = O(n^2)"], answer: 2, exp: "n and n^2 have different orders of growth, so n is not Theta(n^2)." },
  { id: "an-46", topic: "algo-asymptotic", q: "The complexity class P is the set of problems solvable in:", options: ["Constant time", "Polynomial time on a deterministic machine", "Exponential time", "Any time"], answer: 1, exp: "P = problems with an O(n^k) deterministic algorithm." },
  { id: "an-47", topic: "algo-asymptotic", q: "The inverse Ackermann function alpha(n) appearing in union-find analysis is:", options: ["O(log n)", "Effectively constant (<= 4) for all practical n", "O(n)", "O(log* n) exactly and no smaller"], answer: 1, exp: "alpha(n) grows so slowly it is <= 4 for any n that could be written down." },
  { id: "an-48", topic: "algo-asymptotic", q: "log*(n) (iterated logarithm) counts:", options: ["log of log of n once", "How many times you must apply log to bring n down to <= 1", "n / log n", "The number of digits"], answer: 1, exp: "log* grows extremely slowly: log*(2^65536) = 5." },
  { id: "an-49", topic: "algo-asymptotic", q: "Two functions f and g with lim f(n)/g(n) = c where 0 < c < infinity satisfy:", options: ["f = o(g)", "f = Theta(g)", "f = omega(g)", "Nothing"], answer: 1, exp: "A finite nonzero limit ratio means the same order of growth." },
  { id: "an-50", topic: "algo-asymptotic", q: "Which best captures why asymptotic notation is used?", options: ["To make code shorter", "To compare algorithm efficiency independent of hardware, language and constant factors, focusing on scalability", "To count exact CPU cycles", "It is required by compilers"], answer: 1, exp: "Asymptotics abstract away machine-specific detail and describe how cost scales with input size." },

  // ================= Space & Time Complexity (50) =================
  { id: "sc-01", topic: "algo-complexity", q: "Space complexity of an algorithm counts:", options: ["Only the input size", "The auxiliary (working) memory, sometimes plus input", "The number of variables in the source", "Disk space only"], answer: 1, exp: "Usually we report auxiliary space — extra memory beyond the input." },
  { id: "sc-02", topic: "algo-complexity", q: "An 'in-place' algorithm uses:", options: ["No memory at all", "O(1) or O(log n) auxiliary space", "O(n) extra space", "Only the heap"], answer: 1, exp: "In-place means constant (or logarithmic) extra space beyond the input array." },
  { id: "sc-03", topic: "algo-complexity", q: "Merge sort's space complexity is:", options: ["O(1)", "O(log n)", "O(n) for the temporary merge buffer", "O(n^2)"], answer: 2, exp: "The standard array merge needs an auxiliary array of size n (plus O(log n) recursion stack)." },
  { id: "sc-04", topic: "algo-complexity", q: "Quicksort's auxiliary space (in-place partition) is:", options: ["O(1)", "O(log n) average for the recursion stack (O(n) worst case)", "O(n)", "O(n log n)"], answer: 1, exp: "Only the recursion stack; balanced splits give O(log n), degenerate splits O(n)." },
  { id: "sc-05", topic: "algo-complexity", q: "Recursive algorithms incur space cost from:", options: ["The heap", "Activation records on the call stack, proportional to recursion depth", "Global variables", "The instruction cache"], answer: 1, exp: "Each pending call keeps a frame; max depth determines stack space." },
  { id: "sc-06", topic: "algo-complexity", q: "Iterative in-order traversal of a binary tree uses space:", options: ["O(1)", "O(h) for the explicit stack (h = height)", "O(n) always", "O(log n) always"], answer: 1, exp: "The stack holds at most one root-to-current path, i.e. O(height)." },
  { id: "sc-07", topic: "algo-complexity", q: "A time-space tradeoff means:", options: ["Time and space are always equal", "Using more memory (e.g. a lookup table) to reduce running time, or vice versa", "Neither can be reduced", "Space is free"], answer: 1, exp: "Memoization, precomputed tables, and hashing trade space for speed." },
  { id: "sc-08", topic: "algo-complexity", q: "The 0/1 knapsack DP with capacity W and n items uses time and space:", options: ["O(n) / O(n)", "O(nW) / O(nW), reducible to O(W) space", "O(2^n) / O(n)", "O(n log n) / O(1)"], answer: 1, exp: "The table is n x W; only the previous row is needed, so space can drop to O(W)." },
  { id: "sc-09", topic: "algo-complexity", q: "Counting sort on n items with key range k uses space:", options: ["O(1)", "O(n + k)", "O(log n)", "O(n^2)"], answer: 1, exp: "A count array of size k plus an output array of size n." },
  { id: "sc-10", topic: "algo-complexity", q: "BFS space complexity on a graph is dominated by:", options: ["O(1)", "The queue and visited set, O(V)", "O(E^2)", "The recursion stack"], answer: 1, exp: "The frontier can contain O(V) vertices; visited marking is O(V)." },
  { id: "sc-11", topic: "algo-complexity", q: "DFS (recursive) space complexity is:", options: ["O(V) for the call stack in the worst case", "O(1)", "O(E)", "O(V^2)"], answer: 0, exp: "A path can be as long as V vertices, giving O(V) stack depth." },
  { id: "sc-12", topic: "algo-complexity", q: "An algorithm reading its input in a single pass with O(1) extra memory is a:", options: ["Offline algorithm", "Streaming (one-pass, constant-space) algorithm", "Recursive algorithm", "Divide-and-conquer algorithm"], answer: 1, exp: "Streaming algorithms process data as it arrives using sub-linear (often constant) space." },
  { id: "sc-13", topic: "algo-complexity", q: "The Fibonacci DP can be done in O(1) space by:", options: ["Storing the whole array", "Keeping only the last two values", "Using recursion", "Using a hash map"], answer: 1, exp: "Only fib(i-1) and fib(i-2) are needed to compute fib(i)." },
  { id: "sc-14", topic: "algo-complexity", q: "Hash table space complexity for n entries with load factor alpha is:", options: ["O(1)", "O(n) (buckets + entries)", "O(n^2)", "O(log n)"], answer: 1, exp: "The table size is proportional to n / alpha, i.e. O(n)." },
  { id: "sc-15", topic: "algo-complexity", q: "Which sorting algorithm is both O(n log n) time AND O(1) auxiliary space?", options: ["Merge sort", "Heapsort", "Counting sort", "Standard quicksort"], answer: 1, exp: "Heapsort sorts in place; merge sort needs O(n), quicksort needs O(log n) stack, counting sort needs O(n+k)." },
  { id: "sc-16", topic: "algo-complexity", q: "Tail-recursion optimization reduces a recursion's space from:", options: ["O(n) to O(1)", "O(1) to O(n)", "O(log n) to O(n)", "No change"], answer: 0, exp: "Reusing the current frame turns the recursion into a loop with constant stack space." },
  { id: "sc-17", topic: "algo-complexity", q: "The space to store an adjacency matrix of a graph is:", options: ["O(V + E)", "O(V^2)", "O(E)", "O(V log V)"], answer: 1, exp: "A V x V matrix regardless of edge count." },
  { id: "sc-18", topic: "algo-complexity", q: "A rolling-hash (Rabin-Karp) substring search uses extra space:", options: ["O(m) for the pattern length", "O(1) beyond the pattern (just the current hash)", "O(n)", "O(nm)"], answer: 1, exp: "The hash is updated in O(1) per shift; only a few integer variables are kept." },
  { id: "sc-19", topic: "algo-complexity", q: "Which DP problem's naive table is O(n^2) space but reducible to O(n)?", options: ["Longest common subsequence", "0/1 knapsack only", "Matrix chain multiplication", "All-pairs shortest path"], answer: 0, exp: "LCS needs only the previous row, so O(min(m,n)) space suffices for the length (not the reconstruction)." },
  { id: "sc-20", topic: "algo-complexity", q: "Trie space for storing s strings of total length L over alphabet size sigma is at most:", options: ["O(s)", "O(L) nodes (each with up to sigma children)", "O(L * sigma^2)", "O(s^2)"], answer: 1, exp: "At most one node per character across all inserted strings." },
  { id: "sc-21", topic: "algo-complexity", q: "The recursion depth of binary search (recursive) is:", options: ["O(n)", "O(log n)", "O(1)", "O(n log n)"], answer: 1, exp: "The range halves each call, so depth ~ log2 n; iterative binary search is O(1) space." },
  { id: "sc-22", topic: "algo-complexity", q: "Floyd-Warshall all-pairs shortest paths uses space:", options: ["O(V)", "O(V^2)", "O(V^3)", "O(E)"], answer: 1, exp: "A V x V distance matrix (the k dimension is updated in place)." },
  { id: "sc-23", topic: "algo-complexity", q: "Which is TRUE about time vs space lower bounds?", options: ["Space used is always <= time used (you cannot touch more cells than steps)", "Time <= space", "They are unrelated", "Space is always larger"], answer: 0, exp: "In one time step you can write at most O(1) memory, so total space <= O(time)." },
  { id: "sc-24", topic: "algo-complexity", q: "Memoization's space cost equals:", options: ["O(1)", "The number of distinct subproblems cached", "O(2^n) always", "The recursion depth only"], answer: 1, exp: "Every unique subproblem result is stored; e.g. LCS memo is O(mn)." },
  { id: "sc-25", topic: "algo-complexity", q: "Bit manipulation / bitset techniques reduce space by a factor of about:", options: ["2", "8 (bits vs bytes) or the word size", "log n", "n"], answer: 1, exp: "Packing booleans into machine words cuts memory ~ 8x (or 32-64x vs an int array)." },
  { id: "sc-26", topic: "algo-complexity", q: "An algorithm is 'work-efficient' in the parallel setting if its total work is:", options: ["O(1)", "Asymptotically the same as the best sequential algorithm", "Larger than sequential", "Independent of processors"], answer: 1, exp: "Work efficiency means parallelism does not increase the asymptotic total operation count." },
  { id: "sc-27", topic: "algo-complexity", q: "The space complexity of iterative deepening DFS (IDDFS) is:", options: ["O(b^d) like BFS", "O(bd) — linear like DFS, while finding the shallowest goal like BFS", "O(1)", "O(d^2)"], answer: 1, exp: "IDDFS keeps only the current path, so space is O(depth) yet it explores level by level." },
  { id: "sc-28", topic: "algo-complexity", q: "Which uses O(n) space but could be argued to be O(1) if the output is not counted?", options: ["Reversing an array in place", "Building a hash map of counts", "Producing a sorted copy of an array", "Binary search"], answer: 2, exp: "The sorted copy is the output; auxiliary space beyond output/input can still be O(1) (e.g. selection sort into a new array)." },
  { id: "sc-29", topic: "algo-complexity", q: "The time complexity of accessing an element in a hash table (average) and its space:", options: ["O(1) time, O(n) space", "O(log n) time, O(1) space", "O(n) time, O(1) space", "O(1) time, O(1) space"], answer: 0, exp: "Average O(1) lookup at the cost of O(n) table storage." },
  { id: "sc-30", topic: "algo-complexity", q: "Which is the space complexity of the recursive Tower of Hanoi solution for n disks?", options: ["O(1)", "O(n) recursion depth", "O(2^n)", "O(n^2)"], answer: 1, exp: "Although it makes 2^n - 1 moves, the recursion depth (and thus stack space) is only n." },
  { id: "sc-31", topic: "algo-complexity", q: "The 'output-sensitive' complexity of an algorithm depends on:", options: ["Only the input size", "The size of the output k as well as the input n (e.g. O(n + k))", "The machine word size", "The programming language"], answer: 1, exp: "E.g. reporting all k intersection points among n segments." },
  { id: "sc-32", topic: "algo-complexity", q: "Radix sort (LSD) on n d-digit numbers uses space:", options: ["O(1)", "O(n + b) where b is the base/bucket count", "O(nd)", "O(n^2)"], answer: 1, exp: "It needs buckets (O(b)) and an output buffer (O(n)) per digit pass." },
  { id: "sc-33", topic: "algo-complexity", q: "Reducing DP space from O(n^2) to O(n) usually means you can no longer:", options: ["Compute the optimal value", "Reconstruct the optimal solution path directly (need extra bookkeeping or a divide-and-conquer trick)", "Run the algorithm", "Handle large n"], answer: 1, exp: "Keeping only the last row gives the value but discards the choices; Hirschberg's algorithm recovers the path in O(n) space." },
  { id: "sc-34", topic: "algo-complexity", q: "The space used by Dijkstra with a binary heap is:", options: ["O(1)", "O(V) for the heap and distance array", "O(V^2)", "O(E log V)"], answer: 1, exp: "Distance/parent arrays and the priority queue are all O(V) (heap can hold O(E) entries in a simple implementation but still O(E) <= O(V^2))." },
  { id: "sc-35", topic: "algo-complexity", q: "An algorithm with O(n) time and O(n) space processing a 10^9-element array on a machine with 8 GB RAM will most likely:", options: ["Run fine", "Run out of memory if each element needs several bytes of auxiliary storage", "Be slower than O(n^2)", "Use the GPU"], answer: 1, exp: "Constant factors on space matter: 10^9 * (say 16 bytes) = 16 GB exceeds RAM." },
  { id: "sc-36", topic: "algo-complexity", q: "The classic technique to analyze an algorithm whose per-step cost varies but whose total is bounded is:", options: ["Worst-case per step", "Amortized analysis (total / number of operations)", "Best-case analysis", "Ignoring the variation"], answer: 1, exp: "Amortization gives a fair per-operation cost over a sequence." },
  { id: "sc-37", topic: "algo-complexity", q: "Two-pointer / sliding-window techniques typically achieve:", options: ["O(n^2) time, O(n) space", "O(n) time, O(1) extra space", "O(log n) time", "O(n log n) time"], answer: 1, exp: "A single linear scan with a couple of index variables." },
  { id: "sc-38", topic: "algo-complexity", q: "The space complexity of the recursive merge sort call stack alone is:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 1, exp: "Recursion depth is log n; the O(n) merge buffer is separate." },
  { id: "sc-39", topic: "algo-complexity", q: "A segment tree over an array of n elements uses space:", options: ["O(log n)", "O(n) (about 2n-4n nodes)", "O(n log n)", "O(n^2)"], answer: 1, exp: "A segment tree has O(n) nodes and answers range queries in O(log n)." },
  { id: "sc-40", topic: "algo-complexity", q: "A Fenwick (Binary Indexed) tree uses space:", options: ["O(1)", "O(n)", "O(n log n)", "O(log n)"], answer: 1, exp: "One array of size n+1; prefix-sum queries and updates in O(log n)." },
  { id: "sc-41", topic: "algo-complexity", q: "Which is TRUE: an O(n^2)-time algorithm...", options: ["always uses O(n^2) space", "may use only O(1) space", "cannot be recursive", "is always slower than any O(n log n) one for all n"], answer: 1, exp: "Time and space are independent; e.g. bubble sort is O(n^2) time, O(1) space." },
  { id: "sc-42", topic: "algo-complexity", q: "The space for storing all n! permutations of n elements is:", options: ["O(n!)", "O(n * n!)", "O(n^2)", "O(2^n)"], answer: 1, exp: "There are n! permutations, each of length n." },
  { id: "sc-43", topic: "algo-complexity", q: "Which approach trades time for space?", options: ["Recomputing a value each time it is needed instead of caching it", "Precomputing a prefix-sum array for O(1) range queries", "Using an in-place sort", "Streaming"], answer: 1, exp: "Prefix sums use O(n) extra memory to make each query O(1) instead of O(n)." },
  { id: "sc-44", topic: "algo-complexity", q: "The auxiliary space of selection sort is:", options: ["O(1)", "O(n)", "O(log n)", "O(n^2)"], answer: 0, exp: "It swaps within the array using a constant number of variables." },
  { id: "sc-45", topic: "algo-complexity", q: "For a divide-and-conquer algorithm, the maximum space is usually:", options: ["The sum over all recursive calls", "The maximum over a single root-to-leaf path (calls on other branches have returned)", "Zero", "O(n^2)"], answer: 1, exp: "Only one branch is active at a time, so space = max depth * per-frame cost (+ any persistent buffers)." },
  { id: "sc-46", topic: "algo-complexity", q: "Storing a DP table for edit distance between strings of length m and n takes:", options: ["O(m + n)", "O(mn) (reducible to O(min(m,n)) for the value)", "O(1)", "O(2^(m+n))"], answer: 1, exp: "The full table is (m+1) x (n+1); only two rows are needed for the distance value." },
  { id: "sc-47", topic: "algo-complexity", q: "The space complexity of an algorithm that only swaps and compares array elements is:", options: ["O(1) auxiliary", "O(n)", "O(log n)", "O(n log n)"], answer: 0, exp: "No data structure grows with n — constant extra space." },
  { id: "sc-48", topic: "algo-complexity", q: "IDA* (iterative deepening A*) is preferred over A* when:", options: ["The graph is small", "Memory is the bottleneck (A*'s open list can be exponential)", "Edges are negative", "Speed does not matter"], answer: 1, exp: "IDA* uses linear memory by re-searching with an increasing f-cost threshold." },
  { id: "sc-49", topic: "algo-complexity", q: "Which is the space complexity of computing n! iteratively?", options: ["O(1) (ignoring the size of the big result)", "O(n)", "O(n^2)", "O(log n)"], answer: 0, exp: "A single accumulator variable; the recursive version would be O(n) stack." },
  { id: "sc-50", topic: "algo-complexity", q: "The dominant space cost of BFS on a grid of R x C cells is:", options: ["O(1)", "O(R + C)", "O(RC) for the visited array and queue", "O(RC log RC)"], answer: 2, exp: "Every cell may be marked visited and briefly queued." },

  // ================= Worst / Average / Best-Case Analysis (50) =================
  { id: "ca-01", topic: "algo-caseanalysis", q: "Worst-case analysis gives:", options: ["The typical running time", "An upper bound that holds for EVERY input of size n", "The fastest possible time", "The average over random inputs"], answer: 1, exp: "It is a guarantee: no input of size n takes longer." },
  { id: "ca-02", topic: "algo-caseanalysis", q: "Average-case analysis requires:", options: ["Nothing extra", "An assumed probability distribution over inputs", "The worst input", "Randomized code"], answer: 1, exp: "You compute E[T(n)] over the input distribution (often 'uniformly random')." },
  { id: "ca-03", topic: "algo-caseanalysis", q: "Linear search for a key in an array of n elements: worst case / average case (key present, uniform) / best case:", options: ["n / n/2 / 1", "n / n / 1", "log n / log n / 1", "n / 1 / 1"], answer: 0, exp: "Worst: last position or absent (n). Average when present: (n+1)/2 ~ n/2. Best: first position (1)." },
  { id: "ca-04", topic: "algo-caseanalysis", q: "Quicksort: worst / average / best case time:", options: ["n log n / n log n / n log n", "n^2 / n log n / n log n", "n^2 / n^2 / n log n", "n log n / n^2 / n"], answer: 1, exp: "Worst (already sorted with bad pivot) is n^2; average and best (balanced splits) are n log n." },
  { id: "ca-05", topic: "algo-caseanalysis", q: "Merge sort's worst, average and best case are all:", options: ["O(n)", "O(n log n)", "O(n^2)", "different from each other"], answer: 1, exp: "Merge sort always splits in half and merges in linear time regardless of input order." },
  { id: "ca-06", topic: "algo-caseanalysis", q: "Insertion sort: best case (sorted) / worst case (reverse sorted):", options: ["O(n) / O(n^2)", "O(n log n) / O(n^2)", "O(n) / O(n log n)", "O(1) / O(n)"], answer: 0, exp: "Sorted input: one comparison per element, no shifts. Reverse: every element shifts all the way, n(n-1)/2." },
  { id: "ca-07", topic: "algo-caseanalysis", q: "Bubble sort with an early-exit flag: best case on sorted input is:", options: ["O(n^2)", "O(n) (one clean pass, no swaps, then stop)", "O(n log n)", "O(1)"], answer: 1, exp: "If a full pass makes no swaps, the array is sorted and the algorithm halts." },
  { id: "ca-08", topic: "algo-caseanalysis", q: "Hash table search: average / worst case:", options: ["O(1) / O(1)", "O(1) / O(n) (all keys collide into one bucket)", "O(log n) / O(n)", "O(n) / O(n)"], answer: 1, exp: "With a good hash and low load factor it is O(1) average; adversarial or terrible hashing degrades to O(n)." },
  { id: "ca-09", topic: "algo-caseanalysis", q: "Binary search on a sorted array: worst case:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 1, exp: "The range halves each step; at most floor(log2 n) + 1 comparisons." },
  { id: "ca-10", topic: "algo-caseanalysis", q: "BST search worst case vs average case (random insertions):", options: ["O(log n) / O(log n)", "O(n) / O(log n)", "O(n) / O(n)", "O(1) / O(log n)"], answer: 1, exp: "A degenerate tree gives O(n); a randomly built BST has expected height O(log n)." },
  { id: "ca-11", topic: "algo-caseanalysis", q: "For deterministic quicksort, which input triggers the worst case with 'first element as pivot'?", options: ["Random data", "An already-sorted (or reverse-sorted) array", "An array of all equal elements only", "Any array with duplicates"], answer: 1, exp: "Sorted input makes every partition maximally unbalanced (1 vs n-1)." },
  { id: "ca-12", topic: "algo-caseanalysis", q: "Randomized quicksort's WORST case is still O(n^2), but:", options: ["It never happens", "It happens only with negligible probability, so EXPECTED time is O(n log n) for every input", "The average is O(n^2)", "It is O(n log n) worst case"], answer: 1, exp: "Randomization makes the bad case improbable regardless of the input arrangement." },
  { id: "ca-13", topic: "algo-caseanalysis", q: "Which analysis is most relevant for a real-time system with hard deadlines?", options: ["Best case", "Average case", "Worst case", "Amortized"], answer: 2, exp: "Hard real-time needs a guaranteed upper bound on every execution." },
  { id: "ca-14", topic: "algo-caseanalysis", q: "The average-case analysis of successful linear search assumes each position is equally likely, giving expected comparisons:", options: ["1", "n", "(n+1)/2", "log n"], answer: 2, exp: "Average of 1, 2, ..., n is (n+1)/2." },
  { id: "ca-15", topic: "algo-caseanalysis", q: "Selection sort's number of comparisons is:", options: ["O(n) best, O(n^2) worst", "Always Theta(n^2), regardless of input", "O(n log n)", "O(n) always"], answer: 1, exp: "It always scans the unsorted suffix to find the minimum — input order does not help." },
  { id: "ca-16", topic: "algo-caseanalysis", q: "Heapsort's best, average, and worst case are:", options: ["O(n), O(n log n), O(n^2)", "all O(n log n)", "all O(n^2)", "O(n log n), O(n log n), O(n)"], answer: 1, exp: "Build-heap is O(n) and n extractions are O(n log n) regardless of input." },
  { id: "ca-17", topic: "algo-caseanalysis", q: "The worst case of the KMP string matcher on text of length n is:", options: ["O(nm)", "O(n + m)", "O(n^2)", "O(m log n)"], answer: 1, exp: "The failure function (O(m)) plus a single non-backtracking scan of the text (O(n))." },
  { id: "ca-18", topic: "algo-caseanalysis", q: "Naive string matching worst case (e.g. text 'aaaa...a', pattern 'aaa...ab'):", options: ["O(n)", "O(n + m)", "O(nm)", "O(m^2)"], answer: 2, exp: "Each of ~n shifts compares up to m characters before failing." },
  { id: "ca-19", topic: "algo-caseanalysis", q: "For the same asymptotic worst case, which is a reason to prefer one algorithm over another?", options: ["Constant factors, cache behavior, average-case, and stability", "Nothing — they are equivalent", "The one with the longer name", "The older one"], answer: 0, exp: "E.g. quicksort vs heapsort: both n log n worst/average (well, quicksort avg), but quicksort's constants and locality usually win." },
  { id: "ca-20", topic: "algo-caseanalysis", q: "Which statement is TRUE?", options: ["Best-case analysis is the most useful", "Best-case can be misleading because it may correspond to rare inputs", "Best case equals average case", "Best case is always O(1)"], answer: 1, exp: "Best case tells you little about typical or guaranteed performance." },
  { id: "ca-21", topic: "algo-caseanalysis", q: "The expected number of comparisons in randomized quicksort is approximately:", options: ["n", "2 n ln n ~ 1.39 n log2 n", "n^2 / 2", "n log log n"], answer: 1, exp: "The classic analysis gives ~1.39 n lg n comparisons on average." },
  { id: "ca-22", topic: "algo-caseanalysis", q: "For a hash table with chaining and load factor alpha = n/m, the expected search time is:", options: ["O(alpha)", "O(1 + alpha)", "O(m)", "O(n)"], answer: 1, exp: "O(1) to hash plus O(alpha) expected chain length; kept O(1) by bounding alpha with resizing." },
  { id: "ca-23", topic: "algo-caseanalysis", q: "Which sorting algorithm has O(n^2) worst case but is often fastest in practice for small/medium arrays?", options: ["Merge sort", "Quicksort (and insertion sort for tiny arrays)", "Heapsort", "Radix sort"], answer: 1, exp: "Low constants and cache locality; libraries use introsort (quicksort + heapsort fallback + insertion sort for small ranges)." },
  { id: "ca-24", topic: "algo-caseanalysis", q: "The worst case of finding an element in a balanced BST (AVL/Red-Black) is:", options: ["O(1)", "O(log n) guaranteed", "O(n)", "O(n log n)"], answer: 1, exp: "Balancing keeps the height O(log n) even in the worst case." },
  { id: "ca-25", topic: "algo-caseanalysis", q: "Amortized analysis differs from average-case analysis in that:", options: ["It uses probability", "It guarantees the average over ANY sequence of operations (no probabilistic assumption)", "It only considers the best case", "They are identical"], answer: 1, exp: "Amortized bounds are worst-case over sequences; average-case bounds assume an input distribution." },
  { id: "ca-26", topic: "algo-caseanalysis", q: "Dynamic array append: worst-case single operation / amortized:", options: ["O(1) / O(1)", "O(n) (during a resize) / O(1)", "O(n) / O(n)", "O(log n) / O(1)"], answer: 1, exp: "One append can trigger an O(n) copy, but averaged over n appends it is O(1)." },
  { id: "ca-27", topic: "algo-caseanalysis", q: "The worst case for hash table insertion with open addressing near full capacity is:", options: ["O(1)", "O(n) (long probe sequences)", "O(log n)", "O(sqrt n)"], answer: 1, exp: "As alpha -> 1, probe sequences grow long; keep alpha well below 1 (e.g. <= 0.7)." },
  { id: "ca-28", topic: "algo-caseanalysis", q: "For which algorithm does average-case analysis famously give a much better bound than worst-case?", options: ["Merge sort", "Quicksort", "Heapsort", "Binary search"], answer: 1, exp: "Quicksort: O(n^2) worst but O(n log n) average / expected." },
  { id: "ca-29", topic: "algo-caseanalysis", q: "The best case of Dijkstra's algorithm (binary heap) is:", options: ["Better than O((V+E) log V)", "Still Theta((V+E) log V) — it always processes every vertex and edge", "O(V)", "O(1)"], answer: 1, exp: "There is no shortcut; every reachable vertex is extracted and every edge relaxed." },
  { id: "ca-30", topic: "algo-caseanalysis", q: "Bogosort's average-case time is:", options: ["O(n log n)", "O(n * n!) (shuffle until sorted)", "O(n^2)", "O(n!)"], answer: 1, exp: "Expected (n-1)*n! permutations tried, each check O(n) — a cautionary example." },
  { id: "ca-31", topic: "algo-caseanalysis", q: "The number of inversions in an array relates to the running time of:", options: ["Merge sort", "Insertion sort (Theta(n + inversions))", "Heapsort", "Counting sort"], answer: 1, exp: "Insertion sort does one shift per inversion, so nearly-sorted data is fast." },
  { id: "ca-32", topic: "algo-caseanalysis", q: "For 'nearly sorted' input (each element within k of its position), which sort runs in O(n log k)?", options: ["Quicksort", "A heap-based approach with a size-(k+1) heap", "Bubble sort", "Radix sort"], answer: 1, exp: "Maintaining a min-heap of the next k+1 candidates extracts the correct next element in O(log k)." },
  { id: "ca-33", topic: "algo-caseanalysis", q: "The worst case of the Euclidean gcd algorithm gcd(a, b) with a > b occurs for:", options: ["Powers of two", "Consecutive Fibonacci numbers, giving O(log(min(a,b))) steps", "Prime inputs", "Equal inputs"], answer: 1, exp: "Fibonacci inputs make the remainders shrink slowest; still logarithmic." },
  { id: "ca-34", topic: "algo-caseanalysis", q: "Which is the correct statement about 'expected time' of a randomized algorithm?", options: ["It depends on the input distribution", "It is over the algorithm's own random choices and holds for every fixed input", "It is the same as worst case", "It requires random input"], answer: 1, exp: "The expectation is taken over the coin flips of the algorithm, not over inputs." },
  { id: "ca-35", topic: "algo-caseanalysis", q: "A Las Vegas algorithm:", options: ["May give a wrong answer", "Always gives the correct answer; running time is random", "Has fixed running time; answer may be wrong", "Never terminates"], answer: 1, exp: "Las Vegas = always correct, randomized runtime (e.g. randomized quicksort). Monte Carlo = fixed time, possibly wrong." },
  { id: "ca-36", topic: "algo-caseanalysis", q: "A Monte Carlo algorithm:", options: ["Always correct, random time", "Fixed (bounded) time, may err with bounded probability", "Never errs", "Always exponential"], answer: 1, exp: "E.g. Miller-Rabin primality test: fast, with a tunable small error probability." },
  { id: "ca-37", topic: "algo-caseanalysis", q: "The worst case of quickselect (randomized) for the k-th smallest is O(n^2), but expected time is:", options: ["O(n)", "O(n log n)", "O(log n)", "O(n^2)"], answer: 0, exp: "Expected linear time; the deterministic median-of-medians pivot guarantees O(n) worst case." },
  { id: "ca-38", topic: "algo-caseanalysis", q: "For an unbalanced BST built from sorted input, insertion of the n-th key costs:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 2, exp: "The tree is a chain of length n-1; the new key walks to the end." },
  { id: "ca-39", topic: "algo-caseanalysis", q: "Which factor makes worst-case and average-case coincide for merge sort but not quicksort?", options: ["Merge sort's recursion is always balanced (splits by index, not value)", "Merge sort uses more memory", "Quicksort is recursive", "Merge sort is stable"], answer: 0, exp: "Splitting at the midpoint is input-independent; quicksort's split depends on the pivot value." },
  { id: "ca-40", topic: "algo-caseanalysis", q: "The average-case number of probes for a successful search in an open-addressing table with load factor alpha is approximately:", options: ["1 / (1 - alpha)", "(1/alpha) ln(1/(1-alpha))", "alpha", "n"], answer: 1, exp: "Successful search: ~ (1/alpha) ln(1/(1-alpha)); unsuccessful: ~ 1/(1-alpha)." },
  { id: "ca-41", topic: "algo-caseanalysis", q: "For a min-heap, extract-min worst case and best case are:", options: ["O(log n) / O(1) (if the new root does not need to sink)", "O(1) / O(1)", "O(n) / O(log n)", "O(log n) / O(log n) always"], answer: 0, exp: "Sift-down may stop early if the moved element is already <= its children." },
  { id: "ca-42", topic: "algo-caseanalysis", q: "The number of comparisons for merge sort in the worst case is:", options: ["exactly n log n", "between (n log n)/2 and n log n - n + 1", "n^2", "n"], answer: 1, exp: "Each merge of total size m does at most m-1 comparisons; summed over levels gives ~ n log n - n." },
  { id: "ca-43", topic: "algo-caseanalysis", q: "Which analysis would you cite to justify a doubling dynamic array despite occasional slow appends?", options: ["Worst-case per operation", "Amortized analysis", "Best-case analysis", "Average-case with random inputs"], answer: 1, exp: "Amortized O(1) per append is the standard justification." },
  { id: "ca-44", topic: "algo-caseanalysis", q: "The worst case of counting sort is:", options: ["O(n^2)", "O(n + k) — same as its best and average case", "O(n log n)", "O(k^2)"], answer: 1, exp: "It is not comparison-based and its cost is input-order independent." },
  { id: "ca-45", topic: "algo-caseanalysis", q: "'Smoothed analysis' interpolates between worst and average case by:", options: ["Averaging the two", "Analyzing the worst case over small random perturbations of the input", "Ignoring the worst case", "Using amortization"], answer: 1, exp: "It explains why simplex / quicksort perform well despite bad worst cases — pathological inputs are fragile." },
  { id: "ca-46", topic: "algo-caseanalysis", q: "The best case of the naive substring search is:", options: ["O(1)", "O(n) (mismatch on the first character of every alignment)", "O(nm)", "O(m)"], answer: 1, exp: "If the first char always mismatches, each of ~n alignments costs O(1)." },
  { id: "ca-47", topic: "algo-caseanalysis", q: "For interpolation search on uniformly distributed sorted data, the average case is:", options: ["O(log n)", "O(log log n)", "O(n)", "O(1)"], answer: 1, exp: "It estimates the position proportionally; worst case (skewed data) degrades to O(n)." },
  { id: "ca-48", topic: "algo-caseanalysis", q: "Which is TRUE about worst-case vs average-case for hashing-based algorithms?", options: ["They are always equal", "Worst case can be poor (collisions) but a good/random hash makes the expected case efficient", "Average is worse than worst", "Hashing has no worst case"], answer: 1, exp: "Universal hashing gives O(1) expected regardless of the input keys." },
  { id: "ca-49", topic: "algo-caseanalysis", q: "The worst case of building an AVL tree by inserting n elements is:", options: ["O(n)", "O(n log n) (each insert O(log n) with O(1) rotations)", "O(n^2)", "O(2^n)"], answer: 1, exp: "Balanced height keeps every insert logarithmic." },
  { id: "ca-50", topic: "algo-caseanalysis", q: "When a problem statement says 'analyze the algorithm', the default expectation is:", options: ["Best case", "Worst-case asymptotic time (and often space)", "Average case only", "Empirical timing"], answer: 1, exp: "Worst-case Big-O time is the conventional default unless stated otherwise." },

  // ================= Divide & Conquer (50) =================
  { id: "dc-01", topic: "algo-divide-conquer", q: "The three steps of divide and conquer are:", options: ["Sort, search, merge", "Divide, conquer (recurse), combine", "Guess, check, repeat", "Hash, probe, resize"], answer: 1, exp: "Split into subproblems, solve each recursively, then combine the sub-solutions." },
  { id: "dc-02", topic: "algo-divide-conquer", q: "Merge sort's recurrence is:", options: ["T(n) = T(n-1) + O(1)", "T(n) = 2T(n/2) + O(n)", "T(n) = T(n/2) + O(1)", "T(n) = 2T(n-1) + O(1)"], answer: 1, exp: "Two halves plus a linear merge => Theta(n log n)." },
  { id: "dc-03", topic: "algo-divide-conquer", q: "Binary search is divide and conquer with recurrence:", options: ["T(n) = 2T(n/2) + O(1)", "T(n) = T(n/2) + O(1)", "T(n) = T(n/2) + O(n)", "T(n) = 2T(n/2) + O(n)"], answer: 1, exp: "It recurses into only ONE half with constant extra work => O(log n)." },
  { id: "dc-04", topic: "algo-divide-conquer", q: "The master theorem case where f(n) = Theta(n^(log_b a)) gives:", options: ["T(n) = Theta(f(n))", "T(n) = Theta(n^(log_b a) * log n)", "T(n) = Theta(n^(log_b a))", "Cannot apply"], answer: 1, exp: "Case 2: work is evenly spread across log n levels, adding a log factor (e.g. merge sort)." },
  { id: "dc-05", topic: "algo-divide-conquer", q: "Karatsuba multiplication of two n-digit numbers has recurrence T(n) = 3T(n/2) + O(n), giving:", options: ["O(n^2)", "O(n^1.585)", "O(n log n)", "O(n^3)"], answer: 1, exp: "n^(log2 3) ~ n^1.585, beating the schoolbook O(n^2)." },
  { id: "dc-06", topic: "algo-divide-conquer", q: "Strassen's matrix multiplication recurrence T(n) = 7T(n/2) + O(n^2) gives:", options: ["O(n^3)", "O(n^2.807)", "O(n^2)", "O(n^2 log n)"], answer: 1, exp: "n^(log2 7) ~ n^2.807, better than the naive O(n^3)." },
  { id: "dc-07", topic: "algo-divide-conquer", q: "The maximum-subarray problem can be solved by divide and conquer in:", options: ["O(n)", "O(n log n) (the classic D&C; Kadane does it in O(n))", "O(n^2)", "O(log n)"], answer: 1, exp: "Split, recurse on halves, and compute the best crossing subarray in O(n): T(n)=2T(n/2)+O(n)." },
  { id: "dc-08", topic: "algo-divide-conquer", q: "The closest-pair-of-points problem in 2D is solved by divide and conquer in:", options: ["O(n^2)", "O(n log n)", "O(n log^2 n) only", "O(n)"], answer: 1, exp: "Split by x-median, recurse, then check a strip of width 2d in O(n) => T(n)=2T(n/2)+O(n)." },
  { id: "dc-09", topic: "algo-divide-conquer", q: "Counting inversions in an array is done by modifying:", options: ["Quicksort", "Merge sort (count cross-inversions during the merge)", "Heapsort", "Counting sort"], answer: 1, exp: "When taking from the right half before the left is exhausted, add the number of remaining left elements. O(n log n)." },
  { id: "dc-10", topic: "algo-divide-conquer", q: "Quicksort is a divide-and-conquer algorithm where the 'divide' step is:", options: ["Trivial; the 'combine' step does the work", "Partitioning around a pivot (the expensive step); combine is trivial", "Merging", "Choosing a base case"], answer: 1, exp: "Opposite of merge sort: quicksort works hard to divide, then just concatenates." },
  { id: "dc-11", topic: "algo-divide-conquer", q: "T(n) = 2T(n/2) + O(n^2) solves to:", options: ["O(n^2)", "O(n^2 log n)", "O(n log n)", "O(n^3)"], answer: 0, exp: "Master theorem case 3: f(n)=n^2 dominates n^(log2 2)=n, so T(n)=Theta(n^2)." },
  { id: "dc-12", topic: "algo-divide-conquer", q: "The recursion tree of a D&C algorithm with T(n) = 3T(n/3) + O(n) has:", options: ["O(log n) levels, O(n) work per level => O(n log n)", "O(n) levels", "O(1) work total", "O(n^2) work"], answer: 0, exp: "3 branches, size /3, so log_3 n levels each doing O(n) total work." },
  { id: "dc-13", topic: "algo-divide-conquer", q: "Which is NOT typically a divide-and-conquer algorithm?", options: ["Merge sort", "Quicksort", "Binary search", "Dijkstra's shortest path"], answer: 3, exp: "Dijkstra is a greedy algorithm; the others recurse on subproblems." },
  { id: "dc-14", topic: "algo-divide-conquer", q: "The median-of-medians selection algorithm achieves O(n) worst case via a recurrence like:", options: ["T(n) = T(n/2) + O(n)", "T(n) <= T(n/5) + T(7n/10) + O(n)", "T(n) = 2T(n/2) + O(n)", "T(n) = T(n-1) + O(1)"], answer: 1, exp: "The two recursive calls have sizes summing to < n, so the total is linear." },
  { id: "dc-15", topic: "algo-divide-conquer", q: "In merge sort, the combine (merge) step of two sorted arrays of total size m takes:", options: ["O(1)", "O(log m)", "O(m)", "O(m log m)"], answer: 2, exp: "A single linear pass comparing the two fronts." },
  { id: "dc-16", topic: "algo-divide-conquer", q: "The FFT (Fast Fourier Transform) computes the DFT of n points in:", options: ["O(n^2)", "O(n log n) via divide and conquer on even/odd indices", "O(n)", "O(n^3)"], answer: 1, exp: "Splitting into even and odd index subsequences gives T(n)=2T(n/2)+O(n)." },
  { id: "dc-17", topic: "algo-divide-conquer", q: "Polynomial multiplication of two degree-n polynomials via FFT takes:", options: ["O(n^2)", "O(n log n)", "O(n)", "O(n log^2 n)"], answer: 1, exp: "Evaluate (FFT), multiply pointwise (O(n)), interpolate (inverse FFT)." },
  { id: "dc-18", topic: "algo-divide-conquer", q: "Which describes the 'combine' cost that makes T(n) = 2T(n/2) + f(n) equal to O(n log n)?", options: ["f(n) = O(1)", "f(n) = Theta(n)", "f(n) = Theta(n^2)", "f(n) = O(log n)"], answer: 1, exp: "Linear combine work spread over log n levels adds the log factor." },
  { id: "dc-19", topic: "algo-divide-conquer", q: "Exponentiation by squaring computes a^n using the identity:", options: ["a^n = a * a^(n-1)", "a^n = (a^(n/2))^2 for even n, a*(a^((n-1)/2))^2 for odd n", "a^n = n * a", "a^n = a^(n/2) + a^(n/2)"], answer: 1, exp: "Halving the exponent each step gives O(log n) multiplications." },
  { id: "dc-20", topic: "algo-divide-conquer", q: "The 'Tromino / L-shaped tile' problem (tile a 2^n x 2^n board minus one square) is solved by:", options: ["Greedy", "Divide the board into four quadrants, place one tromino at the center, recurse", "Dynamic programming", "BFS"], answer: 1, exp: "Recursion with a constant-time combine per quadrant." },
  { id: "dc-21", topic: "algo-divide-conquer", q: "Divide and conquer is well suited to parallelization because:", options: ["Subproblems are independent and can be solved concurrently", "It uses less memory", "It avoids recursion", "It has no combine step"], answer: 0, exp: "Independent subproblems map naturally onto parallel tasks; span is often O(polylog n)." },
  { id: "dc-22", topic: "algo-divide-conquer", q: "T(n) = T(n/2) + T(n/4) + T(n/8) + ... (halving fractions) + n solves to about:", options: ["O(n)", "O(n log n)", "O(n^2)", "O(log n)"], answer: 0, exp: "The work per level forms a decreasing geometric series summing to O(n)." },
  { id: "dc-23", topic: "algo-divide-conquer", q: "Which sorting algorithm's worst case is caused by the divide step producing maximally unequal parts?", options: ["Merge sort", "Quicksort", "Heapsort", "Bubble sort"], answer: 1, exp: "A pivot that is the min or max gives a 0 : n-1 split, causing T(n)=T(n-1)+O(n)=O(n^2)." },
  { id: "dc-24", topic: "algo-divide-conquer", q: "The recurrence for computing the n-th power of a matrix by repeated squaring is:", options: ["T(n) = T(n/2) + O(matmul)", "T(n) = 2T(n/2) + O(n)", "T(n) = T(n-1) + O(1)", "T(n) = O(n^3)"], answer: 0, exp: "O(log n) matrix multiplications; used for linear recurrences like Fibonacci in O(log n) matmuls." },
  { id: "dc-25", topic: "algo-divide-conquer", q: "Binary search's O(log n) is achieved because at each step it:", options: ["Doubles the search space", "Discards half of the remaining candidates", "Checks every element", "Sorts the array"], answer: 1, exp: "Comparing with the middle eliminates one half." },
  { id: "dc-26", topic: "algo-divide-conquer", q: "The 'combine' step of the closest-pair algorithm only needs to check, for each point in the strip, at most:", options: ["All other strip points", "A constant number (~7) of the next points sorted by y", "log n points", "n/2 points"], answer: 1, exp: "Geometric packing shows only a constant number of candidates can be within distance d." },
  { id: "dc-27", topic: "algo-divide-conquer", q: "Which is the master-theorem result for T(n) = 8T(n/2) + O(n^2)?", options: ["O(n^2)", "O(n^2 log n)", "O(n^3)", "O(n^3 log n)"], answer: 2, exp: "n^(log2 8) = n^3 dominates n^2, so Theta(n^3) — the naive matrix multiply recurrence." },
  { id: "dc-28", topic: "algo-divide-conquer", q: "A divide-and-conquer algorithm's base case is usually:", options: ["n = 0 or n = 1 (or a small constant size), solved directly", "The whole input", "Never reached", "n = infinity"], answer: 0, exp: "Recursion stops when the subproblem is trivial (size <= some small constant)." },
  { id: "dc-29", topic: "algo-divide-conquer", q: "Merge sort is preferred over quicksort for linked lists because:", options: ["It is faster asymptotically", "It needs only sequential access and O(1) splicing, no random indexing", "It uses less memory on lists", "Quicksort cannot sort lists"], answer: 1, exp: "Quicksort's partition relies on random access, which lists lack." },
  { id: "dc-30", topic: "algo-divide-conquer", q: "The number of recursive calls in a full binary recursion tree of depth d is:", options: ["d", "2d", "2^(d+1) - 1", "d^2"], answer: 2, exp: "A perfect binary tree of depth d has 2^(d+1) - 1 nodes." },
  { id: "dc-31", topic: "algo-divide-conquer", q: "Which problem does D&C solve in O(n log n) that brute force does in O(n^2)?", options: ["Closest pair of points", "Linear search", "Computing a factorial", "Reversing an array"], answer: 0, exp: "Brute force checks all C(n,2) pairs; D&C achieves n log n." },
  { id: "dc-32", topic: "algo-divide-conquer", q: "For T(n) = aT(n/b) + f(n), if f(n) grows POLYNOMIALLY FASTER than n^(log_b a) and the regularity condition holds, then:", options: ["T(n) = Theta(n^(log_b a))", "T(n) = Theta(f(n))", "T(n) = Theta(n^(log_b a) log n)", "The theorem does not apply"], answer: 1, exp: "Master theorem case 3: the root's work dominates." },
  { id: "dc-33", topic: "algo-divide-conquer", q: "Divide and conquer vs dynamic programming: D&C is preferred when:", options: ["Subproblems overlap heavily", "Subproblems are disjoint / independent", "There is optimal substructure only", "The problem is a graph"], answer: 1, exp: "Overlapping subproblems call for DP (memoization); disjoint ones suit plain recursion." },
  { id: "dc-34", topic: "algo-divide-conquer", q: "Quickselect (find k-th smallest) has expected time:", options: ["O(n) — one-sided recursion T(n) = T(n/2) + O(n) on average", "O(n log n)", "O(log n)", "O(n^2)"], answer: 0, exp: "Only one partition side is recursed into, and the expected sizes shrink geometrically." },
  { id: "dc-35", topic: "algo-divide-conquer", q: "The recurrence T(n) = T(n/3) + T(2n/3) + O(n) solves to:", options: ["O(n)", "O(n log n)", "O(n^2)", "O(log n)"], answer: 1, exp: "Uneven split but total size preserved per level, longest path ~ log_{3/2} n => O(n log n). (This models unbalanced quicksort with a fixed ratio.)" },
  { id: "dc-36", topic: "algo-divide-conquer", q: "'Decrease and conquer' (e.g. binary search, Euclid's gcd) differs from divide and conquer in that:", options: ["It creates multiple subproblems", "It reduces to ONE smaller subproblem", "It never recurses", "It has no base case"], answer: 1, exp: "One subproblem (often much smaller), no combine step; insertion sort and DFS are also 'decrease and conquer'." },
  { id: "dc-37", topic: "algo-divide-conquer", q: "The integer multiplication lower bound was long thought to be Omega(n^2); the current best is:", options: ["Theta(n^2)", "O(n log n) (Harvey-van der Hoeven, 2019)", "O(n^1.585)", "O(n^3)"], answer: 1, exp: "A long chain of D&C improvements (Karatsuba, Toom-Cook, Schonhage-Strassen) culminated in O(n log n)." },
  { id: "dc-38", topic: "algo-divide-conquer", q: "In the D&C maximum subarray algorithm, the maximum crossing sum is found by:", options: ["Recursing again", "Expanding left from the midpoint for the best left sum and right for the best right sum, in O(n)", "Sorting", "A hash map"], answer: 1, exp: "Two linear scans from the center; combined with the two recursive results." },
  { id: "dc-39", topic: "algo-divide-conquer", q: "Toom-Cook (Toom-3) multiplication has recurrence T(n) = 5T(n/3) + O(n), giving:", options: ["O(n^1.465)", "O(n^2)", "O(n log n)", "O(n^1.585)"], answer: 0, exp: "n^(log_3 5) ~ n^1.465, between Karatsuba and Schonhage-Strassen." },
  { id: "dc-40", topic: "algo-divide-conquer", q: "The main disadvantage of divide and conquer can be:", options: ["It never terminates", "Recursion overhead and, for some algorithms, extra memory for combine buffers", "It cannot be analyzed", "It only works on sorted data"], answer: 1, exp: "Function-call overhead and auxiliary space (e.g. merge sort's O(n) buffer)." },
  { id: "dc-41", topic: "algo-divide-conquer", q: "For very small subproblems, optimized D&C sorts switch to:", options: ["Bogosort", "Insertion sort (low overhead for tiny n)", "Radix sort", "Recursion with smaller base"], answer: 1, exp: "Below a threshold (~10-32 elements) insertion sort beats the recursion overhead." },
  { id: "dc-42", topic: "algo-divide-conquer", q: "T(n) = 4T(n/2) + O(n^2) is:", options: ["O(n^2)", "O(n^2 log n)", "O(n^3)", "O(n log n)"], answer: 1, exp: "n^(log2 4) = n^2 = f(n), so master case 2: Theta(n^2 log n)." },
  { id: "dc-43", topic: "algo-divide-conquer", q: "Which recurrence corresponds to a D&C algorithm that does NO combine work?", options: ["T(n) = 2T(n/2) + O(n)", "T(n) = 2T(n/2) + O(1)", "T(n) = T(n/2) + O(n)", "T(n) = T(n-1) + O(n)"], answer: 1, exp: "O(1) combine; e.g. computing the height of a balanced tree => Theta(n)." },
  { id: "dc-44", topic: "algo-divide-conquer", q: "The convex hull of n points can be computed by divide and conquer in:", options: ["O(n)", "O(n log n)", "O(n^2)", "O(n^3)"], answer: 1, exp: "Split by x, recurse, merge the two hulls with tangent lines in O(n)." },
  { id: "dc-45", topic: "algo-divide-conquer", q: "Which is TRUE of the 'combine' step complexity in most efficient D&C sorts and selections?", options: ["It is exponential", "It is linear or constant in the subproblem size", "It dominates and is O(n^2)", "It is logarithmic"], answer: 1, exp: "Efficient D&C keeps combine cheap so the recurrence stays near n log n or n." },
  { id: "dc-46", topic: "algo-divide-conquer", q: "Recursively computing Fibonacci with fib(n) = fib(n-1) + fib(n-2) is a D&C form but inefficient because:", options: ["The subproblems overlap and are recomputed exponentially", "The base case is wrong", "It uses too much memory", "It is tail recursive"], answer: 0, exp: "Overlapping subproblems: this is where DP/memoization is needed, not plain D&C." },
  { id: "dc-47", topic: "algo-divide-conquer", q: "The number of levels in the recursion tree for T(n) = 2T(n/2) + O(n) is:", options: ["n", "n/2", "log2 n + 1", "2^n"], answer: 2, exp: "Halving from n to 1 takes log2 n divisions." },
  { id: "dc-48", topic: "algo-divide-conquer", q: "Which algorithm applies D&C to a SORTED matrix (rows and columns sorted) to search a value in O(m + n)?", options: ["Binary search on the whole matrix", "Start at the top-right corner and eliminate a row or column each step", "Merge sort the matrix", "DFS"], answer: 1, exp: "The 'staircase' search is technically decrease-and-conquer: each comparison discards a full row or column." },
  { id: "dc-49", topic: "algo-divide-conquer", q: "The maximum number of comparisons to merge two sorted lists of sizes p and q is:", options: ["p * q", "p + q - 1", "max(p, q)", "log(p + q)"], answer: 1, exp: "Each comparison consumes one element; the last element goes in free." },
  { id: "dc-50", topic: "algo-divide-conquer", q: "Divide-and-conquer recurrences assume subproblem sizes are:", options: ["Always exactly n/2", "A constant fraction of n (e.g. n/b), so the depth is logarithmic", "n - 1", "Random"], answer: 1, exp: "Geometric shrinkage (size /b per level) is what gives the log n depth; subtracting a constant gives linear depth instead." },

  // ================= Tree & Graph Traversals (50) =================
  { id: "tv-01", topic: "algo-traversals", q: "Pre-order traversal visits:", options: ["Left, Root, Right", "Root, Left, Right", "Left, Right, Root", "By level"], answer: 1, exp: "Root first, then recurse left, then right." },
  { id: "tv-02", topic: "algo-traversals", q: "In-order traversal visits:", options: ["Root, Left, Right", "Left, Root, Right", "Left, Right, Root", "By level"], answer: 1, exp: "For a BST this yields keys in ascending order." },
  { id: "tv-03", topic: "algo-traversals", q: "Post-order traversal visits:", options: ["Root, Left, Right", "Left, Root, Right", "Left, Right, Root", "By level"], answer: 2, exp: "Children before parent — used to free a tree or compute subtree aggregates." },
  { id: "tv-04", topic: "algo-traversals", q: "Level-order (breadth-first) tree traversal uses a:", options: ["Stack", "Queue", "Priority queue", "Recursion only"], answer: 1, exp: "Enqueue the root; dequeue a node and enqueue its children." },
  { id: "tv-05", topic: "algo-traversals", q: "All four standard tree traversals run in:", options: ["O(log n)", "O(n)", "O(n log n)", "O(n^2)"], answer: 1, exp: "Each node is visited exactly once." },
  { id: "tv-06", topic: "algo-traversals", q: "Recursion depth of DFS traversal on a tree of height h is:", options: ["O(1)", "O(h)", "O(n) always", "O(log n) always"], answer: 1, exp: "The call stack holds one root-to-node path; O(h), which is O(n) for a skewed tree." },
  { id: "tv-07", topic: "algo-traversals", q: "For the expression tree of (a + b) * c, the post-order traversal is:", options: ["* + a b c", "a b + c *", "a + b * c", "c * a + b"], answer: 1, exp: "Post-order of an expression tree gives postfix (RPN)." },
  { id: "tv-08", topic: "algo-traversals", q: "For a BST, which traversal prints keys in DESCENDING order?", options: ["Pre-order", "Reverse in-order (Right, Root, Left)", "Post-order", "Level order"], answer: 1, exp: "Visiting the right subtree before the left gives largest-first." },
  { id: "tv-09", topic: "algo-traversals", q: "Morris traversal performs in-order traversal with:", options: ["O(n) stack", "O(1) extra space by threading leaf right-pointers", "O(log n) recursion", "A queue"], answer: 1, exp: "It temporarily links each node to its in-order predecessor/successor, restoring the tree afterward." },
  { id: "tv-10", topic: "algo-traversals", q: "Graph DFS uses which structure (iteratively)?", options: ["Queue", "Stack", "Priority queue", "Union-find"], answer: 1, exp: "LIFO order: go deep, backtrack." },
  { id: "tv-11", topic: "algo-traversals", q: "Graph BFS uses which structure?", options: ["Stack", "Queue", "Heap", "Set only"], answer: 1, exp: "FIFO order gives level-by-level exploration and unit-weight shortest paths." },
  { id: "tv-12", topic: "algo-traversals", q: "DFS and BFS on a graph both run in:", options: ["O(V)", "O(V + E) with adjacency lists", "O(V^2) always", "O(E log V)"], answer: 1, exp: "Each vertex and edge is processed O(1) times." },
  { id: "tv-13", topic: "algo-traversals", q: "In graph traversal, you must track visited vertices to:", options: ["Save memory", "Avoid infinite loops from cycles and redundant work", "Sort the output", "Speed up hashing"], answer: 1, exp: "Unlike trees, graphs can have cycles and multiple paths to a vertex." },
  { id: "tv-14", topic: "algo-traversals", q: "A DFS on a directed graph classifies edges as:", options: ["Tree, back, forward, cross", "Short, long", "Red, black", "In, out"], answer: 0, exp: "A back edge (to an ancestor still on the recursion stack) indicates a cycle." },
  { id: "tv-15", topic: "algo-traversals", q: "Topological sort can be produced by DFS as:", options: ["The order vertices are discovered", "The reverse of DFS finish times", "BFS order", "Sorted vertex ids"], answer: 1, exp: "Push each vertex when it finishes; reversing gives a valid topological order (DAG only)." },
  { id: "tv-16", topic: "algo-traversals", q: "BFS from a source in an unweighted graph computes:", options: ["Minimum spanning tree", "Shortest path distances (in edges) to all reachable vertices", "Strongly connected components", "A Hamiltonian path"], answer: 1, exp: "Vertices are dequeued in non-decreasing distance order." },
  { id: "tv-17", topic: "algo-traversals", q: "Which traversal would you use to find connected components of an undirected graph?", options: ["Either BFS or DFS, one run per unvisited vertex", "Only BFS", "Only DFS", "Neither works"], answer: 0, exp: "Each traversal marks one entire component." },
  { id: "tv-18", topic: "algo-traversals", q: "The DFS tree of a connected undirected graph has non-tree edges that are only:", options: ["Cross edges", "Back edges (no forward or cross edges in undirected DFS)", "Forward edges", "All four types"], answer: 1, exp: "In undirected DFS every non-tree edge connects a vertex to an ancestor." },
  { id: "tv-19", topic: "algo-traversals", q: "Iterative deepening DFS combines:", options: ["BFS memory with DFS completeness", "DFS's low memory with BFS's shallowest-solution property", "Dijkstra and A*", "Two stacks"], answer: 1, exp: "It re-runs depth-limited DFS with increasing limits; O(bd) space, finds the shallowest goal." },
  { id: "tv-20", topic: "algo-traversals", q: "The space complexity of BFS on a tree is proportional to:", options: ["The height", "The maximum width (largest level)", "1", "The number of leaves squared"], answer: 1, exp: "The queue holds at most one level's nodes at a time." },
  { id: "tv-21", topic: "algo-traversals", q: "Given pre-order [A B D E C F] and in-order [D B E A C F], the root is:", options: ["A", "B", "D", "F"], answer: 0, exp: "The first element of pre-order is always the root." },
  { id: "tv-22", topic: "algo-traversals", q: "Which pair of traversals CANNOT uniquely reconstruct a general binary tree?", options: ["pre-order + in-order", "post-order + in-order", "pre-order + post-order", "level-order + in-order"], answer: 2, exp: "pre + post is ambiguous when a node has a single child." },
  { id: "tv-23", topic: "algo-traversals", q: "Zigzag (spiral) level-order traversal is implemented with:", options: ["One queue", "Two stacks, alternating which one children are pushed to", "A heap", "Recursion only"], answer: 1, exp: "Alternating stacks reverse the visiting direction each level." },
  { id: "tv-24", topic: "algo-traversals", q: "DFS finish times are used to compute:", options: ["Shortest paths", "Strongly connected components (Kosaraju/Tarjan), topological order, articulation points", "Minimum spanning tree", "Maximum flow"], answer: 1, exp: "Discovery/finish times and 'low-link' values drive several classic DFS algorithms." },
  { id: "tv-25", topic: "algo-traversals", q: "A cycle in an undirected graph is detected during DFS when:", options: ["Any vertex is revisited", "A visited neighbor is found that is not the parent of the current vertex", "The stack is empty", "All vertices are visited"], answer: 1, exp: "Ignoring the edge back to the parent, any other visited neighbor closes a cycle." },
  { id: "tv-26", topic: "algo-traversals", q: "For a graph stored as an adjacency MATRIX, BFS/DFS run in:", options: ["O(V + E)", "O(V^2) — scanning each vertex's full row", "O(E)", "O(V log V)"], answer: 1, exp: "Finding a vertex's neighbors costs O(V) regardless of its degree." },
  { id: "tv-27", topic: "algo-traversals", q: "Which traversal naturally computes the height of each subtree in one pass?", options: ["Pre-order", "Post-order (heights of children known before the parent)", "Level order", "In-order"], answer: 1, exp: "Bottom-up: height(node) = 1 + max(height(left), height(right))." },
  { id: "tv-28", topic: "algo-traversals", q: "The number of distinct binary trees with a given in-order traversal of n distinct keys is:", options: ["1", "n!", "The n-th Catalan number", "2^n"], answer: 2, exp: "In-order alone fixes the key ordering but not the shape." },
  { id: "tv-29", topic: "algo-traversals", q: "To print all root-to-leaf paths, use:", options: ["BFS", "DFS with backtracking (append on descent, pop on return)", "In-order traversal", "Level order"], answer: 1, exp: "Maintain the current path; emit it whenever a leaf is reached." },
  { id: "tv-30", topic: "algo-traversals", q: "A 'multi-source BFS' initializes the queue with:", options: ["One source", "Several sources at distance 0 simultaneously", "All vertices", "The sink"], answer: 1, exp: "It computes each vertex's distance to the NEAREST source in one pass." },
  { id: "tv-31", topic: "algo-traversals", q: "DFS is preferred over BFS when:", options: ["The shortest path is required", "The graph is very wide/shallow and memory is tight, or you need path/cycle/topological info", "Edges are weighted", "The graph is a tree of depth 2"], answer: 1, exp: "DFS uses O(depth) memory and exposes discovery/finish structure." },
  { id: "tv-32", topic: "algo-traversals", q: "BFS is preferred over DFS when:", options: ["You need the fewest-edges path in an unweighted graph", "The graph is deep and narrow", "You need topological order", "Memory is extremely tight"], answer: 0, exp: "BFS guarantees the shortest (fewest-edge) path first." },
  { id: "tv-33", topic: "algo-traversals", q: "The order of node visits in a DFS depends on:", options: ["Nothing; it is unique", "The order neighbors are listed in the adjacency structure and the start vertex", "The number of edges only", "Vertex weights"], answer: 1, exp: "Different adjacency orderings yield different (all valid) DFS traversals." },
  { id: "tv-34", topic: "algo-traversals", q: "Tarjan's algorithm finds SCCs in one DFS pass using:", options: ["Two DFS passes", "Discovery indices and low-link values plus a stack", "A queue", "Union-find"], answer: 1, exp: "A vertex whose low-link equals its own index is the root of an SCC; pop the stack down to it." },
  { id: "tv-35", topic: "algo-traversals", q: "Kosaraju's SCC algorithm requires:", options: ["One DFS", "Two DFS passes — one on G (order by finish time) and one on the transpose G^T", "BFS only", "Sorting the edges"], answer: 1, exp: "Processing G^T in decreasing finish-time order isolates each SCC." },
  { id: "tv-36", topic: "algo-traversals", q: "In BFS, marking a vertex visited when it is ENQUEUED (not dequeued) prevents:", options: ["Cycles in trees", "The same vertex being added to the queue multiple times by different neighbors", "Stack overflow", "Nothing"], answer: 1, exp: "Otherwise a vertex with many predecessors is enqueued repeatedly." },
  { id: "tv-37", topic: "algo-traversals", q: "Euler tour of a tree (record each node on entry and exit) is used for:", options: ["Sorting", "Reducing subtree/LCA queries to range queries on an array", "Balancing", "Hashing"], answer: 1, exp: "The Euler tour linearizes the tree; subtrees become contiguous ranges." },
  { id: "tv-38", topic: "algo-traversals", q: "The number of times an edge (u, v) is examined during DFS of an undirected graph is:", options: ["Once", "Twice (once from each endpoint)", "V times", "E times"], answer: 1, exp: "It appears in both adj[u] and adj[v]; total edge work is O(E)." },
  { id: "tv-39", topic: "algo-traversals", q: "Which traversal would compute the diameter of a tree with two passes?", options: ["Two BFS/DFS: from any node find the farthest u; from u find the farthest v; dist(u,v) is the diameter", "One in-order traversal", "Level order once", "Post-order once"], answer: 0, exp: "The endpoint of the longest path from an arbitrary start is always a diameter endpoint (for unweighted or non-negative trees)." },
  { id: "tv-40", topic: "algo-traversals", q: "DFS-based cycle detection in a DIRECTED graph marks vertices with three states because:", options: ["It looks nicer", "It must distinguish 'in the current recursion stack' (gray) from 'fully processed' (black)", "It saves memory", "Two states suffice"], answer: 1, exp: "A back edge points to a gray vertex; an edge to a black vertex is a forward/cross edge, not a cycle." },
  { id: "tv-41", topic: "algo-traversals", q: "Level-order traversal that also records level boundaries lets you compute:", options: ["The tree's in-order", "Per-level sums, averages, rightmost node of each level, etc.", "The Catalan number", "The height in O(1)"], answer: 1, exp: "Processing the queue one level at a time enables level-wise aggregates." },
  { id: "tv-42", topic: "algo-traversals", q: "For an infinite or very large state space (e.g. a puzzle), which traversal risks non-termination without a depth limit?", options: ["BFS", "DFS", "Both equally", "Neither"], answer: 1, exp: "DFS can descend one branch forever; BFS explores by depth so it finds shallow goals but uses exponential memory." },
  { id: "tv-43", topic: "algo-traversals", q: "Bidirectional BFS searches from both source and target and can reduce the explored nodes from O(b^d) to about:", options: ["O(b^d)", "O(b^(d/2))", "O(d)", "O(b)"], answer: 1, exp: "Two frontiers of depth d/2 meet in the middle." },
  { id: "tv-44", topic: "algo-traversals", q: "In a DAG, a topological order exists and can be found in:", options: ["O(V^2)", "O(V + E)", "O(E log V)", "O(V!)"], answer: 1, exp: "Kahn's algorithm (in-degree queue) or DFS finish-time reversal." },
  { id: "tv-45", topic: "algo-traversals", q: "The 'discovery time' and 'finish time' intervals of two vertices in a DFS forest are either:", options: ["Always overlapping", "Nested or disjoint (parenthesis property), never partially overlapping", "Always equal", "Random"], answer: 1, exp: "The parenthesis theorem: [d[u], f[u]] and [d[v], f[v]] are disjoint or one contains the other." },
  { id: "tv-46", topic: "algo-traversals", q: "To serialize and later deserialize a binary tree, a common choice is:", options: ["In-order alone", "Pre-order with NULL markers", "Just the node values sorted", "Level order without markers"], answer: 1, exp: "NULL markers preserve structure for exact reconstruction." },
  { id: "tv-47", topic: "algo-traversals", q: "The order in which Kahn's algorithm outputs vertices is:", options: ["Unique", "One of possibly many valid topological orders", "Reverse BFS", "Sorted by id"], answer: 1, exp: "Ties among in-degree-0 vertices can be broken arbitrarily (or by a rule like smallest id)." },
  { id: "tv-48", topic: "algo-traversals", q: "DFS of a graph produces a DFS forest with how many trees?", options: ["Always 1", "One per call to DFS-visit from the top-level loop (= number of components for undirected graphs)", "V", "E"], answer: 1, exp: "Each unvisited vertex the outer loop starts from roots a new DFS tree." },
  { id: "tv-49", topic: "algo-traversals", q: "Which is TRUE about traversing a graph with negative-weight edges?", options: ["BFS/DFS ignore weights; they only care about connectivity/structure", "DFS finds shortest paths", "BFS handles negatives fine", "You cannot traverse such graphs"], answer: 0, exp: "Plain BFS/DFS are weight-agnostic; shortest paths with negatives need Bellman-Ford." },
  { id: "tv-50", topic: "algo-traversals", q: "Flattening a binary tree to a linked list 'in place' following pre-order can be done with:", options: ["O(n) extra space always", "O(1) extra space (Morris-style: move the left subtree between the node and its right child)", "A queue of size n", "Two stacks"], answer: 1, exp: "Rewire pointers during a single walk without an auxiliary structure." },

  // ================= Searching (50) =================
  { id: "se-01", topic: "algo-searching", q: "Linear search on an unsorted array of n elements is:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 2, exp: "In the worst case every element must be checked." },
  { id: "se-02", topic: "algo-searching", q: "Binary search requires the data to be:", options: ["Unsorted", "Sorted (and randomly accessible)", "Hashed", "In a linked list"], answer: 1, exp: "It relies on comparing with the middle element to discard half the range." },
  { id: "se-03", topic: "algo-searching", q: "Binary search on n elements does at most about how many comparisons?", options: ["n", "n/2", "floor(log2 n) + 1", "sqrt n"], answer: 2, exp: "The range halves each step until it is empty." },
  { id: "se-04", topic: "algo-searching", q: "The midpoint in binary search should be computed as:", options: ["(lo + hi) / 2", "lo + (hi - lo) / 2 (avoids integer overflow)", "hi / 2", "(lo * hi) / 2"], answer: 1, exp: "lo + (hi - lo)/2 is equivalent but never overflows for large lo + hi." },
  { id: "se-05", topic: "algo-searching", q: "Hash table search has average time:", options: ["O(1)", "O(log n)", "O(n)", "O(sqrt n)"], answer: 0, exp: "A good hash function with bounded load factor gives expected constant-time lookup." },
  { id: "se-06", topic: "algo-searching", q: "The worst-case time for a hash table lookup is:", options: ["O(1)", "O(log n)", "O(n) (all keys in one bucket / long probe sequence)", "O(n log n)"], answer: 2, exp: "Adversarial keys or a poor hash collapse the table to a list." },
  { id: "se-07", topic: "algo-searching", q: "Interpolation search on uniformly distributed sorted data has average time:", options: ["O(log n)", "O(log log n)", "O(n)", "O(1)"], answer: 1, exp: "It guesses the position by linear interpolation; worst case (non-uniform) is O(n)." },
  { id: "se-08", topic: "algo-searching", q: "Exponential search is useful for:", options: ["Unsorted arrays", "Sorted arrays of unknown or unbounded size — find a range in O(log i), then binary search", "Hash tables", "Graphs"], answer: 1, exp: "Double the index until you overshoot, then binary search the last interval." },
  { id: "se-09", topic: "algo-searching", q: "Searching for a key in a balanced BST is:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 1, exp: "Height is O(log n); one comparison per level." },
  { id: "se-10", topic: "algo-searching", q: "Searching an unbalanced (degenerate) BST is:", options: ["O(log n)", "O(n)", "O(1)", "O(sqrt n)"], answer: 1, exp: "A chain-shaped tree behaves like a linked list." },
  { id: "se-11", topic: "algo-searching", q: "Which search finds the FIRST occurrence of a key in a sorted array with duplicates?", options: ["Plain binary search", "Lower-bound binary search (keep going left on a match)", "Linear search from the end", "Hashing"], answer: 1, exp: "On a match, record it and continue searching the left half." },
  { id: "se-12", topic: "algo-searching", q: "Binary search can also be used to find:", options: ["Only exact matches", "The smallest x such that a monotonic predicate p(x) is true ('binary search on the answer')", "Elements in a hash set", "The median in O(1)"], answer: 1, exp: "Any monotone boolean condition over an ordered domain is binary-searchable." },
  { id: "se-13", topic: "algo-searching", q: "Ternary search is used to find:", options: ["An element in a sorted array (faster than binary)", "The extremum of a unimodal function", "A key in a hash table", "The median"], answer: 1, exp: "It narrows to the peak/valley of a unimodal function; for sorted-array search it is slower than binary." },
  { id: "se-14", topic: "algo-searching", q: "Searching a rotated sorted array (distinct values) for a key takes:", options: ["O(n)", "O(log n) (modified binary search)", "O(n log n)", "O(1)"], answer: 1, exp: "At each step one half is normally sorted; decide which half could contain the target." },
  { id: "se-15", topic: "algo-searching", q: "A Bloom filter answers membership queries with:", options: ["Exact yes/no", "No false negatives, but possible false positives, using very little space", "No false positives", "O(n) space"], answer: 1, exp: "If it says 'not present' that is certain; 'present' may be wrong with a tunable probability." },
  { id: "se-16", topic: "algo-searching", q: "The KMP algorithm searches for a pattern of length m in text of length n in:", options: ["O(nm)", "O(n + m)", "O(n log m)", "O(m^2)"], answer: 1, exp: "It precomputes a failure function so the text pointer never backtracks." },
  { id: "se-17", topic: "algo-searching", q: "Rabin-Karp string search uses:", options: ["Suffix trees", "A rolling hash to compare the pattern hash with each window's hash in O(1) per shift", "Binary search", "A trie"], answer: 1, exp: "Average O(n + m); worst case O(nm) if many hash collisions occur." },
  { id: "se-18", topic: "algo-searching", q: "A trie searches for a string key of length L in:", options: ["O(L), independent of the number of stored keys", "O(log n)", "O(n)", "O(L log n)"], answer: 0, exp: "You follow one edge per character." },
  { id: "se-19", topic: "algo-searching", q: "Searching a sorted m x n matrix (rows and columns sorted) for a value is done in O(m + n) by:", options: ["Binary search on the flattened array", "Starting at the top-right (or bottom-left) corner and eliminating a row or column each step", "DFS", "Hashing every cell"], answer: 1, exp: "From the top-right: if too big go left, if too small go down." },
  { id: "se-20", topic: "algo-searching", q: "Which structure gives O(1) average membership AND ordered iteration is NOT needed?", options: ["Balanced BST", "Hash set", "Sorted array", "Linked list"], answer: 1, exp: "Hash set: constant expected lookup; use a BST/skip list when order matters." },
  { id: "se-21", topic: "algo-searching", q: "Jump search on a sorted array uses block size sqrt(n) and runs in:", options: ["O(log n)", "O(sqrt n)", "O(n)", "O(n log n)"], answer: 1, exp: "Jump sqrt(n) each step, then linear-scan the last block — total ~ 2 sqrt(n)." },
  { id: "se-22", topic: "algo-searching", q: "Searching for the k-th smallest element of an unsorted array takes (expected):", options: ["O(n log n) always", "O(n) using quickselect", "O(k)", "O(log n)"], answer: 1, exp: "Quickselect partitions and recurses on one side only; expected linear." },
  { id: "se-23", topic: "algo-searching", q: "To search efficiently for points in a 2D range, use a:", options: ["Hash table", "k-d tree or range tree", "Stack", "Linked list"], answer: 1, exp: "Spatial trees support O(log n + k) or O(sqrt n + k) range reporting." },
  { id: "se-24", topic: "algo-searching", q: "Binary search's invariant is:", options: ["The array is unsorted outside [lo, hi]", "If the key exists, it lies within [lo, hi]", "lo > hi always", "The middle element is the key"], answer: 1, exp: "Each step preserves that the target, if present, is still in the current window." },
  { id: "se-25", topic: "algo-searching", q: "A skip list searches in expected:", options: ["O(1)", "O(log n)", "O(n)", "O(sqrt n)"], answer: 1, exp: "Randomized express lanes let a search skip large gaps, like a balanced tree." },
  { id: "se-26", topic: "algo-searching", q: "Which is TRUE about searching a hash table vs a balanced BST?", options: ["BST is always faster", "Hash: O(1) avg but no order; BST: O(log n) with successor/range/min-max queries", "They are identical", "Hash tables cannot have collisions"], answer: 1, exp: "Pick the BST when ordered operations matter." },
  { id: "se-27", topic: "algo-searching", q: "Searching a B+ tree (database index) with n keys and fan-out f takes:", options: ["O(n)", "O(log_f n) node accesses (~ 3-4 disk reads)", "O(f log n)", "O(1)"], answer: 1, exp: "Large fan-out keeps the tree shallow, minimizing block I/O." },
  { id: "se-28", topic: "algo-searching", q: "Finding whether ANY pair in a sorted array sums to a target is done in:", options: ["O(n^2)", "O(n log n)", "O(n) with two pointers", "O(1)"], answer: 2, exp: "Move left pointer right if sum too small, right pointer left if too big." },
  { id: "se-29", topic: "algo-searching", q: "Which search is cache-unfriendly on large arrays?", options: ["Linear (sequential) search", "Binary search (jumps around memory)", "Both equally", "Neither"], answer: 1, exp: "Binary search's large index jumps cause cache misses; linear scan streams memory." },
  { id: "se-30", topic: "algo-searching", q: "The lower bound for comparison-based search in a sorted array is:", options: ["Omega(1)", "Omega(log n)", "Omega(n)", "Omega(n log n)"], answer: 1, exp: "A decision tree distinguishing n+1 outcomes has height >= log2(n+1)." },
  { id: "se-31", topic: "algo-searching", q: "'Binary search on the answer' is applicable when:", options: ["The feasibility function is monotonic in the parameter", "The array is unsorted", "There is no ordering", "The answer is a string"], answer: 0, exp: "E.g. minimize the max load: if capacity C works, any C' > C works — monotone." },
  { id: "se-32", topic: "algo-searching", q: "Searching an infinite sorted stream for a key: which technique?", options: ["Binary search from index 0 to infinity", "Exponential search: probe indices 1, 2, 4, 8, ... until you pass the key, then binary search", "Linear scan (may not terminate)", "Hashing"], answer: 1, exp: "Doubling finds a bounding range in O(log p) where p is the key's position." },
  { id: "se-33", topic: "algo-searching", q: "The number of probes for an unsuccessful search in a hash table with chaining and load factor alpha is expected:", options: ["O(alpha)", "O(1 + alpha)", "O(n)", "O(log n)"], answer: 1, exp: "O(1) to hash plus the expected chain length alpha." },
  { id: "se-34", topic: "algo-searching", q: "Which is a disadvantage of binary search vs hashing?", options: ["It requires sorted data (O(n log n) preprocessing or O(n) per insert to maintain)", "It is slower asymptotically", "It cannot find exact matches", "It uses more memory"], answer: 0, exp: "Maintaining sorted order under insertions is costly; hash tables insert in O(1) average." },
  { id: "se-35", topic: "algo-searching", q: "Finding the peak element (a[i] >= neighbors) in an array can be done in:", options: ["O(n) only", "O(log n) by binary search — move toward the larger neighbor", "O(n log n)", "O(1)"], answer: 1, exp: "There is always a peak in the direction of the larger neighbor." },
  { id: "se-36", topic: "algo-searching", q: "Aho-Corasick searches for MULTIPLE patterns in text simultaneously in:", options: ["O(n * number of patterns)", "O(n + total pattern length + number of matches)", "O(n^2)", "O(n log n)"], answer: 1, exp: "It builds a trie with failure links (a KMP generalization) and scans the text once." },
  { id: "se-37", topic: "algo-searching", q: "A self-balancing tree is chosen over a hash table for a dictionary when you also need:", options: ["Faster point lookups", "Range queries, ordered iteration, predecessor/successor", "Less code", "Case-insensitive keys"], answer: 1, exp: "Order-based operations are the BST's advantage." },
  { id: "se-38", topic: "algo-searching", q: "Searching a suffix array of a text (length n) for a pattern (length m) takes:", options: ["O(m log n) with binary search over suffixes", "O(n)", "O(nm)", "O(1)"], answer: 0, exp: "Binary search the sorted suffixes, comparing up to m characters each step (O(m + log n) with LCP arrays)." },
  { id: "se-39", topic: "algo-searching", q: "Which search structure supports approximate nearest-neighbor queries in high dimensions?", options: ["Balanced BST", "Locality-sensitive hashing (LSH) or HNSW graphs", "Linked list", "Stack"], answer: 1, exp: "Exact NN suffers the 'curse of dimensionality'; LSH/HNSW give fast approximate results." },
  { id: "se-40", topic: "algo-searching", q: "Binary search returns the insertion point when the key is absent if you:", options: ["Return -1", "Return lo (the first index where a[i] >= key) — i.e. lower_bound", "Return hi", "Throw an error"], answer: 1, exp: "After the loop, lo is where the key would be inserted to keep the array sorted." },
  { id: "se-41", topic: "algo-searching", q: "The expected cost of a successful search in a randomly built BST is:", options: ["O(1)", "O(log n)", "O(sqrt n)", "O(n)"], answer: 1, exp: "Expected depth of a node in a random BST is O(log n)." },
  { id: "se-42", topic: "algo-searching", q: "For 'does the array contain a duplicate?' the fastest general approach is:", options: ["Sort then scan: O(n log n); or a hash set: O(n) time, O(n) space", "O(n^2) nested loop", "Binary search", "Impossible in less than O(n^2)"], answer: 0, exp: "Hash set membership check per element is expected O(n)." },
  { id: "se-43", topic: "algo-searching", q: "Which best describes 'searching' vs 'sorting' preprocessing tradeoff?", options: ["Never sort before searching", "If you search many times, an O(n log n) sort (or O(n) hash build) pays off vs repeated O(n) linear scans", "Sorting makes search slower", "They are unrelated"], answer: 1, exp: "Amortize preprocessing over many queries." },
  { id: "se-44", topic: "algo-searching", q: "The number of comparisons in binary search on 1,000,000 elements is at most about:", options: ["1000", "20", "500000", "1000000"], answer: 1, exp: "log2(10^6) ~ 19.9, so ~20 comparisons." },
  { id: "se-45", topic: "algo-searching", q: "In a min-heap, searching for an arbitrary value is:", options: ["O(1)", "O(log n)", "O(n)", "O(n log n)"], answer: 2, exp: "Heaps are not ordered for search; you may scan the whole array." },
  { id: "se-46", topic: "algo-searching", q: "Fibonacci search divides the array using Fibonacci numbers and is useful when:", options: ["Data is unsorted", "Division is expensive (it uses only addition/subtraction) and access is non-uniform (e.g. tape)", "The array is tiny", "There are duplicates"], answer: 1, exp: "It avoids the division in binary search's midpoint computation." },
  { id: "se-47", topic: "algo-searching", q: "Searching for all anagrams of a pattern in a text uses:", options: ["A sliding window with a character-count comparison, O(n)", "Sorting the whole text", "Binary search", "A suffix tree only"], answer: 0, exp: "Slide a window of the pattern's length, maintaining a frequency table." },
  { id: "se-48", topic: "algo-searching", q: "Which is TRUE of searching in external memory (data on disk)?", options: ["Binary search on a sorted file is optimal", "B-tree / B+ tree structures minimize block transfers (O(log_B n) I/Os)", "Hashing is impossible", "Linear scan is fastest"], answer: 1, exp: "High branching factor per block is the key to few I/Os." },
  { id: "se-49", topic: "algo-searching", q: "The two-pointer search on a sorted array for a target sum has space complexity:", options: ["O(n)", "O(log n)", "O(1)", "O(n log n)"], answer: 2, exp: "Just two index variables." },
  { id: "se-50", topic: "algo-searching", q: "When a dataset changes rarely but is queried often, the best search strategy is:", options: ["Keep it unsorted and linear-search", "Sort once (or build a hash/index once) and answer each query in O(log n) / O(1)", "Rebuild the structure per query", "Use DFS"], answer: 1, exp: "Preprocessing cost is amortized over many fast queries." },

  // ================= Sorting & Hashing (50) =================
  { id: "so-01", topic: "algo-sorting-hashing", q: "The comparison-sort lower bound is:", options: ["Omega(n)", "Omega(n log n)", "Omega(n^2)", "Omega(log n)"], answer: 1, exp: "A decision tree with n! leaves has height >= log2(n!) = Omega(n log n)." },
  { id: "so-02", topic: "algo-sorting-hashing", q: "Which sort is NOT comparison-based?", options: ["Merge sort", "Quicksort", "Counting sort", "Heapsort"], answer: 2, exp: "Counting/radix/bucket sorts use key values directly, bypassing the n log n bound." },
  { id: "so-03", topic: "algo-sorting-hashing", q: "Merge sort time / space:", options: ["O(n log n) / O(n)", "O(n^2) / O(1)", "O(n log n) / O(1)", "O(n) / O(n)"], answer: 0, exp: "Always n log n; needs an O(n) merge buffer." },
  { id: "so-04", topic: "algo-sorting-hashing", q: "Quicksort average / worst time:", options: ["O(n log n) / O(n log n)", "O(n log n) / O(n^2)", "O(n^2) / O(n^2)", "O(n) / O(n log n)"], answer: 1, exp: "Bad pivots on sorted data cause the O(n^2) worst case." },
  { id: "so-05", topic: "algo-sorting-hashing", q: "Heapsort time / space:", options: ["O(n log n) / O(1)", "O(n log n) / O(n)", "O(n^2) / O(1)", "O(n) / O(1)"], answer: 0, exp: "In-place, always n log n, but not stable and cache-unfriendly." },
  { id: "so-06", topic: "algo-sorting-hashing", q: "A stable sort:", options: ["Runs in stable (predictable) time", "Preserves the relative order of equal keys", "Uses O(1) space", "Is always faster"], answer: 1, exp: "Stability matters when sorting by multiple keys in succession." },
  { id: "so-07", topic: "algo-sorting-hashing", q: "Which sorts are stable (typical implementations)?", options: ["Quicksort and heapsort", "Merge sort, insertion sort, counting sort, bubble sort", "Heapsort and selection sort", "Only radix sort"], answer: 1, exp: "Quicksort, heapsort and selection sort are not stable as usually written." },
  { id: "so-08", topic: "algo-sorting-hashing", q: "Insertion sort is preferred when:", options: ["n is very large", "The array is small or nearly sorted", "Stability is not needed", "Memory is unlimited"], answer: 1, exp: "O(n) on nearly-sorted input; low overhead makes it the base case in introsort/timsort." },
  { id: "so-09", topic: "algo-sorting-hashing", q: "Counting sort runs in O(n + k) where k is:", options: ["The number of elements", "The range of key values", "log n", "The number of distinct values only"], answer: 1, exp: "It is efficient only when k = O(n); huge ranges make it impractical." },
  { id: "so-10", topic: "algo-sorting-hashing", q: "Radix sort (LSD) on n numbers of d digits in base b runs in:", options: ["O(nd)", "O(d(n + b))", "O(n log n)", "O(n^2)"], answer: 1, exp: "d passes of counting sort, each O(n + b)." },
  { id: "so-11", topic: "algo-sorting-hashing", q: "Bucket sort assumes the input is:", options: ["Sorted", "Drawn from a uniform distribution over a known range", "All equal", "Negative"], answer: 1, exp: "Uniform data spreads evenly across buckets, giving O(n) expected time." },
  { id: "so-12", topic: "algo-sorting-hashing", q: "Which sort does the FEWEST swaps/writes (good for flash memory)?", options: ["Bubble sort", "Selection sort (at most n-1 swaps)", "Insertion sort", "Merge sort"], answer: 1, exp: "Selection sort makes exactly one swap per outer iteration." },
  { id: "so-13", topic: "algo-sorting-hashing", q: "Timsort (used in Python/Java) is a hybrid of:", options: ["Quicksort and heapsort", "Merge sort and insertion sort, exploiting existing runs", "Radix and counting sort", "Heapsort and bucket sort"], answer: 1, exp: "It finds natural sorted runs and merges them, using insertion sort for small runs." },
  { id: "so-14", topic: "algo-sorting-hashing", q: "Introsort begins as quicksort and switches to ____ when recursion gets too deep:", options: ["Merge sort", "Heapsort (to guarantee O(n log n) worst case)", "Bubble sort", "Counting sort"], answer: 1, exp: "The depth-limit fallback caps the worst case; it also uses insertion sort for tiny partitions." },
  { id: "so-15", topic: "algo-sorting-hashing", q: "The number of swaps to sort with selection sort is:", options: ["O(n^2)", "O(n)", "O(n log n)", "O(1)"], answer: 1, exp: "One swap per position, though it still does O(n^2) comparisons." },
  { id: "so-16", topic: "algo-sorting-hashing", q: "Which pivot strategy avoids quicksort's O(n^2) on sorted input?", options: ["Always first element", "Random pivot or median-of-three", "Always last element", "Always the smallest"], answer: 1, exp: "Randomization/median-of-three make maximally unbalanced splits improbable." },
  { id: "so-17", topic: "algo-sorting-hashing", q: "A hash function should ideally:", options: ["Map all keys to the same bucket", "Distribute keys uniformly and be fast to compute", "Be slow for security", "Depend on insertion order"], answer: 1, exp: "Uniform spreading minimizes collisions; speed keeps operations O(1)." },
  { id: "so-18", topic: "algo-sorting-hashing", q: "Collision resolution by 'separate chaining' stores colliding keys in:", options: ["The next empty slot", "A linked list (or tree) per bucket", "A second table", "The previous slot"], answer: 1, exp: "Each bucket holds a list; lookup scans that bucket's chain." },
  { id: "so-19", topic: "algo-sorting-hashing", q: "Open addressing resolves collisions by:", options: ["Chaining", "Probing for another open slot (linear, quadratic, or double hashing)", "Resizing immediately", "Rejecting the key"], answer: 1, exp: "All entries live in the table array itself; the probe sequence finds a free cell." },
  { id: "so-20", topic: "algo-sorting-hashing", q: "Linear probing suffers from:", options: ["Secondary clustering", "Primary clustering — long contiguous runs of occupied slots", "No clustering", "Underflow"], answer: 1, exp: "Adjacent collisions merge into long runs, degrading probe length." },
  { id: "so-21", topic: "algo-sorting-hashing", q: "Double hashing uses a second hash function to:", options: ["Compute the initial bucket", "Determine the probe step size, avoiding primary and secondary clustering", "Resize the table", "Hash the value not the key"], answer: 1, exp: "h(k, i) = (h1(k) + i * h2(k)) mod m spreads probes out." },
  { id: "so-22", topic: "algo-sorting-hashing", q: "The load factor alpha of a hash table is:", options: ["m / n", "n / m (entries / buckets)", "The number of collisions", "Always 1"], answer: 1, exp: "Performance degrades as alpha approaches 1 (open addressing) or grows large (chaining)." },
  { id: "so-23", topic: "algo-sorting-hashing", q: "When a hash table's load factor exceeds a threshold, it is:", options: ["Cleared", "Resized (rehashed) to a larger table, an amortized O(1) cost per insert", "Converted to a BST", "Left as is"], answer: 1, exp: "Doubling the table and rehashing all keys keeps average operations O(1)." },
  { id: "so-24", topic: "algo-sorting-hashing", q: "Universal hashing means:", options: ["One hash function for all data types", "Choosing the hash function randomly from a family so no fixed input set is consistently bad", "A cryptographic hash", "A perfect hash"], answer: 1, exp: "It guarantees low expected collisions for ANY key set, defeating adversaries." },
  { id: "so-25", topic: "algo-sorting-hashing", q: "A perfect hash function:", options: ["Is impossible", "Maps a known static key set to distinct slots with no collisions", "Uses chaining", "Is slow"], answer: 1, exp: "For a fixed dictionary, a two-level (FKS) scheme gives O(1) worst-case lookup." },
  { id: "so-26", topic: "algo-sorting-hashing", q: "Cuckoo hashing guarantees:", options: ["O(1) amortized insert only", "O(1) WORST-CASE lookup (each key is in one of two possible slots)", "O(log n) lookup", "No resizing ever"], answer: 1, exp: "Insertion may cascade (kicking out existing keys) and occasionally triggers a rehash." },
  { id: "so-27", topic: "algo-sorting-hashing", q: "Which sort is best for sorting records by an integer key in a small fixed range, stably, in linear time?", options: ["Quicksort", "Counting sort", "Heapsort", "Merge sort"], answer: 1, exp: "Counting sort is O(n + k), stable, and ideal for small key ranges." },
  { id: "so-28", topic: "algo-sorting-hashing", q: "External merge sort is used when:", options: ["Data fits in RAM", "Data is too large for memory — sort chunks, write runs, then k-way merge from disk", "The data is already sorted", "n is small"], answer: 1, exp: "It minimizes disk I/O by merging sorted runs." },
  { id: "so-29", topic: "algo-sorting-hashing", q: "The partition step of quicksort (Lomuto or Hoare) runs in:", options: ["O(1)", "O(log n)", "O(n) for a subarray of size n", "O(n log n)"], answer: 2, exp: "One linear scan places the pivot and splits the rest." },
  { id: "so-30", topic: "algo-sorting-hashing", q: "Which sort has O(n) best case AND O(n^2) worst case AND is stable?", options: ["Insertion sort", "Selection sort", "Heapsort", "Quicksort"], answer: 0, exp: "Insertion sort: O(n) on sorted input, O(n^2) on reverse-sorted, stable." },
  { id: "so-31", topic: "algo-sorting-hashing", q: "3-way quicksort (Dutch flag partition) is efficient when the array has:", options: ["All distinct keys", "Many duplicate keys", "Negative numbers", "Been pre-sorted"], answer: 1, exp: "It groups elements equal to the pivot, avoiding O(n^2) on many-duplicates input." },
  { id: "so-32", topic: "algo-sorting-hashing", q: "Shell sort improves insertion sort by:", options: ["Using recursion", "Comparing and shifting elements far apart first (gap sequence), then smaller gaps", "Using a heap", "Hashing"], answer: 1, exp: "Large-gap passes move elements near their final position cheaply; final gap of 1 is ordinary insertion sort." },
  { id: "so-33", topic: "algo-sorting-hashing", q: "For sorting strings, which is often best?", options: ["Comparison sort with string compares (O(n log n) compares, each O(L))", "Radix sort / MSD string sort or a ternary search trie for O(total length)", "Counting sort on the whole string", "Bucket sort only"], answer: 1, exp: "Character-by-character radix approaches avoid repeated full-string comparisons." },
  { id: "so-34", topic: "algo-sorting-hashing", q: "The hash of a string is often computed as a polynomial: h = sum(s[i] * p^i) mod m. p and m should be:", options: ["Both even", "Coprime, with p a small prime > alphabet size and m a large prime", "Both 1", "Powers of two"], answer: 1, exp: "This reduces collisions and enables O(1) rolling updates (Rabin-Karp)." },
  { id: "so-35", topic: "algo-sorting-hashing", q: "Which operation is O(1) average in a hash table but O(log n) in a balanced BST?", options: ["Find the minimum", "Insert / lookup / delete by key", "In-order traversal", "Successor query"], answer: 1, exp: "Hash tables win on point operations; BSTs win on ordered operations." },
  { id: "so-36", topic: "algo-sorting-hashing", q: "The main downside of open addressing vs chaining is:", options: ["It uses more memory", "Performance degrades sharply as the load factor nears 1; deletion needs tombstones", "It cannot resize", "It has no O(1) case"], answer: 1, exp: "Deleted slots must be marked (not emptied) so probe sequences are not broken." },
  { id: "so-37", topic: "algo-sorting-hashing", q: "Sorting n elements each in the range [0, n^3 - 1] can be done in O(n) using:", options: ["Comparison sort", "Radix sort with base n (3 digits)", "Counting sort with k = n^3 (too much space)", "Bucket sort only"], answer: 1, exp: "3 passes of counting sort in base n: O(3(n + n)) = O(n)." },
  { id: "so-38", topic: "algo-sorting-hashing", q: "Which is TRUE about merge sort vs quicksort in practice?", options: ["Merge sort is usually faster in memory", "Quicksort is usually faster in memory due to smaller constants and cache locality; merge sort is preferred for stability and linked lists / external sorting", "They are identical", "Quicksort cannot be done in place"], answer: 1, exp: "Standard library sorts often use introsort (quicksort-based) for arrays, timsort (merge-based) where stability matters." },
  { id: "so-39", topic: "algo-sorting-hashing", q: "A consistent hashing scheme (used in distributed caches) minimizes:", options: ["Collisions", "The number of keys that must move when a server is added or removed", "Memory", "Computation"], answer: 1, exp: "Only ~1/n of keys remap when the server set changes, vs nearly all with naive modulo hashing." },
  { id: "so-40", topic: "algo-sorting-hashing", q: "The expected length of the longest chain in a hash table with n keys and n buckets is:", options: ["O(1)", "Theta(log n / log log n)", "O(log n)", "O(n)"], answer: 1, exp: "This 'balls into bins' result explains why worst-case chained lookup is slightly super-constant." },
  { id: "so-41", topic: "algo-sorting-hashing", q: "'Power of two choices' hashing reduces the max load to:", options: ["O(log n)", "O(log log n) — a large improvement over O(log n / log log n)", "O(1) guaranteed", "O(n)"], answer: 1, exp: "Placing each key in the less-loaded of two hashed buckets exponentially reduces the max chain." },
  { id: "so-42", topic: "algo-sorting-hashing", q: "Which sorting algorithm is adaptive (faster on partially sorted input)?", options: ["Selection sort", "Insertion sort / timsort / bubble-with-flag", "Heapsort", "Standard merge sort"], answer: 1, exp: "Adaptive sorts exploit existing order; selection and heap sort do not." },
  { id: "so-43", topic: "algo-sorting-hashing", q: "The 'birthday paradox' is relevant to hashing because:", options: ["Hashes never collide", "Collisions become likely after only ~sqrt(m) insertions into m buckets", "It speeds up lookup", "It affects sorting"], answer: 1, exp: "With m slots, expect a collision after roughly 1.25*sqrt(m) keys." },
  { id: "so-44", topic: "algo-sorting-hashing", q: "To sort a nearly-sorted array where each element is at most k positions from its target:", options: ["Quicksort", "A min-heap of size k+1: O(n log k)", "Counting sort", "Selection sort"], answer: 1, exp: "The next smallest element is always within the next k+1, so a small heap suffices." },
  { id: "so-45", topic: "algo-sorting-hashing", q: "Cryptographic hash functions (SHA-256) differ from hash-table hash functions in that they emphasize:", options: ["Speed above all", "Collision resistance and preimage resistance (security), at the cost of speed", "Small output", "Reversibility"], answer: 1, exp: "Hash-table functions optimize speed and distribution, not adversarial resistance." },
  { id: "so-46", topic: "algo-sorting-hashing", q: "The number of comparisons in the worst case of heapsort is:", options: ["Theta(n)", "Theta(n log n)", "Theta(n^2)", "Theta(log n)"], answer: 1, exp: "n extract-max operations, each doing O(log n) comparisons during sift-down." },
  { id: "so-47", topic: "algo-sorting-hashing", q: "Which is TRUE about sorting stability and multi-key sorting?", options: ["Stability is irrelevant", "Sort by the least significant key first with a stable sort, then by the next key, etc. (LSD radix idea)", "You must sort by the most significant key first", "Only unstable sorts allow multi-key"], answer: 1, exp: "Stable sorting from least to most significant key produces a correct lexicographic order." },
  { id: "so-48", topic: "algo-sorting-hashing", q: "A hash set is a poor choice when you need to:", options: ["Test membership quickly", "Iterate keys in sorted order or find the closest key to a query", "Insert quickly", "Delete quickly"], answer: 1, exp: "Hashing destroys order; use a balanced BST / skip list for ordered access." },
  { id: "so-49", topic: "algo-sorting-hashing", q: "The best worst-case comparison sort with O(1) extra space is:", options: ["Merge sort", "Heapsort", "Quicksort", "Insertion sort"], answer: 1, exp: "Heapsort: guaranteed O(n log n), in place. (In-place stable merge sort exists but is complex/slow.)" },
  { id: "so-50", topic: "algo-sorting-hashing", q: "Given 10^7 32-bit integers to sort with limited RAM, a strong choice is:", options: ["Bubble sort", "Radix sort (or external merge sort if RAM is tiny)", "Selection sort", "Insertion sort"], answer: 1, exp: "Radix sort is O(n) for fixed-width integers; external merge sort handles the out-of-core case." },

  // ================= Greedy Algorithms (50) =================
  { id: "gr-01", topic: "algo-greedy", q: "A greedy algorithm builds a solution by:", options: ["Trying all combinations", "Making the locally optimal choice at each step, never reconsidering", "Working backward from the goal", "Random sampling"], answer: 1, exp: "It commits to the best immediate option and hopes (or proves) it leads to a global optimum." },
  { id: "gr-02", topic: "algo-greedy", q: "For a greedy algorithm to be correct, the problem must have:", options: ["Overlapping subproblems", "The greedy-choice property AND optimal substructure", "A convex objective only", "No constraints"], answer: 1, exp: "Greedy-choice property: a globally optimal solution can be reached by locally optimal choices." },
  { id: "gr-03", topic: "algo-greedy", q: "The activity-selection problem (max non-overlapping intervals) is solved greedily by:", options: ["Picking the shortest activity first", "Picking the activity that finishes earliest, then repeating among the compatible rest", "Picking the one that starts earliest", "Dynamic programming only"], answer: 1, exp: "Earliest finish time leaves the most room for subsequent activities. O(n log n) after sorting." },
  { id: "gr-04", topic: "algo-greedy", q: "The fractional knapsack problem is solved greedily by:", options: ["Taking items in order of value", "Taking items in decreasing value/weight ratio, splitting the last one", "Dynamic programming", "Taking the lightest items first"], answer: 1, exp: "Fractions are allowed, so the best value density always wins; O(n log n)." },
  { id: "gr-05", topic: "algo-greedy", q: "The 0/1 knapsack problem (no splitting) is:", options: ["Solved greedily by value/weight ratio", "NOT solvable by that greedy strategy; it needs dynamic programming", "Always O(n log n)", "In P only for small values"], answer: 1, exp: "A counterexample: the highest-ratio item can block a better combination of others." },
  { id: "gr-06", topic: "algo-greedy", q: "Huffman coding is a greedy algorithm that repeatedly:", options: ["Splits the highest-frequency symbol", "Merges the two lowest-frequency nodes into a subtree", "Assigns fixed-length codes", "Sorts the whole alphabet"], answer: 1, exp: "A priority queue yields the two rarest nodes; merging them O(n log n) total produces an optimal prefix code." },
  { id: "gr-07", topic: "algo-greedy", q: "Which MST algorithm is greedy?", options: ["Only Kruskal", "Only Prim", "Both Kruskal and Prim", "Neither"], answer: 2, exp: "Both add the safe/cheapest edge at each step; the cut property proves correctness." },
  { id: "gr-08", topic: "algo-greedy", q: "Dijkstra's shortest-path algorithm is greedy because it:", options: ["Tries all paths", "Permanently finalizes the closest unvisited vertex at each step", "Uses recursion", "Relaxes edges in random order"], answer: 1, exp: "The greedy choice (nearest frontier vertex) is provably correct only with non-negative weights." },
  { id: "gr-09", topic: "algo-greedy", q: "The coin-change problem with coins {1, 5, 10, 25} and greedy (largest coin first) is:", options: ["Always optimal for any coin system", "Optimal for this 'canonical' system, but NOT for arbitrary systems", "Never optimal", "Optimal only for even amounts"], answer: 1, exp: "Greedy fails for e.g. coins {1, 3, 4} making 6 (gives 4+1+1, optimal is 3+3)." },
  { id: "gr-10", topic: "algo-greedy", q: "Interval scheduling to MINIMIZE the number of resources (rooms) for all intervals uses:", options: ["Earliest finish time", "Sort by start time; use a min-heap of end times to reuse a free room", "Longest interval first", "Random assignment"], answer: 1, exp: "The heap size peaks at the maximum number of simultaneously overlapping intervals." },
  { id: "gr-11", topic: "algo-greedy", q: "The greedy exchange argument proves correctness by:", options: ["Induction on n", "Showing any optimal solution can be transformed into the greedy one without getting worse", "Contradiction with the master theorem", "Enumeration"], answer: 1, exp: "Swap the optimal's first differing choice for the greedy choice; repeat." },
  { id: "gr-12", topic: "algo-greedy", q: "Job sequencing with deadlines (maximize profit, each job takes unit time) is solved greedily by:", options: ["Earliest deadline first", "Sort jobs by profit descending; schedule each in the latest free slot before its deadline", "Shortest job first", "DP over subsets"], answer: 1, exp: "A disjoint-set structure finds the latest free slot in near-constant time." },
  { id: "gr-13", topic: "algo-greedy", q: "Which is a hallmark that greedy will NOT work and DP is needed?", options: ["The problem has independent subproblems", "A locally optimal choice can be regretted later (no greedy-choice property)", "There is a single constraint", "The input is sorted"], answer: 1, exp: "If early choices lock out better global options, you must consider alternatives (DP/backtracking)." },
  { id: "gr-14", topic: "algo-greedy", q: "The minimum number of platforms needed at a railway station given arrival/departure times is found by:", options: ["Counting trains", "Sorting arrivals and departures separately and sweeping to track the max overlap", "DP", "Greedy by train length"], answer: 1, exp: "Increment a counter on each arrival, decrement on each departure; the peak is the answer." },
  { id: "gr-15", topic: "algo-greedy", q: "The 'gas station' problem (can you complete the circular tour?) has a greedy O(n) solution based on:", options: ["Trying every start", "If total gas >= total cost, the start is the index right after the point where the running tank goes most negative", "Sorting stations", "DP"], answer: 1, exp: "A single pass tracks the running surplus and the best restart point." },
  { id: "gr-16", topic: "algo-greedy", q: "Prim's algorithm's greedy choice is:", options: ["The globally lightest edge", "The lightest edge crossing the cut between the tree and the rest", "The lightest edge from the last-added vertex", "A random safe edge"], answer: 1, exp: "The cut property guarantees this edge is in some MST." },
  { id: "gr-17", topic: "algo-greedy", q: "Kruskal's algorithm's greedy choice is:", options: ["The lightest edge crossing a specific cut", "The globally lightest remaining edge that does not create a cycle", "The heaviest edge to remove", "Any edge incident to the tree"], answer: 1, exp: "Union-find rejects edges that would form a cycle." },
  { id: "gr-18", topic: "algo-greedy", q: "A matroid guarantees that:", options: ["Greedy fails", "The greedy algorithm finds a maximum-weight independent set", "DP is required", "The problem is NP-hard"], answer: 1, exp: "Matroid theory formalizes exactly when greedy is optimal (e.g. MST via the graphic matroid)." },
  { id: "gr-19", topic: "algo-greedy", q: "The greedy algorithm for minimum number of coins fails for {1, 3, 4}, amount 6. The DP answer is:", options: ["3 coins (4 + 1 + 1)", "2 coins (3 + 3)", "6 coins", "Impossible"], answer: 1, exp: "Greedy takes 4 then 1 + 1 = 3 coins; DP finds 3 + 3 = 2 coins." },
  { id: "gr-20", topic: "algo-greedy", q: "Which sorting order does the activity-selection greedy require?", options: ["By start time", "By finish time (ascending)", "By duration", "By number of conflicts"], answer: 1, exp: "Finish time ascending is essential to the proof." },
  { id: "gr-21", topic: "algo-greedy", q: "Greedy graph coloring (color each vertex with the smallest color not used by neighbors) uses at most:", options: ["2 colors", "(max degree + 1) colors", "chi(G) colors always (optimal)", "n colors always"], answer: 1, exp: "It is not optimal in general but bounded by Delta + 1." },
  { id: "gr-22", topic: "algo-greedy", q: "The 'largest sum after k merges' / 'connect ropes with minimum cost' problem is greedy via:", options: ["A max-heap", "A min-heap: repeatedly combine the two smallest ropes", "Sorting once", "DP"], answer: 1, exp: "Like Huffman: always merge the two cheapest to minimize total merge cost." },
  { id: "gr-23", topic: "algo-greedy", q: "Which is TRUE about greedy vs dynamic programming?", options: ["Greedy explores more states", "Greedy is faster (no table) but only correct for a subset of problems; DP is more general", "DP is always faster", "They solve disjoint problem sets"], answer: 1, exp: "Every greedy-solvable problem is DP-solvable, but not vice versa." },
  { id: "gr-24", topic: "algo-greedy", q: "The minimum spanning tree is unique if:", options: ["The graph is connected", "All edge weights are distinct", "It has no cycles", "It is a tree already"], answer: 1, exp: "Distinct weights force a unique safe edge at every cut." },
  { id: "gr-25", topic: "algo-greedy", q: "For 'minimum number of arrows to burst all balloons' (interval point cover), greedy sorts by:", options: ["Start point", "End point; shoot at the end of the first balloon, skip all it covers, repeat", "Width", "Center"], answer: 1, exp: "Same structure as activity selection." },
  { id: "gr-26", topic: "algo-greedy", q: "Greedy best-first search in AI orders the frontier by:", options: ["g(n) (path cost so far)", "h(n) (heuristic estimate to goal) only", "g(n) + h(n)", "Random"], answer: 1, exp: "It is fast but not optimal; A* uses f = g + h for optimality with an admissible h." },
  { id: "gr-27", topic: "algo-greedy", q: "The 'assign cookies' problem (greed factors vs cookie sizes, maximize content children) is greedy by:", options: ["Assigning the biggest cookie to the greediest child", "Sorting both and giving the smallest sufficient cookie to the least greedy child", "Random matching", "DP"], answer: 1, exp: "Two-pointer sweep after sorting." },
  { id: "gr-28", topic: "algo-greedy", q: "A greedy solution to 'jump game' (can you reach the last index?) tracks:", options: ["All possible positions", "The farthest index reachable so far; fail if the current index exceeds it", "The number of jumps only", "A DP array"], answer: 1, exp: "O(n), O(1) space." },
  { id: "gr-29", topic: "algo-greedy", q: "Minimum jumps to reach the end (greedy O(n)) works by:", options: ["BFS on indices", "Tracking the current jump's boundary and the farthest reachable; increment jumps when you pass the boundary", "DP over all indices", "Trying every jump length"], answer: 1, exp: "It is essentially a linear-time BFS by levels." },
  { id: "gr-30", topic: "algo-greedy", q: "The greedy algorithm for 'remove k digits to make the smallest number' uses:", options: ["Sorting", "A monotonic increasing stack: pop larger preceding digits", "DP", "Recursion over subsets"], answer: 1, exp: "Removing a digit larger than its successor reduces the number the most." },
  { id: "gr-31", topic: "algo-greedy", q: "Which problem does greedy solve optimally?", options: ["Traveling salesman", "Minimum spanning tree", "0/1 knapsack", "Longest common subsequence"], answer: 1, exp: "MST has the matroid/cut structure; the others need DP or are NP-hard." },
  { id: "gr-32", topic: "algo-greedy", q: "Scheduling to minimize maximum lateness is solved greedily by:", options: ["Shortest processing time first", "Earliest deadline first (EDF)", "Longest job first", "Largest lateness first"], answer: 1, exp: "An exchange argument shows EDF minimizes the maximum lateness." },
  { id: "gr-33", topic: "algo-greedy", q: "Scheduling to minimize the sum (or average) of completion times is solved greedily by:", options: ["Earliest deadline first", "Shortest Processing Time (SPT) first", "Longest job first", "Random order"], answer: 1, exp: "SPT minimizes total/average completion time (and average wait)." },
  { id: "gr-34", topic: "algo-greedy", q: "The greedy set-cover algorithm (pick the set covering the most uncovered elements) achieves an approximation ratio of:", options: ["1 (optimal)", "H(n) ~ ln n", "2", "n"], answer: 1, exp: "It cannot do better than Theta(log n) unless P = NP." },
  { id: "gr-35", topic: "algo-greedy", q: "Which is a correct greedy strategy for 'candy' (children with ratings, each gets >= 1, higher rating than a neighbor gets more)?", options: ["One pass left to right", "Two passes: left-to-right then right-to-left, taking the max", "Sort by rating", "DP over pairs"], answer: 1, exp: "Each pass enforces one neighbor constraint; the max satisfies both." },
  { id: "gr-36", topic: "algo-greedy", q: "The complexity of Kruskal's algorithm is dominated by:", options: ["Union-find operations", "Sorting the edges: O(E log E)", "BFS", "Building the graph"], answer: 1, exp: "After sorting, the union-find work is near-linear (inverse Ackermann)." },
  { id: "gr-37", topic: "algo-greedy", q: "A greedy algorithm's time complexity is usually dominated by:", options: ["The number of subproblems", "A sort (O(n log n)) or heap operations (O(n log n))", "Exponential enumeration", "Matrix operations"], answer: 1, exp: "Most greedy algorithms are 'sort, then one linear sweep'." },
  { id: "gr-38", topic: "algo-greedy", q: "The 'two city scheduling' problem (send n people to city A, n to city B, minimize cost) is greedy by:", options: ["Cost to A only", "Sorting by (costA - costB) and sending the first half to A", "Random", "DP over assignments"], answer: 1, exp: "The difference measures how much you save by sending someone to A rather than B." },
  { id: "gr-39", topic: "algo-greedy", q: "Which is FALSE about greedy algorithms?", options: ["They are often simple and fast", "They always yield a global optimum", "They make irrevocable choices", "Correctness usually needs a proof (exchange argument or matroid)"], answer: 1, exp: "Greedy is optimal only when the problem structure supports it." },
  { id: "gr-40", topic: "algo-greedy", q: "The greedy algorithm for 'minimum number of refueling stops' uses:", options: ["A max-heap of fuel amounts from stations already passed", "A min-heap", "Sorting stations by distance", "DP"], answer: 0, exp: "When you run out, retroactively 'use' the largest available fuel stop passed so far." },
  { id: "gr-41", topic: "algo-greedy", q: "For 'partition labels' (split a string so each letter appears in one part), greedy:", options: ["Records the last index of each character; extends the current partition to cover all seen characters' last indices", "Sorts characters", "Uses DP", "Splits in the middle"], answer: 0, exp: "A single pass; cut when the current index equals the running max last-index." },
  { id: "gr-42", topic: "algo-greedy", q: "In Huffman coding, the symbol with the highest frequency gets:", options: ["The longest code", "The shortest code", "A code of average length", "No code"], answer: 1, exp: "It is merged last, so it sits nearest the root — fewest bits." },
  { id: "gr-43", topic: "algo-greedy", q: "The greedy strategy for 'maximum units on a truck' (boxes with counts and unit values) is:", options: ["Fill with the most numerous box type", "Sort by units-per-box descending and fill greedily", "Random", "DP"], answer: 1, exp: "A bounded, fractional-knapsack-like structure where greedy is optimal." },
  { id: "gr-44", topic: "algo-greedy", q: "Which condition makes the greedy coin-change algorithm provably optimal?", options: ["Even amounts only", "Each coin is at least double the previous, or the system is 'canonical' (verified by checking small amounts)", "Fewer than 5 coin types", "Coins are prime"], answer: 1, exp: "'At least double' (like {1,2,4,8}) is a sufficient condition." },
  { id: "gr-45", topic: "algo-greedy", q: "The greedy 'meeting rooms II' (min rooms) heap contains:", options: ["Start times", "End times of ongoing meetings; reuse a room if the earliest end <= next start", "Room ids", "Durations"], answer: 1, exp: "Peek the min end time to decide if a room frees up." },
  { id: "gr-46", topic: "algo-greedy", q: "A greedy algorithm that produces a feasible but non-optimal answer is called a:", options: ["Exact algorithm", "Approximation algorithm (if it has a proven bound) or a heuristic", "Randomized algorithm", "Brute force"], answer: 1, exp: "Set cover's greedy is a classic O(log n)-approximation." },
  { id: "gr-47", topic: "algo-greedy", q: "Which of these is solved by a greedy algorithm on a sorted list plus a single pass?", options: ["Longest increasing subsequence (O(n^2) DP or O(n log n) with binary search)", "Merge overlapping intervals", "Edit distance", "Matrix chain multiplication"], answer: 1, exp: "Sort by start, then merge each interval into the previous if they overlap." },
  { id: "gr-48", topic: "algo-greedy", q: "The greedy choice in Prim's/Dijkstra's is efficiently found using a:", options: ["Stack", "Priority queue (min-heap)", "Hash table", "Queue"], answer: 1, exp: "Extract-min gives the next vertex/edge to add; O(log V) per step." },
  { id: "gr-49", topic: "algo-greedy", q: "Which is a valid reason greedy might be chosen even when not provably optimal?", options: ["It never matters", "It is fast and gives a good-enough approximate solution for an NP-hard problem", "It uses recursion", "It is required by the compiler"], answer: 1, exp: "For TSP, bin packing, scheduling, etc., greedy heuristics are practical." },
  { id: "gr-50", topic: "algo-greedy", q: "The overall template of a greedy algorithm is:", options: ["Enumerate all solutions, pick the best", "Sort/prioritize by a criterion, then iterate making each locally best feasible choice", "Fill a DP table bottom-up", "Recurse on halves"], answer: 1, exp: "Selection criterion + feasibility check + irrevocable commitment." },

  // ================= Dynamic Programming (50) =================
  { id: "dp-01", topic: "algo-dp", q: "Dynamic programming applies when a problem has:", options: ["Independent subproblems only", "Optimal substructure AND overlapping subproblems", "No recursion", "A greedy-choice property"], answer: 1, exp: "Overlap is what makes memoization/tabulation pay off (vs plain divide and conquer)." },
  { id: "dp-02", topic: "algo-dp", q: "'Optimal substructure' means:", options: ["The problem is small", "An optimal solution is built from optimal solutions to subproblems", "Subproblems do not overlap", "There is only one subproblem"], answer: 1, exp: "You can combine sub-solutions without needing their full internal detail." },
  { id: "dp-03", topic: "algo-dp", q: "Top-down DP is also called:", options: ["Tabulation", "Memoization — recursion plus a cache", "Iteration", "Greedy"], answer: 1, exp: "It computes subproblems on demand and stores results." },
  { id: "dp-04", topic: "algo-dp", q: "Bottom-up DP is also called:", options: ["Memoization", "Tabulation — fill a table in dependency order iteratively", "Backtracking", "Branch and bound"], answer: 1, exp: "No recursion; iterate subproblems from smallest to largest." },
  { id: "dp-05", topic: "algo-dp", q: "The naive recursive Fibonacci is O(2^n); with DP it becomes:", options: ["O(log n)", "O(n) time, O(1) or O(n) space", "O(n^2)", "O(n log n)"], answer: 1, exp: "Each fib(i) is computed once." },
  { id: "dp-06", topic: "algo-dp", q: "The 0/1 knapsack DP has time and space:", options: ["O(n) / O(n)", "O(nW) / O(nW), space reducible to O(W)", "O(2^n) / O(n)", "O(n log n) / O(1)"], answer: 1, exp: "dp[i][w] = best value using first i items with capacity w; only the previous row is needed." },
  { id: "dp-07", topic: "algo-dp", q: "The 0/1 knapsack DP is 'pseudo-polynomial' because its running time is polynomial in:", options: ["The number of items only", "n and the NUMERIC VALUE of W, not W's bit length", "log W", "Nothing"], answer: 1, exp: "If W is given in binary with b bits, O(nW) = O(n * 2^b) is exponential in the input size." },
  { id: "dp-08", topic: "algo-dp", q: "Longest Common Subsequence (LCS) of strings length m, n has DP complexity:", options: ["O(m + n)", "O(mn) time, O(mn) space (O(min(m,n)) for length only)", "O(2^(m+n))", "O(mn log mn)"], answer: 1, exp: "dp[i][j] = LCS of prefixes; recurrence branches on whether s[i] == t[j]." },
  { id: "dp-09", topic: "algo-dp", q: "Edit distance (Levenshtein) DP recurrence at dp[i][j] considers:", options: ["Only substitution", "Match/substitute, insert, delete — min of the three", "Only insert and delete", "Transposition only"], answer: 1, exp: "dp[i][j] = min(dp[i-1][j-1] + (s[i]!=t[j]), dp[i-1][j] + 1, dp[i][j-1] + 1)." },
  { id: "dp-10", topic: "algo-dp", q: "Matrix chain multiplication finds the optimal parenthesization in:", options: ["O(n)", "O(n^2)", "O(n^3) time, O(n^2) space", "O(2^n)"], answer: 2, exp: "dp[i][j] over all split points k; there are O(n^2) subproblems each taking O(n)." },
  { id: "dp-11", topic: "algo-dp", q: "Longest Increasing Subsequence (LIS) can be computed in:", options: ["O(n) ", "O(n^2) DP, or O(n log n) with patience sorting / binary search", "O(2^n)", "O(n^3)"], answer: 1, exp: "The O(n log n) method maintains the smallest tail of an increasing subsequence of each length." },
  { id: "dp-12", topic: "algo-dp", q: "The coin-change 'minimum coins' problem DP is:", options: ["Greedy, O(n)", "dp[amount] = 1 + min over coins c of dp[amount - c]; O(amount * #coins)", "O(2^amount)", "O(amount log amount)"], answer: 1, exp: "Unbounded knapsack structure; bottom-up over amounts." },
  { id: "dp-13", topic: "algo-dp", q: "The coin-change 'number of ways' problem must iterate:", options: ["Amounts in the outer loop, coins inner (counts permutations)", "Coins in the outer loop, amounts inner (counts combinations)", "Both give the same answer", "Neither loop order works"], answer: 1, exp: "Coin-outer avoids double counting {1,2} and {2,1} as different." },
  { id: "dp-14", topic: "algo-dp", q: "Subset-sum (does a subset sum to target T?) DP is:", options: ["O(n) time", "O(nT) time, O(T) space (boolean dp)", "O(2^n) unavoidable", "O(T^2)"], answer: 1, exp: "dp[s] = can we make sum s; process items, updating s from high to low." },
  { id: "dp-15", topic: "algo-dp", q: "The number of distinct subproblems bounds the DP's:", options: ["Correctness", "Time and space (each solved once and stored)", "Input size", "Recursion base case"], answer: 1, exp: "Total time ~ (#subproblems) * (work per subproblem)." },
  { id: "dp-16", topic: "algo-dp", q: "Which is TRUE about memoization vs tabulation?", options: ["Tabulation always uses less memory", "Memoization computes only the subproblems actually needed; tabulation may compute all and avoids recursion overhead / stack limits", "They give different answers", "Memoization cannot handle 2D states"], answer: 1, exp: "Choose memoization for sparse state spaces, tabulation for dense ones or to avoid deep recursion." },
  { id: "dp-17", topic: "algo-dp", q: "The 'house robber' problem (max sum, no two adjacent) recurrence is:", options: ["dp[i] = dp[i-1] + a[i]", "dp[i] = max(dp[i-1], dp[i-2] + a[i])", "dp[i] = a[i]", "dp[i] = dp[i-1] * a[i]"], answer: 1, exp: "Either skip house i (dp[i-1]) or rob it plus dp[i-2]." },
  { id: "dp-18", topic: "algo-dp", q: "The Bellman-Ford algorithm is essentially DP over:", options: ["Vertices only", "The number of edges allowed in the path (relax all edges V-1 times)", "Edge weights", "Recursion depth"], answer: 1, exp: "dp[k][v] = shortest path to v using at most k edges." },
  { id: "dp-19", topic: "algo-dp", q: "Floyd-Warshall is DP over:", options: ["The set of intermediate vertices allowed", "Path length", "Edge weights", "Source vertices"], answer: 0, exp: "dp[k][i][j] = shortest i->j path using only vertices {1..k} as intermediates; O(V^3)." },
  { id: "dp-20", topic: "algo-dp", q: "The 'maximum subarray sum' (Kadane) is a DP where dp[i] =", options: ["max(a[i], dp[i-1] + a[i])", "dp[i-1] + a[i]", "max(dp[i-1], a[i])", "a[i]"], answer: 0, exp: "Best subarray ending at i either starts fresh at a[i] or extends the previous." },
  { id: "dp-21", topic: "algo-dp", q: "The 'unique paths in a grid' (only right/down) DP is:", options: ["dp[i][j] = dp[i-1][j] + dp[i][j-1]", "dp[i][j] = dp[i-1][j-1]", "dp[i][j] = max(...)", "dp[i][j] = 1"], answer: 0, exp: "Each cell's path count is the sum of the cell above and the cell to the left; answer is C(m+n-2, m-1)." },
  { id: "dp-22", topic: "algo-dp", q: "Which problem is NP-hard even though it 'looks like' a DP?", options: ["Longest path in a general graph", "Shortest path in a DAG", "LCS", "Knapsack with small W"], answer: 0, exp: "Longest simple path has no polynomial DP (state would need to track visited sets); it IS poly for DAGs." },
  { id: "dp-23", topic: "algo-dp", q: "The traveling salesman problem via the Held-Karp DP runs in:", options: ["O(n!)", "O(2^n * n^2) — DP over subsets of visited cities", "O(n^3)", "O(2^n)"], answer: 1, exp: "dp[S][j] = min cost to visit exactly the set S ending at j; still exponential but far better than n!." },
  { id: "dp-24", topic: "algo-dp", q: "In DP, 'state' refers to:", options: ["The programming language", "The parameters that uniquely identify a subproblem", "The final answer", "The recursion stack"], answer: 1, exp: "E.g. (index, remaining capacity) for knapsack." },
  { id: "dp-25", topic: "algo-dp", q: "To reconstruct the actual optimal solution (not just its value) from a DP table:", options: ["It is impossible", "Store parent/choice pointers, or backtrack through the table following the recurrence", "Rerun the algorithm", "Sort the table"], answer: 1, exp: "Trace back from the final state, at each step picking the predecessor that achieved the optimum." },
  { id: "dp-26", topic: "algo-dp", q: "The rod-cutting problem (max revenue cutting a rod of length n) DP is:", options: ["Greedy by price/length", "dp[len] = max over cut c of (price[c] + dp[len - c]); O(n^2)", "O(2^n)", "O(n log n)"], answer: 1, exp: "Unbounded knapsack structure." },
  { id: "dp-27", topic: "algo-dp", q: "Which technique reduces a 2D DP's space to 1D?", options: ["Recursion", "Noticing dp[i][*] depends only on dp[i-1][*], so keep one (or two) rows", "Hashing", "Sorting the states"], answer: 1, exp: "Common for knapsack, LCS length, edit distance, unique paths." },
  { id: "dp-28", topic: "algo-dp", q: "The DP for 'longest palindromic subsequence' of string s is:", options: ["LIS of s", "LCS of s and reverse(s)", "Edit distance of s and reverse(s)", "Kadane on s"], answer: 1, exp: "A palindromic subsequence reads the same forward and backward, so it is common to s and its reverse." },
  { id: "dp-29", topic: "algo-dp", q: "'Interval DP' (like matrix chain, burst balloons) has state:", options: ["A single index", "A range [i, j], with the recurrence splitting on a middle point k", "A subset", "A pair of strings"], answer: 1, exp: "O(n^2) intervals, each trying O(n) split points => O(n^3)." },
  { id: "dp-30", topic: "algo-dp", q: "'Digit DP' is used to count numbers in [L, R] with some property, with state:", options: ["(position, tight-bound flag, accumulated property)", "(L, R)", "The full number", "A subset of digits"], answer: 0, exp: "Process digits left to right, tracking whether the prefix still equals the bound." },
  { id: "dp-31", topic: "algo-dp", q: "Bitmask DP is appropriate when:", options: ["n is large (n > 10^6)", "n is small (<= ~20) and the state is a subset of items", "The graph is a tree", "There are no constraints"], answer: 1, exp: "2^n states become tractable only for small n." },
  { id: "dp-32", topic: "algo-dp", q: "The 'partition equal subset sum' problem reduces to:", options: ["LIS", "Subset-sum with target = totalSum / 2 (fail if totalSum is odd)", "Edit distance", "Coin change"], answer: 1, exp: "Split into two equal halves iff a subset sums to half the total." },
  { id: "dp-33", topic: "algo-dp", q: "The DP recurrence for 'climbing stairs' (1 or 2 steps) is:", options: ["dp[n] = dp[n-1] + dp[n-2] (Fibonacci)", "dp[n] = 2 * dp[n-1]", "dp[n] = n", "dp[n] = dp[n-1] * dp[n-2]"], answer: 0, exp: "You reach step n from n-1 or n-2." },
  { id: "dp-34", topic: "algo-dp", q: "The Catalan number recurrence C(n) = sum_{i} C(i) C(n-1-i) is a DP for counting:", options: ["Permutations", "Binary tree shapes, valid parenthesis strings, triangulations, etc.", "Subsets", "Paths in a grid"], answer: 1, exp: "It appears whenever a structure splits into a left and right part around a root/pair." },
  { id: "dp-35", topic: "algo-dp", q: "Which is a sign that a DP state is missing a dimension?", options: ["The table is large", "The recurrence needs information (e.g. 'last element chosen', 'remaining budget') not captured by the current state", "The base case is trivial", "It runs fast"], answer: 1, exp: "If two different histories with the same state lead to different optimal futures, add a dimension." },
  { id: "dp-36", topic: "algo-dp", q: "'Tree DP' computes an answer for each subtree, typically with:", options: ["BFS", "Post-order DFS: combine children's results at the parent", "In-order traversal", "Union-find"], answer: 1, exp: "E.g. maximum independent set on a tree: dp[v][0/1] = v not/ included." },
  { id: "dp-37", topic: "algo-dp", q: "The number of ways to tile a 2 x n board with 2x1 dominoes is:", options: ["n", "The (n+1)-th Fibonacci number", "2^n", "n!"], answer: 1, exp: "dp[n] = dp[n-1] (vertical) + dp[n-2] (two horizontal)." },
  { id: "dp-38", topic: "algo-dp", q: "Which is TRUE about DP and greedy?", options: ["DP is a special case of greedy", "Greedy is a special case of DP where the recurrence needs only one branch", "They are unrelated", "Greedy is always slower"], answer: 1, exp: "When the optimal choice at each state is provably a single option, DP collapses to greedy." },
  { id: "dp-39", topic: "algo-dp", q: "The 'egg drop' problem (min trials to find the critical floor with k eggs, n floors) is DP with state:", options: ["(eggs, floors) and O(k n^2) or O(k n log n) time", "(floors) only", "A subset of floors", "(eggs) only"], answer: 0, exp: "dp[e][f] = min worst-case trials; optimized with binary search or a moves-based formulation." },
  { id: "dp-40", topic: "algo-dp", q: "The DP for 'word break' (can string s be segmented into dictionary words?) has state:", options: ["dp[i] = is s[0..i) segmentable; check all j < i with s[j..i) in dict", "dp[word]", "A subset of words", "Two indices into two strings"], answer: 0, exp: "O(n^2) substring checks (or O(n * maxWordLen) with a set)." },
  { id: "dp-41", topic: "algo-dp", q: "The 'best time to buy and sell stock with at most k transactions' DP has state:", options: ["(day, transactions used, holding?) with O(nk) time", "(day) only", "A subset of days", "(price)"], answer: 0, exp: "Track whether you currently hold a share and how many transactions remain." },
  { id: "dp-42", topic: "algo-dp", q: "Which optimization technique speeds up certain DPs from O(n^2) to O(n log n) or O(n)?", options: ["Recursion", "Convex hull trick / divide-and-conquer optimization / Knuth optimization (when the cost function is monotone/quadrangle-convex)", "Hashing states", "Sorting the input"], answer: 1, exp: "These exploit structure in the transition cost to avoid checking every split point." },
  { id: "dp-43", topic: "algo-dp", q: "The DP table for 'distinct subsequences' (count how many times t appears as a subsequence of s) is:", options: ["O(1)", "O(mn) — dp[i][j] with dp[i][j] += dp[i-1][j-1] when s[i]==t[j]", "O(2^m)", "O(m + n)"], answer: 1, exp: "Standard 2D string DP." },
  { id: "dp-44", topic: "algo-dp", q: "For counting problems, DP transitions typically use ____ instead of min/max:", options: ["division", "addition (sum the ways from each valid predecessor state)", "XOR", "comparison"], answer: 1, exp: "Optimization DP uses min/max; counting DP sums, often modulo a prime." },
  { id: "dp-45", topic: "algo-dp", q: "The recurrence T(n) for a DP with n states and O(n) transition work each is:", options: ["O(n)", "O(n^2)", "O(n log n)", "O(2^n)"], answer: 1, exp: "n * O(n) = O(n^2); e.g. O(n^2) LIS." },
  { id: "dp-46", topic: "algo-dp", q: "'Memoization with a hash map' (instead of an array) is used when:", options: ["States are dense", "The state space is large/sparse or states are not small integers (e.g. tuples, strings)", "n is small", "The DP is 1D"], answer: 1, exp: "A map stores only the reached states." },
  { id: "dp-47", topic: "algo-dp", q: "The DP for the Fibonacci-like recurrence can be computed in O(log n) using:", options: ["Memoization", "Fast matrix exponentiation of [[1,1],[1,0]]", "Tabulation", "A closed form only"], answer: 1, exp: "Raising the transition matrix to the n-th power via repeated squaring gives O(log n) matmuls." },
  { id: "dp-48", topic: "algo-dp", q: "Which is a correct base case for the LCS DP?", options: ["dp[0][j] = j", "dp[0][j] = 0 and dp[i][0] = 0 (empty prefix)", "dp[0][0] = 1", "dp[i][0] = i"], answer: 1, exp: "The LCS with an empty string is 0. (For edit distance, dp[i][0] = i.)" },
  { id: "dp-49", topic: "algo-dp", q: "The main risk of top-down DP in languages with small default stacks is:", options: ["Wrong answers", "Stack overflow for deep recursion (e.g. n = 10^6 chain)", "Slower than exponential", "Using too little memory"], answer: 1, exp: "Convert to bottom-up (or increase the stack) for very deep state chains." },
  { id: "dp-50", topic: "algo-dp", q: "The overall DP design process is:", options: ["Guess and check", "Define the state, write the recurrence (transition) and base cases, decide the evaluation order, then optimize space", "Sort then sweep", "Enumerate all solutions"], answer: 1, exp: "State + transition + base + order is the standard four-step recipe." },

  // ================= Graph Search (50) =================
  { id: "gs-01", topic: "algo-graph-search", q: "BFS explores a graph in order of:", options: ["Depth", "Increasing number of edges from the source", "Edge weight", "Vertex id"], answer: 1, exp: "The FIFO queue processes all distance-d vertices before distance-(d+1)." },
  { id: "gs-02", topic: "algo-graph-search", q: "DFS explores a graph by:", options: ["Levels", "Going as deep as possible before backtracking", "Cheapest edge first", "Random walk"], answer: 1, exp: "It uses a stack (explicit or the call stack)." },
  { id: "gs-03", topic: "algo-graph-search", q: "BFS and DFS both run in:", options: ["O(V)", "O(V + E)", "O(V^2)", "O(E log V)"], answer: 1, exp: "Linear in the graph size with adjacency lists." },
  { id: "gs-04", topic: "algo-graph-search", q: "To find the shortest path (fewest edges) in an unweighted graph, use:", options: ["DFS", "BFS", "Dijkstra", "Bellman-Ford"], answer: 1, exp: "BFS layers = shortest edge-distance." },
  { id: "gs-05", topic: "algo-graph-search", q: "Uniform-cost search (UCS) is essentially:", options: ["BFS", "Dijkstra's algorithm — expand the lowest-cost frontier node", "DFS", "A* with h = 0"], answer: 1, exp: "UCS is Dijkstra framed as a search; it equals A* with a zero heuristic." },
  { id: "gs-06", topic: "algo-graph-search", q: "A* search orders the frontier by:", options: ["g(n) only", "h(n) only", "f(n) = g(n) + h(n)", "Random"], answer: 2, exp: "g = cost so far, h = estimated cost to goal." },
  { id: "gs-07", topic: "algo-graph-search", q: "A* is guaranteed to find an optimal path if the heuristic h is:", options: ["Fast", "Admissible (never overestimates the true cost to the goal)", "Zero", "Monotone only"], answer: 1, exp: "Consistency (monotonicity) additionally guarantees each node is expanded once." },
  { id: "gs-08", topic: "algo-graph-search", q: "If A*'s heuristic h(n) = 0 for all n, A* behaves like:", options: ["DFS", "Greedy best-first search", "Dijkstra / uniform-cost search", "Random search"], answer: 2, exp: "With no guidance it expands by path cost only." },
  { id: "gs-09", topic: "algo-graph-search", q: "Greedy best-first search (order by h only) is:", options: ["Optimal and complete", "Fast but neither optimal nor complete in general", "Slower than BFS", "The same as A*"], answer: 1, exp: "It can be misled by the heuristic into a suboptimal or dead-end path." },
  { id: "gs-10", topic: "algo-graph-search", q: "Iterative deepening DFS (IDDFS) has space complexity:", options: ["O(b^d)", "O(bd) — linear like DFS", "O(1)", "O(d^2)"], answer: 1, exp: "It keeps only the current path while still finding the shallowest goal." },
  { id: "gs-11", topic: "algo-graph-search", q: "Bidirectional search reduces time from O(b^d) to roughly:", options: ["O(b^d)", "O(b^(d/2))", "O(d)", "O(log b^d)"], answer: 1, exp: "Two frontiers of depth d/2 meet in the middle." },
  { id: "gs-12", topic: "algo-graph-search", q: "In BFS, a vertex is marked visited:", options: ["When dequeued", "When enqueued (prevents multiple enqueues)", "Never", "After the search"], answer: 1, exp: "Marking on enqueue avoids adding the same vertex from several neighbors." },
  { id: "gs-13", topic: "algo-graph-search", q: "0-1 BFS (edge weights 0 or 1) uses a ____ to run in O(V + E):", options: ["min-heap", "deque — push weight-0 edges to the front, weight-1 to the back", "stack", "plain queue"], answer: 1, exp: "The deque keeps the frontier sorted by distance without a heap." },
  { id: "gs-14", topic: "algo-graph-search", q: "Multi-source BFS computes:", options: ["The MST", "Each vertex's distance to its NEAREST source", "SCCs", "A topological order"], answer: 1, exp: "All sources start at distance 0 in the queue." },
  { id: "gs-15", topic: "algo-graph-search", q: "DFS is used to detect a cycle in a directed graph by finding:", options: ["A cross edge", "A back edge (to a vertex currently on the recursion stack)", "A forward edge", "Any repeated vertex"], answer: 1, exp: "Three-color (white/gray/black) marking distinguishes back edges." },
  { id: "gs-16", topic: "algo-graph-search", q: "Topological sort of a DAG can be done by:", options: ["BFS from any vertex", "Kahn's algorithm (repeatedly remove an in-degree-0 vertex) or DFS finish-time reversal", "Dijkstra", "Union-find"], answer: 1, exp: "Both run in O(V + E)." },
  { id: "gs-17", topic: "algo-graph-search", q: "The shortest path in a weighted DAG is found in O(V + E) by:", options: ["Dijkstra", "Relaxing edges in topological order", "BFS", "Floyd-Warshall"], answer: 1, exp: "No priority queue needed; each vertex is finalized when reached in topo order." },
  { id: "gs-18", topic: "algo-graph-search", q: "Strongly connected components are found in O(V + E) by:", options: ["BFS from every vertex", "Kosaraju's (2 DFS passes) or Tarjan's (1 DFS pass) algorithm", "Dijkstra", "Kruskal"], answer: 1, exp: "Kosaraju uses the graph and its transpose; Tarjan uses low-link values." },
  { id: "gs-19", topic: "algo-graph-search", q: "Articulation points and bridges are found in O(V + E) using DFS with:", options: ["Edge weights", "Discovery times and low-link (earliest reachable ancestor) values", "A queue", "Union-find"], answer: 1, exp: "A non-root u is an articulation point if some child's low value >= disc[u]." },
  { id: "gs-20", topic: "algo-graph-search", q: "Which search is complete (will find a solution if one exists) on an infinite graph with finite branching?", options: ["DFS", "BFS (and IDDFS)", "Greedy best-first", "Random walk"], answer: 1, exp: "DFS may go down an infinite branch forever; BFS/IDDFS are complete." },
  { id: "gs-21", topic: "algo-graph-search", q: "In a maze/grid, BFS from start finds the shortest path because:", options: ["It uses recursion", "All moves have equal cost, so layers correspond to path length", "It sorts cells", "It uses a heap"], answer: 1, exp: "Uniform cost + FIFO = shortest first." },
  { id: "gs-22", topic: "algo-graph-search", q: "The frontier (open list) size of BFS on a tree with branching factor b at depth d is:", options: ["O(d)", "O(b^d)", "O(1)", "O(bd)"], answer: 1, exp: "This exponential memory is BFS's main weakness vs IDDFS." },
  { id: "gs-23", topic: "algo-graph-search", q: "A* with an inadmissible heuristic:", options: ["Is faster and still optimal", "May be faster but can return a suboptimal path", "Never terminates", "Behaves like DFS"], answer: 1, exp: "Overestimating can prune the true optimal path." },
  { id: "gs-24", topic: "algo-graph-search", q: "The Manhattan distance is an admissible heuristic for grid pathfinding when:", options: ["Diagonal moves are allowed", "Only 4-directional (up/down/left/right) moves are allowed", "There are no walls", "Costs are negative"], answer: 1, exp: "It never overestimates when you can only move along axes; use Chebyshev/octile for 8-directional." },
  { id: "gs-25", topic: "algo-graph-search", q: "DFS of a graph produces a DFS forest; the number of trees for an undirected graph equals:", options: ["1", "The number of connected components", "V", "E"], answer: 1, exp: "Each restart of DFS from an unvisited vertex roots a new tree." },
  { id: "gs-26", topic: "algo-graph-search", q: "Which is TRUE about DFS vs BFS memory on a wide shallow graph?", options: ["BFS uses less", "DFS uses less (O(depth)); BFS must buffer a whole wide level", "Equal", "Both O(1)"], answer: 1, exp: "Pick DFS when the branching factor is large and solutions are deep-ish." },
  { id: "gs-27", topic: "algo-graph-search", q: "Flood fill (e.g. paint bucket) is:", options: ["Dijkstra", "BFS or DFS from the seed cell, spreading to same-color neighbors", "A* search", "Topological sort"], answer: 1, exp: "Either traversal works; BFS avoids deep recursion on large regions." },
  { id: "gs-28", topic: "algo-graph-search", q: "The 'word ladder' problem (transform one word to another one letter at a time) is solved by:", options: ["DFS", "BFS on the graph of words (edges = one-letter differences); bidirectional BFS is faster", "Dijkstra with weights", "DP"], answer: 1, exp: "Unweighted shortest path => BFS." },
  { id: "gs-29", topic: "algo-graph-search", q: "Which search would you use to find ANY path quickly (not necessarily shortest) with minimal memory?", options: ["BFS", "DFS", "A*", "Dijkstra"], answer: 1, exp: "DFS uses O(depth) memory and often reaches a goal fast." },
  { id: "gs-30", topic: "algo-graph-search", q: "IDA* (iterative deepening A*) is used when:", options: ["The graph is tiny", "A*'s memory (open list) is too large; IDA* uses linear memory with an f-cost threshold", "Edges are negative", "Speed does not matter"], answer: 1, exp: "It re-searches with increasing f-limits, like IDDFS guided by f = g + h." },
  { id: "gs-31", topic: "algo-graph-search", q: "The time complexity of BFS/DFS on an adjacency MATRIX is:", options: ["O(V + E)", "O(V^2)", "O(E)", "O(V log V)"], answer: 1, exp: "Enumerating a vertex's neighbors costs O(V) each." },
  { id: "gs-32", topic: "algo-graph-search", q: "In directed-graph DFS, an edge to an already-finished vertex in a different subtree is a:", options: ["Tree edge", "Back edge", "Forward edge", "Cross edge"], answer: 3, exp: "Cross edges go between subtrees or between DFS trees; they never indicate a cycle." },
  { id: "gs-33", topic: "algo-graph-search", q: "A 2-coloring (bipartiteness check) is done with:", options: ["Dijkstra", "BFS or DFS, coloring each vertex opposite its parent; conflict => not bipartite", "Union-find only", "Topological sort"], answer: 1, exp: "A conflict corresponds to an odd-length cycle." },
  { id: "gs-34", topic: "algo-graph-search", q: "The recursion depth of DFS on a graph with V vertices can be as large as:", options: ["O(log V)", "O(V) (a long path)", "O(1)", "O(sqrt V)"], answer: 1, exp: "For very large graphs, use an explicit stack to avoid stack overflow." },
  { id: "gs-35", topic: "algo-graph-search", q: "Which is a correct statement about BFS parent pointers?", options: ["They form the MST", "They form a shortest-path tree (in edges) rooted at the source", "They form a DFS tree", "They are meaningless"], answer: 1, exp: "Following parents from any vertex to the source gives a shortest path." },
  { id: "gs-36", topic: "algo-graph-search", q: "The number of vertices enqueued during a BFS equals:", options: ["|E|", "The number of vertices reachable from the source", "|V| * |E|", "1"], answer: 1, exp: "Each reachable vertex is enqueued exactly once." },
  { id: "gs-37", topic: "algo-graph-search", q: "Which technique speeds up point-to-point queries on a fixed road network after preprocessing?", options: ["Plain Dijkstra every time", "Contraction hierarchies / A* with landmark heuristics (ALT)", "BFS", "DFS"], answer: 1, exp: "Preprocessing enables millisecond continental routing." },
  { id: "gs-38", topic: "algo-graph-search", q: "In game-tree search, minimax explores the tree with:", options: ["BFS", "DFS, alternating min and max at each level", "Dijkstra", "Random sampling"], answer: 1, exp: "Alpha-beta pruning cuts branches that cannot affect the result." },
  { id: "gs-39", topic: "algo-graph-search", q: "The 'number of islands' problem counts connected components of 1-cells using:", options: ["Dijkstra", "BFS or DFS flood fill, counting each new unvisited land cell as a new island", "Topological sort", "MST"], answer: 1, exp: "O(RC) over the grid." },
  { id: "gs-40", topic: "algo-graph-search", q: "For an unweighted graph, DFS finds:", options: ["The shortest path", "SOME path (not necessarily shortest)", "The longest path", "All shortest paths"], answer: 1, exp: "DFS gives no distance guarantee; use BFS for shortest." },
  { id: "gs-41", topic: "algo-graph-search", q: "The 'rotting oranges' (minutes until all fresh oranges rot) problem uses:", options: ["DFS", "Multi-source BFS from all initially rotten oranges", "Dijkstra", "DP"], answer: 1, exp: "Each BFS level is one minute; the last level reached is the answer." },
  { id: "gs-42", topic: "algo-graph-search", q: "A* expands fewer nodes than Dijkstra when:", options: ["The heuristic is 0", "The heuristic is informative (close to the true remaining cost)", "The graph is unweighted", "There is no goal"], answer: 1, exp: "A better heuristic focuses the search toward the goal." },
  { id: "gs-43", topic: "algo-graph-search", q: "Which search guarantees the minimum-cost path in a graph with non-negative edge weights?", options: ["BFS", "DFS", "Dijkstra / A* with admissible h / uniform-cost search", "Greedy best-first"], answer: 2, exp: "All three are cost-optimal for non-negative weights." },
  { id: "gs-44", topic: "algo-graph-search", q: "The DFS-based algorithm to find a topological order fails (detects no valid order) exactly when the graph:", options: ["Is disconnected", "Contains a directed cycle", "Has isolated vertices", "Has a source and a sink"], answer: 1, exp: "Only DAGs have a topological order." },
  { id: "gs-45", topic: "algo-graph-search", q: "Which is TRUE about the open and closed lists in graph search?", options: ["Both are optional", "Open = frontier to expand; closed = already expanded, used to avoid revisiting states", "Closed stores the answer", "Open is a stack always"], answer: 1, exp: "The data structure for 'open' (queue/stack/heap) defines the search strategy." },
  { id: "gs-46", topic: "algo-graph-search", q: "Depth-limited search is DFS that:", options: ["Uses a heap", "Cuts off exploration below a fixed depth L (may miss deeper goals)", "Explores by cost", "Is complete"], answer: 1, exp: "It bounds memory and time but is incomplete if the goal is deeper than L; IDDFS fixes this." },
  { id: "gs-47", topic: "algo-graph-search", q: "BFS on a graph with V vertices needs auxiliary space:", options: ["O(1)", "O(V) for the queue, visited set and parent array", "O(E^2)", "O(V log V)"], answer: 1, exp: "The frontier and bookkeeping are all O(V)." },
  { id: "gs-48", topic: "algo-graph-search", q: "Which search would you use to explore all reachable states of a small puzzle to find the optimal solution?", options: ["DFS", "BFS (optimal for unit costs) or A* (with a good heuristic, faster)", "Random walk", "Greedy"], answer: 1, exp: "BFS gives the fewest-move solution; A* prunes with a heuristic like the number of misplaced tiles." },
  { id: "gs-49", topic: "algo-graph-search", q: "In DFS, the 'gray' state of a vertex means:", options: ["Unvisited", "Discovered but not finished (still on the recursion stack)", "Fully processed", "Deleted"], answer: 1, exp: "White = undiscovered, gray = in progress, black = finished." },
  { id: "gs-50", topic: "algo-graph-search", q: "Which statement is TRUE?", options: ["BFS uses less memory than DFS", "DFS's time is O(V + E) but its recursion can overflow the stack on deep graphs; an explicit stack avoids this", "DFS is always faster than BFS", "BFS cannot find a path"], answer: 1, exp: "Both are O(V + E) time; the difference is exploration order and memory profile." },

  // ================= Minimum Spanning Trees (50) =================
  { id: "mst-01", topic: "algo-mst", q: "A spanning tree of a connected graph with V vertices has:", options: ["V edges", "V - 1 edges", "E - 1 edges", "2V edges"], answer: 1, exp: "It is a tree covering all vertices — connected and acyclic." },
  { id: "mst-02", topic: "algo-mst", q: "A minimum spanning tree (MST) is a spanning tree with:", options: ["The most edges", "The minimum total edge weight", "The fewest vertices", "No leaves"], answer: 1, exp: "Among all spanning trees, the MST minimizes the sum of edge weights." },
  { id: "mst-03", topic: "algo-mst", q: "Kruskal's algorithm processes edges:", options: ["In arbitrary order", "In increasing weight order, adding an edge if it connects two different components", "In decreasing weight order", "By DFS order"], answer: 1, exp: "Union-find detects whether an edge would create a cycle." },
  { id: "mst-04", topic: "algo-mst", q: "Kruskal's algorithm's time complexity is:", options: ["O(V)", "O(E log E) (dominated by sorting the edges)", "O(V^2)", "O(V^3)"], answer: 1, exp: "The union-find operations are near-linear; sorting dominates." },
  { id: "mst-05", topic: "algo-mst", q: "Prim's algorithm grows the MST by:", options: ["Adding the globally cheapest edge each step", "Starting from one vertex and repeatedly adding the cheapest edge from the tree to a vertex outside it", "Removing the heaviest edges", "DFS from the root"], answer: 1, exp: "It maintains a single connected tree; a priority queue picks the cheapest crossing edge." },
  { id: "mst-06", topic: "algo-mst", q: "Prim's algorithm with a binary heap runs in:", options: ["O(V^2)", "O((V + E) log V)", "O(E)", "O(V log E + E)"], answer: 1, exp: "Each edge may cause a decrease-key/push; each vertex is extracted once." },
  { id: "mst-07", topic: "algo-mst", q: "Prim's algorithm with an adjacency matrix and no heap runs in:", options: ["O(E log V)", "O(V^2)", "O(V + E)", "O(V^3)"], answer: 1, exp: "V iterations, each scanning O(V) to find the min-key vertex — good for dense graphs." },
  { id: "mst-08", topic: "algo-mst", q: "The cut property states that:", options: ["The heaviest edge in any cycle is not in any MST", "For any cut, the minimum-weight crossing edge is in some MST", "Every MST has V edges", "MSTs are unique"], answer: 1, exp: "This is the correctness basis of both Prim and Kruskal." },
  { id: "mst-09", topic: "algo-mst", q: "The cycle property states that:", options: ["Every cycle has an MST edge", "The maximum-weight edge of any cycle is NOT in any MST (if it is unique)", "Cycles cannot exist in a graph", "MSTs contain one cycle"], answer: 1, exp: "Such an edge can always be replaced by a lighter cycle edge." },
  { id: "mst-10", topic: "algo-mst", q: "An MST is UNIQUE if:", options: ["The graph is connected", "All edge weights are distinct", "It has no leaves", "It is planar"], answer: 1, exp: "Distinct weights force a unique minimum crossing edge at every cut." },
  { id: "mst-11", topic: "algo-mst", q: "Does the MST also minimize the maximum edge weight (the bottleneck)?", options: ["No", "Yes — the MST is always a minimum bottleneck spanning tree", "Only for trees", "Only if weights are distinct"], answer: 1, exp: "Every MST minimizes the largest edge on the path between any two vertices." },
  { id: "mst-12", topic: "algo-mst", q: "Boruvka's (Sollin's) algorithm:", options: ["Adds one edge per iteration", "Adds, for every component simultaneously, its cheapest outgoing edge; O(E log V)", "Removes heavy edges", "Uses DFS"], answer: 1, exp: "The number of components at least halves each round, giving O(log V) rounds." },
  { id: "mst-13", topic: "algo-mst", q: "If all edge weights are equal, the MST is:", options: ["Unique", "Any spanning tree (all have the same total weight)", "Impossible", "The graph itself"], answer: 1, exp: "Every spanning tree has weight (V-1) * w." },
  { id: "mst-14", topic: "algo-mst", q: "Adding 1 to every edge weight:", options: ["Never changes the MST", "May change the MST (it adds (V-1) uniformly to spanning trees, but... actually it does NOT change which tree is minimum)", "Always changes the MST", "Makes the MST heavier only"], answer: 0, exp: "All spanning trees have exactly V-1 edges, so every tree's weight increases by the same (V-1); the ranking (and MST) is unchanged." },
  { id: "mst-15", topic: "algo-mst", q: "Multiplying every edge weight by a positive constant:", options: ["Changes the MST", "Does not change the MST (relative order of tree weights is preserved)", "Only changes it if the constant is > 1", "Makes it non-unique"], answer: 1, exp: "Scaling preserves comparisons, so the same tree stays minimum." },
  { id: "mst-16", topic: "algo-mst", q: "Prim's algorithm is preferred over Kruskal's when the graph is:", options: ["Sparse", "Dense (E close to V^2) — Prim with a matrix is O(V^2), better than O(E log E)", "A tree", "Disconnected"], answer: 1, exp: "Kruskal shines on sparse graphs where sorting E edges is cheap." },
  { id: "mst-17", topic: "algo-mst", q: "The union-find data structure in Kruskal's, with path compression and union by rank, gives per-operation cost:", options: ["O(log n)", "O(alpha(n)) — effectively constant", "O(n)", "O(sqrt n)"], answer: 1, exp: "Inverse Ackermann alpha(n) <= 4 for all practical n." },
  { id: "mst-18", topic: "algo-mst", q: "An MST of a graph with negative edge weights:", options: ["Does not exist", "Is still well-defined and computed the same way (Prim/Kruskal work with negatives)", "Requires Bellman-Ford", "Is always the whole graph"], answer: 1, exp: "MST algorithms only compare weights; sign does not matter." },
  { id: "mst-19", topic: "algo-mst", q: "The 'safe edge' added at each step of a generic MST algorithm is:", options: ["Any edge not yet chosen", "An edge that can be added without violating the property that the chosen set is a subset of some MST", "The heaviest available edge", "A random edge"], answer: 1, exp: "The cut property identifies safe edges." },
  { id: "mst-20", topic: "algo-mst", q: "To find the SECOND-best (next-minimum) spanning tree:", options: ["Run Kruskal twice", "Find the MST, then for each non-MST edge e, add it and remove the heaviest edge on the cycle it forms; take the best swap", "It equals the MST", "Impossible"], answer: 1, exp: "The second-best tree differs from the MST by exactly one edge swap." },
  { id: "mst-21", topic: "algo-mst", q: "Which edge is DEFINITELY in the MST of a connected graph (distinct weights)?", options: ["The heaviest edge", "The lightest edge in the whole graph", "Any edge on a cycle", "The edge with median weight"], answer: 1, exp: "The globally minimum edge is the min crossing edge of the cut separating its endpoints." },
  { id: "mst-22", topic: "algo-mst", q: "Which edge is DEFINITELY NOT in the MST (distinct weights)?", options: ["The lightest edge", "The unique heaviest edge of any cycle", "A bridge", "The second-lightest edge"], answer: 1, exp: "The cycle property excludes it." },
  { id: "mst-23", topic: "algo-mst", q: "A bridge (cut edge) of a connected graph:", options: ["Is never in the MST", "Must be in EVERY spanning tree, hence in the MST", "Is the heaviest edge", "Creates a cycle"], answer: 1, exp: "Removing a bridge disconnects the graph, so it is essential." },
  { id: "mst-24", topic: "algo-mst", q: "Prim's priority queue is keyed by:", options: ["Vertex degree", "The minimum weight of an edge connecting an outside vertex to the current tree", "DFS discovery time", "Vertex id"], answer: 1, exp: "Extract-min gives the next vertex to attach and the edge to use." },
  { id: "mst-25", topic: "algo-mst", q: "The MST of a graph is also a solution to:", options: ["Shortest path between all pairs", "Connecting all vertices at minimum total cable/road cost", "Maximum flow", "Graph coloring"], answer: 1, exp: "Network design: minimum cost to keep everything connected." },
  { id: "mst-26", topic: "algo-mst", q: "Is a shortest-path tree (from Dijkstra) the same as an MST?", options: ["Always", "Generally NO — they optimize different objectives", "Only for unweighted graphs", "Only for trees"], answer: 1, exp: "SPT minimizes distance from the source; MST minimizes total edge weight." },
  { id: "mst-27", topic: "algo-mst", q: "With a Fibonacci heap, Prim's algorithm runs in:", options: ["O(V^2)", "O(E + V log V)", "O(E log V)", "O(V log E)"], answer: 1, exp: "O(1) amortized decrease-key improves the E log V term to E." },
  { id: "mst-28", topic: "algo-mst", q: "Kruskal's algorithm can be stopped early after adding:", options: ["E edges", "V - 1 edges (the tree is complete)", "V edges", "log V edges"], answer: 1, exp: "A spanning tree has exactly V-1 edges." },
  { id: "mst-29", topic: "algo-mst", q: "If a graph is disconnected, Kruskal's algorithm produces:", options: ["Nothing", "A minimum spanning FOREST (an MST per component)", "An error", "A single tree spanning some vertices"], answer: 1, exp: "Each component gets its own MST." },
  { id: "mst-30", topic: "algo-mst", q: "Removing the maximum-weight edge from a cycle in the current graph, repeatedly, until no cycle remains is:", options: ["Prim's algorithm", "The 'reverse-delete' algorithm — a valid MST method", "Kruskal's algorithm", "Not correct"], answer: 1, exp: "Reverse-delete: sort edges descending; delete an edge if the graph stays connected." },
  { id: "mst-31", topic: "algo-mst", q: "The MST problem is in complexity class:", options: ["NP-complete", "P (polynomial time)", "Undecidable", "EXPTIME"], answer: 1, exp: "Prim/Kruskal solve it in near-linear time; contrast with NP-hard Steiner tree." },
  { id: "mst-32", topic: "algo-mst", q: "The Steiner tree problem differs from MST in that it:", options: ["Has no weights", "May add extra (Steiner) vertices to reduce total cost — and is NP-hard", "Is easier", "Requires a directed graph"], answer: 1, exp: "MST must use only the given terminals; Steiner tree allows helper points." },
  { id: "mst-33", topic: "algo-mst", q: "When Kruskal considers an edge (u, v) and find(u) == find(v):", options: ["Add the edge", "Skip it — u and v are already connected, so adding it creates a cycle", "Merge them anyway", "Restart"], answer: 1, exp: "The edge is unsafe." },
  { id: "mst-34", topic: "algo-mst", q: "The number of edges Kruskal's algorithm examines in the worst case is:", options: ["V - 1", "All E edges", "log E", "V^2"], answer: 1, exp: "It may inspect every edge (skipping cycle-forming ones) before finding V-1 tree edges." },
  { id: "mst-35", topic: "algo-mst", q: "A graph where every edge has a distinct weight has how many MSTs?", options: ["0", "Exactly 1", "2", "Many"], answer: 1, exp: "Distinct weights => unique MST." },
  { id: "mst-36", topic: "algo-mst", q: "In Prim's algorithm, once a vertex is extracted from the priority queue, its MST edge is:", options: ["Tentative", "Finalized (it will never get a cheaper connection)", "Recomputed", "Deleted"], answer: 1, exp: "Like Dijkstra, extraction finalizes the vertex." },
  { id: "mst-37", topic: "algo-mst", q: "Which is TRUE if an edge e is the unique minimum-weight edge crossing SOME cut?", options: ["e may or may not be in the MST", "e is in EVERY MST", "e is in NO MST", "e forms a cycle"], answer: 1, exp: "The cut property, strengthened by uniqueness." },
  { id: "mst-38", topic: "algo-mst", q: "To verify that a given spanning tree T is an MST:", options: ["Recompute the MST", "Check that for every non-tree edge (u,v), its weight >= the max edge weight on the tree path from u to v (O(E) or O(E alpha) with proper structures)", "Sum its weights", "It cannot be verified"], answer: 1, exp: "Linear-time MST verification algorithms exist." },
  { id: "mst-39", topic: "algo-mst", q: "The maximum spanning tree can be found by:", options: ["A different algorithm entirely", "Running Kruskal/Prim with weights negated (or sorting descending)", "It does not exist", "Taking the complement of the MST"], answer: 1, exp: "Flip the comparison; the structure is identical." },
  { id: "mst-40", topic: "algo-mst", q: "Prim's algorithm without a priority queue (scan all vertices for the min each step) is O(V^2); this is optimal when:", options: ["The graph is sparse", "The graph is dense (E = Theta(V^2)), where O(V^2) beats O(E log V) = O(V^2 log V)", "V is small", "There are negative weights"], answer: 1, exp: "For dense graphs the array version wins." },
  { id: "mst-41", topic: "algo-mst", q: "If you contract an MST edge (merge its endpoints), the MST of the smaller graph plus that edge:", options: ["Is not the MST", "Is the MST of the original graph", "Loses a vertex from the MST", "Has a cycle"], answer: 1, exp: "This 'edge contraction' view underlies Boruvka's algorithm." },
  { id: "mst-42", topic: "algo-mst", q: "Given the MST, adding a new edge e to the graph changes the MST only if:", options: ["e is always added", "weight(e) is less than the maximum weight on the current MST path between e's endpoints", "e is a bridge", "Never"], answer: 1, exp: "Then swap e in and remove that heaviest path edge." },
  { id: "mst-43", topic: "algo-mst", q: "The total weight of the MST is:", options: ["Always less than the shortest path between the two farthest vertices", "The minimum possible sum of edge weights to keep the graph connected", "Equal to the number of edges", "The sum of all edge weights"], answer: 1, exp: "By definition it is the cheapest connecting subgraph (which must be a tree)." },
  { id: "mst-44", topic: "algo-mst", q: "Which data structure is central to Kruskal's efficiency?", options: ["Priority queue", "Disjoint-set union (union-find)", "Segment tree", "Hash map"], answer: 1, exp: "It answers 'are u and v already connected?' in near-constant amortized time." },
  { id: "mst-45", topic: "algo-mst", q: "The MST contains the minimum-weight edge incident to EVERY vertex:", options: ["Always true", "True — each vertex's cheapest edge is safe (min crossing edge of the cut {v} vs rest)", "Only for leaves", "Never"], answer: 1, exp: "This is why Boruvka can add all of them at once (with tie-breaking)." },
  { id: "mst-46", topic: "algo-mst", q: "Which problem is NOT solved by an MST?", options: ["Minimum cost to connect all houses with roads", "Clustering (remove the k-1 heaviest MST edges to get k clusters)", "Approximate TSP (MST-based 2-approximation)", "Single-source shortest paths"], answer: 3, exp: "Shortest paths need Dijkstra/Bellman-Ford; the MST optimizes a different objective." },
  { id: "mst-47", topic: "algo-mst", q: "The MST-based 2-approximation for metric TSP works by:", options: ["Sorting cities", "Doubling the MST edges to get an Eulerian tour, then shortcutting repeated vertices", "Running Dijkstra", "Dynamic programming"], answer: 1, exp: "Tour cost <= 2 * MST <= 2 * OPT because OPT minus an edge is a spanning tree." },
  { id: "mst-48", topic: "algo-mst", q: "Prim's and Kruskal's produce:", options: ["Different trees always", "The same total weight; the same tree if weights are distinct", "Kruskal's is always lighter", "Prim's has fewer edges"], answer: 1, exp: "Both are correct MST algorithms." },
  { id: "mst-49", topic: "algo-mst", q: "In a graph with V vertices and E edges, an MST exists iff:", options: ["E >= V", "The graph is connected", "E = V - 1", "The graph is a DAG"], answer: 1, exp: "A disconnected graph has only a spanning forest." },
  { id: "mst-50", topic: "algo-mst", q: "The classic near-linear-time MST algorithm (Chazelle) has complexity:", options: ["O(E)", "O(E alpha(E, V)) — nearly linear", "O(E log V)", "O(V^2)"], answer: 1, exp: "Whether a truly O(E) deterministic MST algorithm exists is still open; a randomized O(E) algorithm (Karger-Klein-Tarjan) is known." },

  // ================= Shortest Paths (50) =================
  { id: "sp-01", topic: "algo-shortest-paths", q: "For a graph with non-negative edge weights, single-source shortest paths are computed by:", options: ["BFS", "Dijkstra's algorithm", "Bellman-Ford only", "DFS"], answer: 1, exp: "Dijkstra greedily finalizes the closest unvisited vertex." },
  { id: "sp-02", topic: "algo-shortest-paths", q: "Dijkstra's algorithm with a binary heap runs in:", options: ["O(V^2)", "O((V + E) log V)", "O(VE)", "O(V^3)"], answer: 1, exp: "Each edge relaxation may push/decrease-key (O(log V)); each vertex extracted once." },
  { id: "sp-03", topic: "algo-shortest-paths", q: "Dijkstra's algorithm FAILS when the graph has:", options: ["Cycles", "Negative-weight edges", "Many vertices", "Parallel edges"], answer: 1, exp: "A finalized vertex could later be reached more cheaply via a negative edge, violating the greedy assumption." },
  { id: "sp-04", topic: "algo-shortest-paths", q: "Bellman-Ford runs in:", options: ["O(V + E)", "O(V log V)", "O(VE)", "O(V^3)"], answer: 2, exp: "It relaxes all E edges V-1 times." },
  { id: "sp-05", topic: "algo-shortest-paths", q: "Bellman-Ford can additionally:", options: ["Find the MST", "Detect a negative-weight cycle reachable from the source (a V-th relaxation still improves a distance)", "Run faster than Dijkstra", "Handle only DAGs"], answer: 1, exp: "If distances still decrease after V-1 passes, a negative cycle exists." },
  { id: "sp-06", topic: "algo-shortest-paths", q: "Floyd-Warshall computes:", options: ["Single-source shortest paths", "All-pairs shortest paths in O(V^3)", "The MST", "Maximum flow"], answer: 1, exp: "A DP over allowed intermediate vertices; works with negative edges (no negative cycles)." },
  { id: "sp-07", topic: "algo-shortest-paths", q: "For shortest paths in an UNWEIGHTED graph, the best method is:", options: ["Dijkstra", "BFS — O(V + E)", "Floyd-Warshall", "Bellman-Ford"], answer: 1, exp: "All edges have weight 1, so BFS layers give the distances." },
  { id: "sp-08", topic: "algo-shortest-paths", q: "For shortest paths in a weighted DAG:", options: ["Only Bellman-Ford works", "Relax edges in topological order — O(V + E), and it handles negative weights", "Dijkstra is required", "It is NP-hard"], answer: 1, exp: "Topological order guarantees a vertex is finalized before its outgoing edges are relaxed." },
  { id: "sp-09", topic: "algo-shortest-paths", q: "The relaxation step for edge (u, v) with weight w is:", options: ["if dist[u] + w < dist[v]: dist[v] = dist[u] + w; parent[v] = u", "dist[v] = w", "dist[v] += dist[u]", "swap dist[u], dist[v]"], answer: 0, exp: "It improves v's estimate if going through u is shorter." },
  { id: "sp-10", topic: "algo-shortest-paths", q: "Dijkstra's greedy invariant is:", options: ["Every vertex is visited twice", "When a vertex is extracted from the priority queue, its distance is final (shortest)", "Edges are processed in weight order", "The graph is a tree"], answer: 1, exp: "True only for non-negative weights." },
  { id: "sp-11", topic: "algo-shortest-paths", q: "Johnson's algorithm computes all-pairs shortest paths on a SPARSE graph with negative edges in:", options: ["O(V^3)", "O(V^2 log V + VE) — reweight with Bellman-Ford, then run Dijkstra from each vertex", "O(VE)", "O(V + E)"], answer: 1, exp: "It reweights edges to be non-negative using a potential function, preserving shortest paths." },
  { id: "sp-12", topic: "algo-shortest-paths", q: "A* is Dijkstra plus:", options: ["Negative edge handling", "A heuristic h(v) estimating the remaining distance to the target, prioritizing by g + h", "Two sources", "Edge sorting"], answer: 1, exp: "With an admissible/consistent h, A* finds the optimal path while expanding fewer nodes." },
  { id: "sp-13", topic: "algo-shortest-paths", q: "The number of edges on a shortest path in a graph with V vertices (no negative cycle) is at most:", options: ["V", "V - 1", "E", "2V"], answer: 1, exp: "A shortest path is simple (no repeated vertex), so at most V-1 edges — the basis for Bellman-Ford's V-1 passes." },
  { id: "sp-14", topic: "algo-shortest-paths", q: "Dijkstra with a simple array (no heap) runs in:", options: ["O(E log V)", "O(V^2 + E) = O(V^2), better for dense graphs", "O(V + E)", "O(VE)"], answer: 1, exp: "Each of V extract-min operations scans O(V)." },
  { id: "sp-15", topic: "algo-shortest-paths", q: "0-1 BFS finds shortest paths when edge weights are 0 or 1 in:", options: ["O(V^2)", "O(V + E) using a deque", "O((V+E) log V)", "O(VE)"], answer: 1, exp: "Push weight-0 relaxations to the front, weight-1 to the back." },
  { id: "sp-16", topic: "algo-shortest-paths", q: "Which is TRUE about a shortest-path TREE?", options: ["It equals the MST", "Following parent pointers from any vertex to the source gives a shortest path", "It has cycles", "It contains all edges"], answer: 1, exp: "The parent array from Dijkstra/BFS/Bellman-Ford encodes all shortest paths from the source." },
  { id: "sp-17", topic: "algo-shortest-paths", q: "If Dijkstra is run on a graph with a negative edge and it 'seems to work', it is because:", options: ["Dijkstra always works", "The particular graph/source happened to avoid the failure case; it is still incorrect in general", "Negative edges are fine if there are no cycles", "The heap fixed it"], answer: 1, exp: "Never rely on it — use Bellman-Ford / Johnson for negative edges." },
  { id: "sp-18", topic: "algo-shortest-paths", q: "The Bellman-Ford early-termination optimization stops when:", options: ["V-1 passes are done", "A full pass makes no relaxation (distances have converged)", "The source is reached", "Half the edges are relaxed"], answer: 1, exp: "If nothing changes in a pass, nothing will change later." },
  { id: "sp-19", topic: "algo-shortest-paths", q: "SPFA (Shortest Path Faster Algorithm) is:", options: ["A different algorithm from Bellman-Ford", "A queue-based optimization of Bellman-Ford — fast on average, still O(VE) worst case", "Always O(V + E)", "For non-negative weights only"], answer: 1, exp: "Only re-relax edges out of vertices whose distance changed." },
  { id: "sp-20", topic: "algo-shortest-paths", q: "Floyd-Warshall's core update is:", options: ["dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])", "dist[i][j] = dist[i][k] * dist[k][j]", "dist[i][j] = dist[i][j] + 1", "dist[i][j] = max(...)"], answer: 0, exp: "For each intermediate vertex k, see if i->k->j beats the current i->j." },
  { id: "sp-21", topic: "algo-shortest-paths", q: "To detect a negative cycle with Floyd-Warshall, check whether:", options: ["Any dist[i][j] is 0", "Any dist[i][i] < 0 after the algorithm", "All distances are positive", "The matrix is symmetric"], answer: 1, exp: "A vertex reachable to itself with negative total weight sits on a negative cycle." },
  { id: "sp-22", topic: "algo-shortest-paths", q: "Which algorithm would you use for a road network (millions of nodes, non-negative weights, one source)?", options: ["Floyd-Warshall", "Dijkstra with a heap (or A* with a distance heuristic)", "Bellman-Ford", "DFS"], answer: 1, exp: "O((V+E) log V) scales; Floyd-Warshall's O(V^3) is far too slow." },
  { id: "sp-23", topic: "algo-shortest-paths", q: "The single-pair shortest path (s to t) can sometimes stop early with Dijkstra:", options: ["Never", "Yes — halt as soon as t is extracted from the priority queue", "Only if t is the source", "Only in unweighted graphs"], answer: 1, exp: "t's distance is final once extracted; the rest of the graph need not be processed." },
  { id: "sp-24", topic: "algo-shortest-paths", q: "Reweighting an edge (u,v) as w'(u,v) = w(u,v) + h(u) - h(v) (Johnson's) preserves:", options: ["Edge weights", "The SET of shortest paths (each s-t path changes by the constant h(s) - h(t))", "The MST", "Nothing"], answer: 1, exp: "Since every s-t path shifts by the same amount, the minimum path is unchanged; choosing h as shortest distances from a super-source makes all w' >= 0." },
  { id: "sp-25", topic: "algo-shortest-paths", q: "The number of shortest paths from s to each vertex (counting) is computed by:", options: ["Dijkstra/BFS with a count array: when dist improves, count[v] = count[u]; when equal, count[v] += count[u]", "Floyd-Warshall", "DFS", "It cannot be counted"], answer: 0, exp: "Accumulate path counts along the shortest-path DAG." },
  { id: "sp-26", topic: "algo-shortest-paths", q: "Which is TRUE if a graph has a negative edge but NO negative cycle?", options: ["Dijkstra works fine", "Shortest paths are well-defined; use Bellman-Ford or (for DAGs) topological relaxation", "Shortest paths are undefined", "All distances are negative"], answer: 1, exp: "Negative cycles are the problem, not negative edges alone." },
  { id: "sp-27", topic: "algo-shortest-paths", q: "The bottleneck shortest path (minimize the maximum edge weight on the path) is found by:", options: ["Dijkstra with 'min of max' relaxation, or via the MST (max edge on the tree path)", "Bellman-Ford", "BFS", "It is NP-hard"], answer: 0, exp: "Replace 'sum' with 'max' in the relaxation; the MST path also gives the minimax edge." },
  { id: "sp-28", topic: "algo-shortest-paths", q: "The 'widest path' (maximize the minimum edge capacity) problem is solved by:", options: ["A Dijkstra/Prim variant maximizing the minimum edge along the path", "Bellman-Ford", "DFS", "DP"], answer: 0, exp: "Also known as the maximum-capacity path; used in network routing." },
  { id: "sp-29", topic: "algo-shortest-paths", q: "Which algorithm's running time does NOT depend on the edge weights (only on V and E)?", options: ["Dijkstra", "Bellman-Ford and Floyd-Warshall (O(VE) and O(V^3))", "A*", "0-1 BFS"], answer: 1, exp: "Their complexity is purely structural; Dijkstra's heap ops are also weight-independent, but BF/FW are the canonical answer here." },
  { id: "sp-30", topic: "algo-shortest-paths", q: "For all-pairs shortest paths on a DENSE graph with non-negative weights, the simplest choice is:", options: ["Floyd-Warshall, O(V^3)", "V runs of Bellman-Ford", "One BFS", "Kruskal"], answer: 0, exp: "V Dijkstras cost O(V(V+E)log V) = O(V^3 log V) for dense E; Floyd-Warshall's O(V^3) is simpler and often faster." },
  { id: "sp-31", topic: "algo-shortest-paths", q: "Dijkstra without decrease-key (lazy deletion: push duplicates, skip stale ones) has complexity:", options: ["O(V^2)", "O(E log E) = O(E log V)", "O(V + E)", "O(VE)"], answer: 1, exp: "The heap may hold up to E entries; each pop is O(log E)." },
  { id: "sp-32", topic: "algo-shortest-paths", q: "In Dijkstra, a vertex may be added to the priority queue:", options: ["Exactly once", "Multiple times (once per successful relaxation), if using the lazy approach", "Never", "V times"], answer: 1, exp: "Stale entries are discarded when popped if their distance is greater than the finalized one." },
  { id: "sp-33", topic: "algo-shortest-paths", q: "The shortest path in a graph with all edge weights equal to c is:", options: ["The path found by Dijkstra only", "The path with the fewest edges (BFS finds it), total = c * (edge count)", "Always the direct edge", "Undefined"], answer: 1, exp: "Uniform weights reduce shortest path to fewest edges." },
  { id: "sp-34", topic: "algo-shortest-paths", q: "Which is TRUE about A* with a consistent (monotone) heuristic?", options: ["It may expand a node multiple times", "Each node is expanded at most once (like Dijkstra); the f-values along any path are non-decreasing", "It is not optimal", "It needs negative edges"], answer: 1, exp: "Consistency: h(u) <= w(u,v) + h(v)." },
  { id: "sp-35", topic: "algo-shortest-paths", q: "The transitive closure of a graph (which vertices are reachable from which) is a special case of:", options: ["MST", "Floyd-Warshall with boolean OR/AND instead of min/+ (or repeated BFS/DFS)", "Dijkstra", "Topological sort"], answer: 1, exp: "reach[i][j] = reach[i][j] OR (reach[i][k] AND reach[k][j]); O(V^3), or O(V(V+E)) with V traversals." },
  { id: "sp-36", topic: "algo-shortest-paths", q: "The Viterbi algorithm (most likely hidden state sequence) is essentially:", options: ["Dijkstra on a random graph", "A shortest-path DP on a layered (trellis) DAG, using -log probabilities as weights", "Bellman-Ford", "BFS"], answer: 1, exp: "Maximizing a product of probabilities = minimizing a sum of negative log-probabilities over the trellis." },
  { id: "sp-37", topic: "algo-shortest-paths", q: "If you must answer many s-t shortest-path queries on a static graph, a good approach is:", options: ["Run Dijkstra fresh each time (fine for a few queries)", "Precompute all-pairs (Floyd-Warshall / Johnson) or use contraction hierarchies for huge graphs", "Use DFS", "Sort the edges"], answer: 1, exp: "Amortize preprocessing over many queries." },
  { id: "sp-38", topic: "algo-shortest-paths", q: "The 'k shortest paths' problem (find the k shortest s-t paths, possibly with loops) is solved by:", options: ["Running Dijkstra k times unchanged", "Yen's algorithm or a modified Dijkstra that allows up to k relaxations per vertex", "BFS", "Floyd-Warshall"], answer: 1, exp: "Yen's builds each next path by deviating from previous ones." },
  { id: "sp-39", topic: "algo-shortest-paths", q: "A negative self-loop (edge from v to v with weight < 0) means:", options: ["Nothing special", "There is a negative cycle, so shortest paths through v are -infinity (undefined)", "The graph is a DAG", "Dijkstra still works"], answer: 1, exp: "You could loop forever decreasing the cost." },
  { id: "sp-40", topic: "algo-shortest-paths", q: "Which is the shortest-path algorithm of choice for a graph with a FEW negative edges but no negative cycle, when speed matters?", options: ["Plain Bellman-Ford", "Johnson's reweighting then Dijkstra, or SPFA", "Floyd-Warshall", "BFS"], answer: 1, exp: "Reweighting lets you use fast Dijkstra." },
  { id: "sp-41", topic: "algo-shortest-paths", q: "In Dijkstra, if all you need is the distance (not the path), you can omit:", options: ["The priority queue", "The parent/predecessor array", "The distance array", "The visited check"], answer: 1, exp: "Parent pointers are only for path reconstruction." },
  { id: "sp-42", topic: "algo-shortest-paths", q: "The time to reconstruct a single shortest path from the parent array is:", options: ["O(1)", "O(path length) <= O(V)", "O(E)", "O(V log V)"], answer: 1, exp: "Walk parent[t], parent[parent[t]], ... back to s, then reverse." },
  { id: "sp-43", topic: "algo-shortest-paths", q: "Which shortest-path algorithm is a dynamic program?", options: ["Dijkstra (greedy)", "Bellman-Ford (dp over edge count) and Floyd-Warshall (dp over intermediate vertices)", "BFS", "A*"], answer: 1, exp: "Both have an explicit DP structure; Dijkstra is greedy." },
  { id: "sp-44", topic: "algo-shortest-paths", q: "A grid shortest path with obstacles and unit moves is best solved with:", options: ["Floyd-Warshall", "BFS (or A* with Manhattan distance for speed)", "Bellman-Ford", "DFS"], answer: 1, exp: "Unweighted => BFS is optimal; A* prunes toward the target." },
  { id: "sp-45", topic: "algo-shortest-paths", q: "If edge weights can be 0, Dijkstra:", options: ["Fails", "Still works correctly (0 is non-negative)", "Needs a deque", "Loops forever"], answer: 1, exp: "Non-negative includes zero; only strictly negative weights break it." },
  { id: "sp-46", topic: "algo-shortest-paths", q: "The all-pairs shortest path via repeated squaring of the weight matrix (min-plus product) runs in:", options: ["O(V^2 log V)", "O(V^3 log V)", "O(V^3)", "O(V log V)"], answer: 1, exp: "log V matrix 'multiplications', each O(V^3); Floyd-Warshall's plain O(V^3) is better." },
  { id: "sp-47", topic: "algo-shortest-paths", q: "Which statement about Dijkstra and Prim is TRUE?", options: ["They are the same algorithm", "They share the structure (priority queue, greedy extraction) but Dijkstra's key is 'distance from source', Prim's is 'edge weight to the tree'", "Prim handles negative weights", "Dijkstra builds a spanning tree that minimizes total weight"], answer: 1, exp: "Same skeleton, different relaxation quantity and objective." },
  { id: "sp-48", topic: "algo-shortest-paths", q: "The output of Bellman-Ford when a negative cycle is reachable from the source is:", options: ["The correct shortest paths", "A report that no shortest path exists (some distances are -infinity)", "An infinite loop", "The MST"], answer: 1, exp: "Distances of vertices reachable from a negative cycle are unbounded below." },
  { id: "sp-49", topic: "algo-shortest-paths", q: "The minimum number of Bellman-Ford relaxation passes to guarantee correctness (no negative cycle) is:", options: ["1", "V - 1", "V", "E"], answer: 1, exp: "A shortest path has at most V-1 edges; each pass extends correct distances by one more edge." },
  { id: "sp-50", topic: "algo-shortest-paths", q: "Which is the correct choice: single-source shortest path, non-negative weights, sparse graph?", options: ["Floyd-Warshall", "Dijkstra with a binary or Fibonacci heap", "Bellman-Ford", "Repeated matrix squaring"], answer: 1, exp: "O((V+E) log V) or O(E + V log V) — the standard, fastest general choice." }

);




